export function enemyTurn(this: GameContext, deltaTime: number) {
  const { gameState } = this;
  const hero = gameState.getHero();

  const currentIndex = gameState.combatQueue.units.findIndex(
    (enemy) => enemy.id === gameState.combatQueue.currentUnitId,
  );

  if (currentIndex >= gameState.combatQueue.units.length) {
    gameState.combatQueue.currentUnitId = hero.id;
    return;
  }

  const enemy = gameState.combatQueue.units[currentIndex];
  const enemyWeapon = enemy.getFirstAvailableWeaponInHands();

  if (enemyWeapon) {
    enemyWeapon.weapon.aimAt(hero.getRoundedPosition());
  }

  switch (true) {
    // Attack hero
    case enemy.pathQueue.points.length === 0 && enemy.getDistanceToEntity(hero) <= 1:
      enemyTurnBattle.apply(this, [deltaTime, enemy, enemyWeapon!]);
      break;

    // No more action points, next enemy turn
    case enemy.actionPoints.current === 0:
      enemyTurnNoActionPoints.apply(this, [deltaTime, enemy]);
      break;

    // Chase hero
    default:
      enemyTurnChaseHero.apply(this, [deltaTime, enemy]);
  }
}

export function heroTurnBattle(this: GameContext, deltaTime: number, hero: Unit) {
  const { terrainState, gameState, gameDispatch } = this;
  const heroWeapon = hero.getCurrentWeapon();
  const vehicleInUse = hero.getVehicleInUse();

  if (terrainState.isUnitIsInExitPoint(hero)) {
    const mapUrl = terrainState.getTerrainAreaByCoordinates(hero.position.grid).exitUrl! as mapsList;

    gameDispatch({ type: "updateMapUrl", mapUrl });
  }
  gameDispatch({ type: "animateUnitsMove", entities: [hero], deltaTime, consumeActionPoints: true });
  gameDispatch({
    type: "animateVehiclesMove",
    entities: vehicleInUse ? [vehicleInUse] : [],
    deltaTime,
    consumeActionPoints: true,
  });

  gameDispatch({ type: "animateFiredAmmo", deltaTime });
  gameDispatch({ type: "detectFiredAmmoHitsTarget" });

  for (const enemy of gameState.combatQueue.units) {
    // Mark enemy unit at gunpoint
    enemy.setAtGunpoint(
      !!heroWeapon &&
        heroWeapon.isReadyToUse(gameState) &&
        heroWeapon.getAimCoordinates()?.x === enemy.getRoundedPosition().x &&
        heroWeapon.getAimCoordinates()?.y === enemy.getRoundedPosition().y,
    );
  }
}

export function stepWorld(w: World, dt: number): void {
  // A finished match freezes rather than continuing to tick. M6 puts a result
  // screen over the top of it.
  if (w.phase !== 'playing') return;

  applyCommands(w);
  updateWaves(w, dt);
  // Shields recover before anything can shoot at them.
  updateStatuses(w, dt);
  moveCreeps(w, dt);
  // Fire before stepping: a projectile spawned this tick waits a tick before
  // moving, which is one frame of muzzle position rather than a shot that
  // teleports partway to its target the instant it appears.
  fireTowers(w, dt);
  stepProjectiles(w, dt);
  // After every system that iterates `w.creeps`, before the sweep that would
  // otherwise drop the parents the children are positioned from.
  resolveSplits(w);
  cleanup(w);

  // Checked after cleanup so the leak that emptied the life bar has already
  // been counted, and once only — the phase change stops the next tick.
  if (w.lives <= 0) {
    w.phase = 'lost';
    w.events.push({ type: 'gameOver', won: false });
  }

  w.time += dt;
  w.tick++;
}

export function renderInspector(w: World, t: Tower): string {
  const d = TOWERS[t.defId];
  const s = t.stats;
  const nextDamage = nextStats(t, 'damage', tierCeiling(w))?.damage ?? null;

  // Iconic, with **the active mode labelled** — not labels-on-hover.
  //
  // Four unlabelled glyphs would be unguessable (Strong and Close especially),
  // `title` never fires on touch, and this control mutates game state so a
  // mis-click has a cost. Naming only the selected one costs exactly one word,
  // is self-teaching — the player sees "First" beside its glyph and learns the
  // glyph — and works without a pointer. `aria-label` on all four regardless.
  const modes = TARGET_MODES.map((m) => {
    const on = t.targeting === m;
    return (
      `<button data-act="target" data-mode="${m}" class="${on ? 'on' : ''}"` +
      // No `title`: it duplicates the aria-label, and the active mode is
      // already spelled out beside its glyph — which is the affordance that
      // works without a pointer.
      ` aria-label="${TARGET_LABEL[m]}">${TARGET_GLYPH[m]}` +
      (on ? `<span>${TARGET_LABEL[m]}</span>` : '') +
      `</button>`
    );
  }).join('');

  return (
    `<div class="inspector">` +
    // Portrait column: the station wearing its real collar at full size, so the
    // board's positional upgrade code is taught here rather than by a 13px
    // afterthought on a button. The board only has to jog this memory.
    `<div class="portrait t-${t.defId}">${stationIcon(t.defId, 40)}` +
    `${collarDial(t.tiers, BALANCE.upgrade.maxTier, 56)}` +
    `<span class="mk">Mk ${'I'.repeat(visualTier(t))}</span></div>` +
    `<div class="body">` +
    `<div class="head t-${t.defId}"><b>${d.name}</b>` +
    // Tile coordinates dropped — the one fact here nobody has ever needed.
    // Damage dealt stays in the `title` rather than becoming text: this is the
    // inspector, read mid-wave, and it is held to a hard ten-word budget that
    // tools/check.ts enforces. The words go to the armed panel instead.
    `<span class="blurb" title="${Math.round(t.damageDealt)} damage dealt">` +
    `${t.kills} ${t.kills === 1 ? 'kill' : 'kills'}</span></div>` +
    // Live stats, not the def: this is where an effect purchase becomes visible
    // in numbers, including the secondary dial the upgrade card omits. One row
    // for both chip groups — the inspector's height budget has no room for two.
    `<div class="chipline t-${t.defId}">${mechanicChips(s)}${axisChips(s, false, effectiveInterval(t))}</div>` +
    renderArmourLine(w, t, nextDamage) +
    `</div>` +
    `<div class="upgrades">${renderPathButtons(w, t)}</div>` +
    `<div class="actions"><div class="seg targeting">${modes}</div>` +
    `<button class="btn" data-act="sell">Sell ${sellValue(t)}</button></div>` +
    `</div>`
  );
}

export function enemyTurnChaseHero(this: GameContext, deltaTime: number, enemy: Unit) {
  const { gameState, gameDispatch } = this;
  const hero = gameState.getHero();

  if (enemy.path.length === 0) {
    const unitPath = pathFinderBiAStar(gameState.matrix, enemy.getRoundedPosition(), hero.getRoundedPosition()); //gameState.calcMovementPath(enemy, hero.getRoundedPosition());

    unitPath.pop();

    if (unitPath.length > 0) {
      enemy.setPath(unitPath);
      enemy.setAction("run");
      gameDispatch({ type: "setUnitMovementMode", unit: enemy, mode: "run" });
      gameDispatch({ type: "setCurrentUnitAction", unit: enemy, selectedAction: "move" });
    }
  }

  gameDispatch({ type: "animateUnitsMove", entities: [enemy], deltaTime, consumeActionPoints: true });
}

export function animateUnitsMove(state: GameMap, action: AnimateUnitsMoveReducerAction) {
  let isStateChanged = false;

  for (const entity of action.entities) {
    if (entity.path.length === 0) continue;

    if (entity.isVehicleInUse()) {
      continue;
    }

    isStateChanged = true;
    state.setGridMatrixOccupancy([entity], -1);

    const entityPosition = { ...entity.position.grid };

    entity.pathQueue.points = entity.path;
    entity.pathQueue.currentPos = entity.position.grid;
    entity.pathQueue.destinationPos = entity.path[entity.path.length - 1];

    const speed = entity.getCurrentSpeed();
    const prevPoint = entity.pathQueue.moveAlong(action.deltaTime * speed);

    if (prevPoint) {
      // if (action.consumeActionPoints) {
      //   const currentSelectedAction = entity.currentSelectedAction;
      //
      //   if (currentSelectedAction === "move") {
      //     entity.consumeActionPoints(entity.actionPoints.consumption[entity.currentMovementMode]);
      //   }
      // }

      if (entity.path.length > 1 && state.isCellOccupied(entity.path[1])) {
        const unitPath = pathFinderAStar(state.matrix, entity.path[0], entity.pathQueue.destinationPos);

        entity.setPath(unitPath);

        if (unitPath.length === 0) {
          const prevPath = entity.pathQueue.points;

          prevPath.pop();

          if (prevPath.length > 1 && state.isCellOccupied(prevPath[1])) {
            while (prevPath.length > 1 && state.isCellOccupied(prevPath[1])) {
              prevPath.pop();
            }
          }

          if (prevPath.length > 1) {
            entity.setPath(entity.convertCoordinatesToPathArray(prevPath));
          } else {
            entity.clearPath();
            entity.pathQueue.points = [];
            entity.pathQueue.atEnd = true;
            entity.pathQueue.currentPos = entity.position.grid;
          }
        }
      }
    }

    if (
      entity.pathQueue.points.length > 1 &&
      getDistanceBetweenGridPoints(entity.pathQueue.currentPos, entityPosition) > 0
    ) {
      entity.setRotation(getAngleBetweenTwoGridPoints(entity.pathQueue.currentPos, entityPosition));
    }

    entity.setPosition(entity.pathQueue.currentPos, state, action.deltaTime);

    if (entity.pathQueue.atEnd) {
      entity.clearPath();
      entity.setAction("none");
      entity.pathQueue.atEnd = false;
      entity.setPositionComplete();
    }

    state.setGridMatrixOccupancy([entity], 1);
  }

  return isStateChanged ? { ...state } : state;
}

export function damageCreep(w: World, c: Creep, amount: number, source?: Tower): void {
  if (c.dead || c.hp <= 0) return;

  const def = ENEMIES[c.defId];

  // Any hit restarts the regen countdown, whether or not a shield is up. That
  // is what makes sustained fire hold a Warden's shield at zero while a gap in
  // coverage hands it back.
  c.shieldTimer = def.shieldRegenDelay;

  // Armour comes off the individual hit, before anything else can absorb it.
  // Splash arrives here too, which is deliberate — the falloff edge of a
  // detonation is a small hit and armour treats it like one.
  const effective = effectiveDamage(amount, def.armor);

  // Shield absorbs next, and the overflow carries into the hull — so a single
  // heavy shot is not wasted on a thin shield the way it would be if the shield
  // simply ate the whole hit.
  let toHull = effective;
  let toShield = 0;
  if (c.shield > 0) {
    toShield = Math.min(c.shield, toHull);
    c.shield -= toShield;
    toHull -= toShield;
    if (c.shield === 0) w.events.push({ type: 'shieldBroke', x: c.x, y: c.y });
  }

  // Credit shield and hull alike, but never more than was actually there, so
  // overkill on a 2hp creep doesn't inflate a tower's damage figure.
  const landed = Math.min(effective, effective - toHull + c.hp);
  c.hp -= toHull;

  if (source !== undefined) source.damageDealt += landed;
  w.events.push({
    type: 'creepDamaged',
    id: c.id,
    x: c.x,
    y: c.y,
    amount: landed,
    toShield,
    defId: source?.defId ?? null,
  });

  if (c.hp > 0) return;

  c.dead = true;
  // Paid to whoever's board this is, which for a sortie means the *defender*
  // collects. That is the whole anti-spam valve of the duel economy and it
  // needs no code of its own: bounty has always been credited to the world the
  // contact died in, and a sortie dies in the world it was sent to.
  w.money += c.bounty;
  w.stats.kills++;
  w.stats.bounty += c.bounty;

  // Run totals count every kill; the per-wave itemisation counts only what the
  // wave machine dispatched. A sortie has no wave to be itemised against, and
  // charging it to whichever wave happened to be spawning would put kills in a
  // clear summary that the wave never contained.
  if (c.origin === 'wave') {
    const wave = waveStats(w, c.wave);
    wave.kills++;
    wave.bounty += c.bounty;
  }

  if (source !== undefined) source.kills++;
  w.events.push({ type: 'creepKilled', x: c.x, y: c.y, bounty: c.bounty, defId: c.defId });

  // Queued, never spawned here. `stepProjectiles` is iterating `w.creeps` when
  // this runs, and a push mid-iteration would let the very shot that made the
  // kill also strike a child that did not exist when it was fired.
  const split = ENEMIES[c.defId].splitInto;
  if (split !== null) {
    w.pendingSplits.push({ parent: c, into: split.enemy as EnemyId, count: split.count });
  }
}

export function recalculateUnitDistanceToScreenCenter(
  state: GameMap,
  action: RecalculateUnitDistanceToScreenCenterReducerAction,
): GameMap {
  if (state.mapSize.width === 0) return state;

  const { unit, viewport, scroll } = action;

  const screenCenter = (viewport.screen.x2 - viewport.screen.x1) / 2;
  const heroScreenX =
    gridToScreenSpace(unit.position.grid, state.mapSize).x - scroll.x + constants.wireframeTileSize.width / 2;
  const distance = ((heroScreenX * 100) / screenCenter - 100) / 100;

  if (distance < Infinity) {
    unit.setDistanceToScreenCenter(distance);
  }

  return state;
}

export function moveUnit(state: GameMap, action: MoveUnitReducerAction): GameMap {
  const unit = action.unit;

  if (unit.path.length > 0) {
    state.deOccupyCell(unit.position.grid);

    unit.path.forEach((pathPoint) => {
      state.deOccupyCell(pathPoint);
    });

    unit.clearPath();
    unit.pathQueue.distAlong = 0;
    unit.pathQueue.totalDistMoved = 0;
    unit.pathQueue.points = [];
    unit.pathQueue.atEnd = false;
    unit.pathQueue.currentPos = unit.position.grid;
  }

  const unitPath = state.calcMovementPath(unit.position.grid, action.position);

  if (unitPath.length > 0) {
    unit.setPath(unitPath);
    unit.setAction(action.moveAction);

    unit.setPathCompleteCallback(action.onUnitMoveFinished || null);
  }

  return { ...state };
}

export function getOutOfVehicle(state: GameMap, action: GetOutOfVehicleReducerAction) {
  const vehicle = action.unit.getVehicleInUse();

  if (!vehicle) return state;

  const { unit } = action;

  unit.getOutOfVehicle();
  unit.currentSelectedAction = "move";
  unit.setPosition(
    {
      x: vehicle.position.grid.x - vehicle.size.grid.width / 2,
      y: vehicle.position.grid.y - vehicle.size.grid.length / 2,
    },
    state,
  );
  unit.setRotation(vehicle.rotation);

  vehicle.unAssignDriver();
  vehicle.clearPath();
  state.setGridMatrixOccupancy([unit], 1);

  const idleSfx = vehicle.currentPlayingSfx["idle"];

  if (idleSfx) {
    const turnOffSfx = state.createSfx([vehicle.dictEntity.sfx["turnOff"].src], 1);

    turnOffSfx?.start();

    window.setTimeout(() => {
      idleSfx.stop();
      delete vehicle.currentPlayingSfx["idle"];
    }, 100);
  }

  return { ...state };
}

export function detectFiredAmmoHitsTarget(state: GameMap) {
  state.ammoFiredIds.forEach((ammoId) => {
    const ammo = state.getAmmoById(ammoId);

    if (ammo && ammo.isTargetReached) {
      const weapon = ammo.loadedInWeapon!;
      const shooter = weapon.owner as Unit;
      const weaponBlastDamage = weapon?.getCurrentAttackModeDetails().blastRadius;
      const blastDamage = calcBlastDamage(
        ammo.position.grid,
        weaponBlastDamage || 0,
        calcDamage(shooter, weapon, ammo),
      );

      const unitsAtTargetArea = state.getUnitsByCoordinatesInRadius(ammo.position.grid, weaponBlastDamage);

      for (const unit of unitsAtTargetArea) {
        if (unit.isDead || !weapon) continue;

        const { x, y } = unit.getRoundedPosition();
        const damage = blastDamage[`${x}:${y}`];

        if (damage) {
          unit.takeDamage(damage, state);
        }

        if (unit.isDead) {
          shooter.characteristics.earnXp(unit.dictEntity.rewardXpPoints);
          state.deOccupyCell(unit.getRoundedPosition());
          unit.blocksRays = false;
        }
      }
    }
  });

  return state;
}

export function animateVehiclesMove(state: GameMap, action: AnimateVehiclesMoveReducerAction) {
  let isStateChanged = false;

  for (const vehicle of action.entities) {
    if (vehicle.path.length === 0 || vehicle.speed.current === 0) continue;

    isStateChanged = true;
    state.setGridMatrixOccupancy([vehicle], -1);

    const entityPosition = { ...vehicle.position.grid };

    if (vehicle.isCollisionDetected()) {
      vehicle.setPosition(calcCollisionRollbackPosition(vehicle), state);
      vehicle.setRotation(normalizeRotation(vehicle.realRotation.deg, 4));

      vehicle.stop();
      vehicle.setAction("collision");

      state.setGridMatrixOccupancy([vehicle], 1);

      continue;
    }

    vehicle.pathQueue.points = vehicle.path;
    vehicle.pathQueue.currentPos = vehicle.position.grid;
    vehicle.pathQueue.destinationPos = vehicle.path[vehicle.path.length - 1];

    const speed = vehicle.getCurrentSpeed();
    const prevPoint = vehicle.pathQueue.moveAlong(action.deltaTime * speed);

    if (prevPoint) {
      vehicle.setPosition(prevPoint, state);
    }

    if (getDistanceBetweenGridPoints(vehicle.pathQueue.currentPos, entityPosition) > 0) {
      const reverseAngle = vehicle.gearShiftMode === "reverse" ? 180 : 0;
      const angle = getAngleBetweenTwoGridPoints(vehicle.pathQueue.currentPos, entityPosition, undefined, reverseAngle);

      vehicle.setRotation(angle);
    }

    vehicle.setPosition(vehicle.pathQueue.currentPos, state);

    if (vehicle.pathQueue.atEnd) {
      vehicle.stop();

      vehicle.setPositionComplete();
    }

    state.setGridMatrixOccupancy([vehicle], 1);
  }

  return isStateChanged ? { ...state } : state;
}

function renderBox(entity: Building | Unit | Vehicle) {
      const x = entity.position.grid.x * wireframeTileWidth * miniMapZoom;
      const y = entity.position.grid.y * wireframeTileHeight * miniMapZoom;
      const z = 0;

      const width = entity.size.grid.width * wireframeTileWidth * miniMapZoom;
      const length = entity.size.grid.length * wireframeTileHeight * miniMapZoom;
      const height = entity.size.grid.height * wireframeTileHeight * miniMapZoom;

      const frontTopRight = isoTransform(x + width, y, z);
      const frontBottomLeft = isoTransform(x, y + length, z);
      const frontBottomRight = isoTransform(x + width, y + length, z);

      const backTopLeft = isoTransform(x, y, z + height);
      const backTopRight = isoTransform(x + width, y, z + height);
      const backBottomLeft = isoTransform(x, y + length, z + height);
      const backBottomRight = isoTransform(x + width, y + length, z + height);

      const baseColor = gameState.isEntityVisibleByHero(entity) ? entity.internalColor : "#ffffff";

      const colors = {
        right: darkenLightenColor(baseColor, -25),
        top: baseColor,
        bottom: darkenLightenColor(baseColor, 25),
      };

      // Draw top face
      ctx.fillStyle = colors.top;
      ctx.beginPath();
      ctx.moveTo(backTopLeft.x, backTopLeft.y);
      ctx.lineTo(backTopRight.x, backTopRight.y);
      ctx.lineTo(backBottomRight.x, backBottomRight.y);
      ctx.lineTo(backBottomLeft.x, backBottomLeft.y);
      ctx.closePath();
      ctx.fill();

      // Draw right face
      ctx.fillStyle = colors.right;
      ctx.beginPath();
      ctx.moveTo(frontTopRight.x, frontTopRight.y);
      ctx.lineTo(backTopRight.x, backTopRight.y);
      ctx.lineTo(backBottomRight.x, backBottomRight.y);
      ctx.lineTo(frontBottomRight.x, frontBottomRight.y);
      ctx.closePath();
      ctx.fill();

      // Draw bottom face
      ctx.fillStyle = colors.bottom;
      ctx.beginPath();
      ctx.moveTo(frontBottomLeft.x, frontBottomLeft.y);
      ctx.lineTo(frontBottomRight.x, frontBottomRight.y);
      ctx.lineTo(backBottomRight.x, backBottomRight.y);
      ctx.lineTo(backBottomLeft.x, backBottomLeft.y);
      ctx.closePath();
      ctx.fill();
    }

export function useTerrainAreas(terrainState: GameTerrain, gameState: GameMap, uiState: GameUI) {
  const { getEditorLibraryPosition } = useEditor();

  const tileWidth = constants.tileSize.width;
  const tileHeight = constants.tileSize.height;

  const mapWidth = gameState.mapSize.width;
  const mapHeight = gameState.mapSize.height;

  const entityLibraryWidth = getEditorLibraryPosition();

  const renderTerrainTiles = (ctx: CanvasRenderingContext2D) => {
    if (!ctx) return;

    ctx.resetTransform();
    ctx.clearRect(0, 0, mapWidth * tileWidth, mapHeight * tileHeight);
    ctx.setTransform(1, 0, 0, 1, -uiState.scroll.x + entityLibraryWidth, -uiState.scroll.y);

    Object.values(uiState.viewport.visibleCells).forEach((coordinates) => {
      const terrainTile = terrainState.getTerrainTileByCoordinates(coordinates);

      if (terrainTile) {
        const image = gameState.getAssetImage(terrainTile.type)?.source;

        if (image) {
          ctx.drawImage(
            image,
            tileWidth * (terrainTile.backgroundPosition.x || 0) + (terrainTile.backgroundPosition.x || 0) * 3 + 1,
            tileHeight * (terrainTile.backgroundPosition.y || 0) + (terrainTile.backgroundPosition.y || 0) * 3 + 1,
            terrainTile.size.screen.width,
            terrainTile.size.screen.height,
            terrainTile.position.screen.x,
            terrainTile.position.screen.y,
            terrainTile.size.screen.width,
            terrainTile.size.screen.height,
          );
        }

        if (terrainTile.isMapExit) {
          const position = terrainTile.position.grid;

          const tl = gridToScreenSpace(position, gameState.mapSize);
          const tr = gridToScreenSpace({ x: position.x + 1, y: position.y }, gameState.mapSize);
          const br = gridToScreenSpace({ x: position.x + 1, y: position.y + 1 }, gameState.mapSize);
          const bl = gridToScreenSpace({ x: position.x, y: position.y + 1 }, gameState.mapSize);

          ctx.fillStyle = "rgba(0,255,0, .2)";
          ctx.beginPath();
          ctx.moveTo(tl.x + tileWidth / 2, tl.y);
          ctx.lineTo(tr.x + tileWidth / 2, tr.y);
          ctx.lineTo(br.x + tileWidth / 2, br.y);
          ctx.lineTo(bl.x + tileWidth / 2, bl.y);
          ctx.closePath();

          ctx.fill();
        }
      }
    });
  };

  return { renderTerrainTiles };
}

export class Shoot extends BaseState {
	update() {
		this.shoot();
		this.entity.addVFX('TowerShoot');
		this.entity.state.setState('Guard');
	}

	shoot() {
		const stageManager = managers.get('stageManager');
		const { spawner } = this.stateMachine.context;
		const projectileType = spawner.stats.projectileType;
		const projectileNumber = this.entity.stats.projectileNumber;
		// use upgradeLvl

		const towerShootPoint = spawner.position.add(new Vector2(spawner.width / 2, 0));

		const entityManager = managers.get('entityManager');
		const targets = entityManager.findNearestEntities(
			spawner,
			entityManager.enemies,
			projectileNumber
		);
		targets.forEach((target) => {
			stageManager.spawnEntity(projectileType, towerShootPoint, {
				spawner,
				target
			});
		});

		soundManager.play('towerShoot');
	}
}

export class LootTracker {
	collectedLoot = $state(100);
	playLowLootAnimation = $state(false);
	playTowerUpgradeAnimation = $state(false);
	playEnemyClickAnimation = $state(false);
	score = $state(100);
	killsEnemy = $state(0);

	spendLoot(action) {
		const toSpend = LOOT_MAP[action.type];

		if (this.collectedLoot < toSpend) {
			this.playAnimation('LowLoot');
			// soundManager.play('lowResourse');
			return;
		}

		if (action.type === 'upgrade') {
			const { tower } = action.payload;
			this.collectedLoot -= toSpend;

			tower.state.setState('Upgrade');
			this.playAnimation('TowerUpgrade');

			cursor.setAnimation('TowerBuildCursor');
		} else if (action.type === 'click') {
			const { collisionManager, stageManager } = managers.get(['collisionManager', 'stageManager']);
			const { offset } = action.payload;

			const boundingBox = boundingBoxFromPoint(offset, 60, 60);
			const enemies = collisionManager.filterEnemiesByBounds(boundingBox);

			stageManager.spawnEntity('ClickExplode', offset);
			soundManager.play('clickEnemy', true);

			enemies.forEach((enemy) => {
				enemy.state.setState('Die');
			});

			if (enemies.length > 0) {
				this.collectedLoot -= toSpend;
			}
		}
	}

	receiveLoot(loot) {
		this.collectedLoot += loot;
		this.score += loot;
		this.killsEnemy++;
	}
	reset() {
		this.collectedLoot = 100;
		this.killsEnemy = 0;
	}

	getAnimation(name) {
		return `play${name}Animation`;
	}

	playAnimation(name) {
		const animation = this.getAnimation(name);
		this[animation] = true;
	}

	unsetAnimation(name) {
		const animation = this.getAnimation(name);
		this[animation] = false;
	}
}

