export class ProjectileManager {
  private projectiles: Projectile[] = [];
  private group: Group;
  private impactHandler: ImpactHandler;
  private effectManager: EffectManager | null = null;
  private pool = new ObjectPool<Projectile>(() => new Projectile());

  constructor(group: Group, enemyManager: EnemyManager) {
    this.group = group;
    this.impactHandler = new ImpactHandler(enemyManager);
  }

  setEffectManager(em: EffectManager): void {
    this.effectManager = em;
    this.impactHandler.setEffectManager(em);
  }

  spawn(
    x: number,
    y: number,
    z: number,
    target: Enemy,
    config: TowerConfig,
  ): Projectile {
    const projectile = this.pool.acquire();
    projectile.reset(x, y, z, target, config);
    this.projectiles.push(projectile);
    this.group.add(projectile.getObject3D());
    return projectile;
  }

  update(delta: number): void {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.update(delta);
      if (!p.alive) {
        if (p.impactPosition) {
          this.impactHandler.handleImpact(p);
          if (this.effectManager) {
            this.effectManager.spawnImpactFlash(
              p.impactPosition.x,
              p.impactPosition.y,
              p.impactPosition.z,
              p.towerConfig.projectileColor,
            );
          }
        }
        this.group.remove(p.getObject3D());
        this.pool.release(p);
        this.projectiles[i] = this.projectiles[this.projectiles.length - 1];
        this.projectiles.pop();
      }
    }
  }

  dispose(): void {
    for (const p of this.projectiles) {
      this.group.remove(p.getObject3D());
    }
    this.projectiles = [];
    this.pool.disposeAll((p) => p.dispose());
  }
}

export class Projectile extends GameObject {
  private mesh: Mesh;
  private material: MeshStandardMaterial;
  private _impactPos = new Vector3();
  private _lastTargetPos = new Vector3();
  damage!: number;
  speed!: number;
  towerConfig!: TowerConfig;
  target!: Enemy;
  alive = true;
  impactPosition: Vector3 | null = null;
  /** True when the projectile reached its destination but the target was already dead/gone. */
  targetWasDeadOnImpact = false;

  constructor() {
    super();
    this.material = new MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xffffff,
      emissiveIntensity: 0.5,
    });
    this.mesh = new Mesh(PROJECTILE_GEO, this.material);
    this.object3D = this.mesh;
  }

  reset(
    x: number,
    y: number,
    z: number,
    target: Enemy,
    config: TowerConfig,
  ): void {
    this.target = target;
    this.damage = config.damage;
    this.speed = config.projectileSpeed;
    this.towerConfig = config;
    this.alive = true;
    this.impactPosition = null;
    this.targetWasDeadOnImpact = false;
    this.material.color.set(config.projectileColor);
    this.material.emissive.set(config.projectileColor);
    this.mesh.position.set(x, y, z);

    // Snapshot initial target position
    const targetPos = target.getObject3D().position;
    this._lastTargetPos.set(targetPos.x, targetPos.y, targetPos.z);
  }

  update(delta: number): void {
    if (!this.alive) return;

    const targetDead = !this.target.alive || this.target.reachedGoal;

    // Determine destination: live target position, or last known position if target is dead
    let destX: number;
    let destY: number;
    let destZ: number;

    if (targetDead) {
      // Target died in flight -- fly to last known position
      destX = this._lastTargetPos.x;
      destY = this._lastTargetPos.y + this.target.config.radius;
      destZ = this._lastTargetPos.z;
    } else {
      // Target alive -- track it and update last known position
      const targetPos = this.target.getObject3D().position;
      this._lastTargetPos.set(targetPos.x, targetPos.y, targetPos.z);
      destX = targetPos.x;
      destY = targetPos.y + this.target.config.radius;
      destZ = targetPos.z;
    }

    const dx = destX - this.mesh.position.x;
    const dy = destY - this.mesh.position.y;
    const dz = destZ - this.mesh.position.z;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

    const step = this.speed * delta;

    if (dist <= step + 0.15) {
      // Arrived at destination -- store impact position at ground level
      this._impactPos.set(this._lastTargetPos.x, this._lastTargetPos.y, this._lastTargetPos.z);
      this.impactPosition = this._impactPos;
      this.targetWasDeadOnImpact = targetDead;
      this.alive = false;
    } else {
      this.mesh.position.x += (dx / dist) * step;
      this.mesh.position.y += (dy / dist) * step;
      this.mesh.position.z += (dz / dist) * step;
    }
  }

  dispose(): void {
    this.material.dispose();
  }
}

export function useGameEntityInteraction() {
  const { gameState, uiState, uiDispatch } = useGameState();

  const handleEntityMouseMove = (e: React.MouseEvent, entity: Unit | Building | Vehicle) => {
    e.stopPropagation();
    e.preventDefault();

    const entityGridPosition = gameState.getClosestCoordinatesOfEntity(gameState.getHero(), entity); //entity.getRoundedPosition();

    if (
      uiState.mousePosition.grid.x === entityGridPosition.x &&
      uiState.mousePosition.grid.y === entityGridPosition.y
    ) {
      return;
    }

    uiDispatch({
      type: "setMousePosition",
      mousePosition: {
        grid: entityGridPosition,
        screen: gridToScreenSpace(entityGridPosition, gameState.mapSize),
        browser: { x: 0, y: 0 },
        isOutOfGrid: false,
      },
    });
  };

  return { handleEntityMouseMove };
}

export class ProjectileAmmo extends Ammo {
  private readonly _MAX_HEIGHT: number;
  private readonly _EXPONENT = 2.5;
  private velocity = { x: Infinity, y: Infinity, z: Infinity };
  private _timeElapsed = 0;
  private _timeToReachTarget = 0;
  constructor(ammoName: AmmoName, ammoDictEntity: AmmoDictEntity) {
    super(ammoName, ammoDictEntity);

    this._MAX_HEIGHT = Math.pow(this.dictEntity.speed, this._EXPONENT);
  }

  updatePosition(deltaTime: number, gameState: GameMap) {
    if (
      this._timeElapsed >= this._timeToReachTarget ||
      (this.position.grid.x === this.targetPosition.grid.x && this.position.grid.y === this.targetPosition.grid.y)
    ) {
      this.isTargetReached = true;
      this.position = this.targetPosition;

      return;
    }

    const newPositionScreen = this.convert2DToIso(
      this.velocity.x * this._timeElapsed,
      this.velocity.y * this._timeElapsed,
      this.velocity.z * this._timeElapsed -
        (constants.GRAVITY_ACCELERATION * this._MAX_HEIGHT * Math.pow(this._timeElapsed, this._EXPONENT)) / 2,
    );

    const newPosition = {
      x: this.startPosition.screen.x + newPositionScreen.x,
      y: this.startPosition.screen.y + newPositionScreen.y,
    };

    this.position = {
      grid: screenToGridSpace(newPosition, gameState.mapSize),
      screen: newPosition,
    };

    this._timeElapsed += deltaTime;
  }

  shot(initialCoordinates: GridCoordinates, targetCoordinates: GridCoordinates, gameState: GameMap) {
    super.shot(initialCoordinates, targetCoordinates, gameState);

    const positionEnd = {
      x: this.targetPosition.screen.x - this.startPosition.screen.x,
      y: (this.targetPosition.screen.y - this.startPosition.screen.y) * 2,
    };

    const distance = Math.sqrt(positionEnd.x ** 2 + positionEnd.y ** 2);

    this._timeToReachTarget = distance / this.dictEntity.speed / 100;

    this.velocity = {
      x: positionEnd.x / this._timeToReachTarget,
      y: positionEnd.y / this._timeToReachTarget,
      z:
        (constants.GRAVITY_ACCELERATION * this._MAX_HEIGHT * Math.pow(this._timeToReachTarget, this._EXPONENT)) /
        2 /
        this._timeToReachTarget,
    };
  }
}

export function useCanvas() {
  const { gameState } = useGameState();

  const mapWidth = gameState.mapSize.width;
  const mapHeight = gameState.mapSize.height;

  const wireframeTileWidth = constants.wireframeTileSize.width;
  const wireframeTileHeight = constants.wireframeTileSize.height;

  const clearCanvas = (ctx: CanvasRenderingContext2D) => {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, mapWidth * wireframeTileWidth, mapHeight * wireframeTileHeight);
  };

  const drawCircle = (
    ctx: CanvasRenderingContext2D,
    position: GridCoordinates,
    color = "#ffffff",
    fillStyle?: CanvasGradient | string,
    lineWidth = 1,
    radius = wireframeTileWidth / 2,
  ) => {
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    if (fillStyle) ctx.fillStyle = fillStyle;
    ctx.arc(
      position.x * wireframeTileWidth + wireframeTileWidth / 2 + 0.5,
      position.y * wireframeTileHeight + wireframeTileHeight / 2 + 0.5,
      radius,
      0,
      2 * Math.PI,
    );
    if (lineWidth > 0) ctx.stroke();
    if (fillStyle) ctx.fill();
  };

  const drawFillRect = (
    ctx: CanvasRenderingContext2D,
    position: GridCoordinates,
    color = "#ffffff",
    lineWidth = 1,
    size = { width: 1, length: 1, height: 1 } as Size3D,
  ) => {
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.beginPath();
    ctx.fillRect(
      position.x * wireframeTileWidth,
      position.y * wireframeTileHeight,
      size.width * wireframeTileWidth,
      size.length * wireframeTileHeight,
    );
    ctx.stroke();
  };

  const drawRect = (
    ctx: CanvasRenderingContext2D,
    position: GridCoordinates,
    color = "#ffffff",
    lineWidth = 1,
    size = { width: wireframeTileWidth, height: wireframeTileHeight } as Size2D,
  ) => {
    ctx.beginPath();
    ctx.rect(position.x * wireframeTileWidth, position.y * wireframeTileHeight, size.width, size.height);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  };

  const drawLine = (
    ctx: CanvasRenderingContext2D,
    from: GridCoordinates,
    to: GridCoordinates,
    color = "rgba(255,255,255, 0.5)",
  ) => {
    ctx.beginPath();
    ctx.moveTo(from.x * wireframeTileWidth + 0.5, from.y * wireframeTileWidth + 0.5);
    ctx.lineTo(to.x * wireframeTileHeight + 0.5, to.y * wireframeTileHeight + 0.5);
    ctx.fillStyle = color;
    ctx.fill();
  };

  return {
    clearCanvas,
    drawCircle,
    drawFillRect,
    drawRect,
    drawLine,
  };
}

function createInitialContext(): ZhitheadContext {
  const shuffledDeck = shuffle(createDeck());
  const [deck, [human, bot]] = dealCardsFor(2, shuffledDeck);

