export function deckKey(w: World, ui: UiState, inspected: Tower | undefined): string {
  if (!ui.deckOpen) return 'c';

  const s = w.wave;
  return [
    'o',
    ui.selected ?? '-',
    inspected
      ? `${inspected.id}:${inspected.tiers.damage}${inspected.tiers.range}${inspected.tiers.effect}:${inspected.targeting}:${inspected.kills}`
      : '-',
    // Affordability of every slot, plus the two buttons the inspector prices.
    w.money,
    // Which slots are locked, and the ceiling the upgrade buttons price against.
    // Also which sortie cards are open, and — via `s.index` below — what they
    // cost, since a sortie is priced off the wave it would be sent into.
    w.era,
    ui.sortieLane,
    s.index,
    s.phase,
    Math.ceil(s.timer),
    // The inspector prices the armed station against this, and while the deck
    // is open nothing else in this key changes when the last Bulwark dies.
    inspected ? (toughestArmour(w)?.defId ?? '-') : '',
  ].join('|');
}

function act(action: string, data: DOMStringMap): void {
    switch (action) {
      case 'arm': {
        const id = data['id'] as TowerId;
        ui.selected = ui.selected === id ? null : id;
        if (ui.selected !== null) ui.inspecting = null;
        break;
      }
      case 'send':
        ports.dispatch({ type: 'startWave' });
        break;
      case 'era':
        ports.dispatch({ type: 'advanceEra' });
        break;
      case 'lane':
        ui.sortieLane = Number(data['v']);
        break;
      case 'sortie':
        ports.dispatch({
          type: 'sortie',
          sortie: data['id'] as SortieId,
          lane: ui.sortieLane,
        });
        break;
      case 'deck':
        ui.deckOpen = !ui.deckOpen;
        break;
      case 'speed':
        ports.speed.set(Number(data['v']));
        break;
      case 'pause':
        ports.togglePause();
        break;
      case 'restart':
        ports.restart();
        break;
      case 'menu':
        ports.campaign?.menu();
        break;
      case 'next':
        ports.campaign?.next();
        break;
      case 'upgrade':
        if (ui.inspecting !== null) {
          ports.dispatch({
            type: 'upgradeTower',
            id: ui.inspecting,
            path: data['path'] as UpgradePath,
          });
        }
        break;
      case 'sell':
        if (ui.inspecting !== null) {
          ports.dispatch({ type: 'sellTower', id: ui.inspecting });
          ui.inspecting = null;
        }
        break;
      case 'target':
        if (ui.inspecting !== null) {
          ports.dispatch({
            type: 'setTargeting',
            id: ui.inspecting,
            mode: data['mode'] as TargetMode,
          });
        }
        break;
      case 'pref-reach':
        ui.prefs.reachCircles = data['v'] === 'always' ? 'always' : 'hover';
        break;
      case 'pref-damage':
        ui.prefs.damageNumbers = data['v'] === 'on';
        break;
      case 'pref-stream':
        ui.prefs.stream = data['v'] === 'on';
        break;
      case 'pref-sound': {
        // Four steps, not a slider. A slider is a drag target the size of a
        // fingertip on the compact layout, and "off / quiet / normal / loud" is
        // the whole range anyone actually wants from a game's master volume.
        const v = data['v'];
        ui.prefs.muted = v === 'off';
        if (v === 'low') ui.prefs.volume = 0.3;
        else if (v === 'mid') ui.prefs.volume = 0.6;
        else if (v === 'high') ui.prefs.volume = 1;
        saveAudioPrefs(ui.prefs);
        ports.audio?.apply(ui.prefs);
        break;
      }
    }
  }

export class BattleAction {
    constructor(
        public type: BattleActionType,
        public path: Coords[],
        public step: number = 0,
        public stepDuration: number = 0,
        public remainingTime: number = 0,
        public sourceUnit?: Creature,
        public targetUnit?: Creature
    ) {
    }

    static create(
        type: BattleActionType,
        path: Coords[],
        data: {
            step: number,
            stepDuration: number,
            remainingTime: number,
            sourceUnit: Creature | undefined,
            targetUnit: Creature | undefined
        } = { step: 0, stepDuration: 0, remainingTime: 0, sourceUnit: undefined, targetUnit: undefined }
    ): BattleAction {
        return new BattleAction(type, path, data.step, data.stepDuration, data.remainingTime, data.sourceUnit, data.targetUnit);
    }

    static CreateAttackMelee(source: Creature, target: Creature): BattleAction {
        return new BattleAction(BattleActionType.ATTACK_MELEE, [target.pos], 0, 500, 50, source, target);
    }

    static CounterAttack(source: Creature, target: Creature): BattleAction {
        return new BattleAction(BattleActionType.COUNTER_ATTACK_MELEE, [], 0, 500, 50, source, target);
    }
}

export class TowerTooltip extends UIComponent {
  constructor() {
    super("div");

    this.root.className = "tooltip-base";
    document.body.appendChild(this.root);
  }

  showFor(config: TowerConfig, anchorEl: HTMLElement): void {
    this.root.innerHTML = "";

    const dps = (config.damage * config.fireRate).toFixed(1);

    // Title
    const title = document.createElement("div");
    title.className = "font-bold text-[13px] mb-1";
    title.textContent = config.name;

    // Stats table
    const stats: string[] = [
      `Damage: ${config.damage}  |  Rate: ${config.fireRate}/s`,
      `DPS: ${dps}  |  Range: ${config.range}`,
    ];

    if (config.splashRadius) {
      stats.push(`Splash: ${config.splashRadius}m radius`);
    }
    if (config.slowFactor != null && config.slowDuration != null) {
      const pct = Math.round((1 - config.slowFactor) * 100);
      stats.push(`Slow: ${pct}% for ${config.slowDuration}s`);
    }
    if (config.chainCount) {
      stats.push(`Chain: ${config.chainCount} targets (${Math.round((config.chainDamageFalloff ?? 0.7) * 100)}% per hop)`);
    }
    if (config.poisonDamage != null && config.poisonDuration != null) {
      stats.push(`Poison: ${config.poisonDamage}/tick for ${config.poisonDuration}s (max ${config.poisonMaxStacks ?? 1} stacks)`);
    }
    if (config.isPulse) {
      stats.push("AoE pulse (no projectile)");
    }
    if (config.canTargetFlying === false) {
      stats.push("Cannot target flying");
    }

    this.root.appendChild(title);
    for (const line of stats) {
      const div = document.createElement("div");
      div.className = "text-game-gray-lighter";
      div.textContent = line;
      this.root.appendChild(div);
    }

    // Position above anchor (fall back to below if not enough room)
    const rect = anchorEl.getBoundingClientRect();
    this.root.style.display = "block";
    const tipRect = this.root.getBoundingClientRect();

    // Horizontal: center on anchor, clamp to viewport
    let left = rect.left + rect.width / 2 - tipRect.width / 2;
    left = Math.max(4, Math.min(left, window.innerWidth - tipRect.width - 4));
    this.root.style.left = `${left}px`;

    // Vertical: prefer above anchor, fall back to below
    const spaceAbove = rect.top - 6;
    if (spaceAbove >= tipRect.height) {
      this.root.style.bottom = `${window.innerHeight - rect.top + 6}px`;
      this.root.style.top = "";
    } else {
      const top = rect.bottom + 6;
      // Clamp so tooltip doesn't go below viewport
      const maxTop = window.innerHeight - tipRect.height - 4;
      this.root.style.top = `${Math.min(top, maxTop)}px`;
      this.root.style.bottom = "";
    }
  }

  hideTooltip(): void {
    this.root.style.display = "none";
  }

  dispose(): void {
    this.root.remove();
  }
}

export function heroTurn(this: GameContext, deltaTime: number) {
  const { gameState } = this;
  const hero = gameState.getHero();

  if (gameState.combatQueue.units.length === 0) {
    return heroTurnNoEnemies.apply(this);
  }

  if (hero.actionPoints.current === 0) {
    return heroTurnNoActionPoints.apply(this);
  }

  heroTurnBattle.apply(this, [deltaTime, hero]);
}

export function pathFinderBiAStar(matrix: GameMap["matrix"], fromPos: GridCoordinates, toPos: GridCoordinates) {
  const grid = new pathfinding.Grid(matrix);
  const finder = new pathfinding.BiAStarFinder({
    diagonalMovement: pathfinding.DiagonalMovement.Never,
    heuristic: pathfinding.Heuristic.euclidean,
  });

  return finder.findPath(Math.round(fromPos.x), Math.round(fromPos.y), Math.round(toPos.x), Math.round(toPos.y), grid);
}

export function pathFinderAStar(
  matrix: GameMap["matrix"],
  fromPos: GridCoordinates,
  toPos: GridCoordinates,
  diagonalMovement: pathfinding.DiagonalMovement = pathfinding.DiagonalMovement.Never,
) {
  const grid = new pathfinding.Grid(matrix);
  const finder = new pathfinding.AStarFinder({
    diagonalMovement: diagonalMovement,
    heuristic: pathfinding.Heuristic.euclidean,
  });

  return finder.findPath(Math.round(fromPos.x), Math.round(fromPos.y), Math.round(toPos.x), Math.round(toPos.y), grid);
}

export function setUnitDead(state: GameMap, action: SetUnitDeadReducerAction): GameMap {
  const entity = state.getUnitById(action.entityId);

  if (entity) {
    entity.isDead = action.isDead;
    entity.blocksRays = !action.isDead;
    entity.setAction(action.isDead ? "dead" : "none");

    if (action.isDead) {
      state.deOccupyCell(entity.position.grid);
      entity.clearShadows();
    } else {
      state.occupyCell(entity.position.grid);
      entity.characteristics.derived.healthPoints.value = entity.characteristics.derived.healthPoints.max;
      entity.calcShadows(state);
    }

    return { ...state };
  }

  return state;
}

export function recalculateUnitFieldOfView(state: GameMap, action: RecalculateUnitFieldOfViewReducerAction): GameMap {
  const units = state.getAllAliveUnitsArray();

  for (const unit of units) {
    if (unit.fieldOfView.rays.length === 0 || unit.distanceToHero > unit.fieldOfView.range) {
      continue;
    }

    const vehicle = unit.getVehicleInUse();
    const entitiesInView: { [id: string]: Building | Unit | Vehicle } = {};

    for (const coordinates of unit.fieldOfView.cellsInView) {
      const entity = state.getEntityByCoordinates(coordinates);

      if (entity && entity.id !== unit.id && entity.id !== vehicle?.id) {
        entitiesInView[entity.id] = entity;
      }
    }

    unit.fieldOfView.castRays(Object.values(entitiesInView));
  }

  return state;
}

function renderCone(entity: Building | Unit | Vehicle) {
      const colors = {
