      const top = isoTransform(x + width / 2, y + length / 2, height);

      ctx.fillStyle = colors.right;
      ctx.beginPath();
      ctx.moveTo(bottomRight.x, bottomRight.y);
      ctx.lineTo(top.x, top.y);
      ctx.lineTo(topRight.x, topRight.y);
      ctx.fill();

      ctx.fillStyle = colors.top;
      ctx.beginPath();
      ctx.moveTo(bottomLeft.x, bottomLeft.y);
      ctx.lineTo(top.x, top.y);
      ctx.lineTo(bottomRight.x, bottomRight.y);
      ctx.fill();
    }

export class FogOfWar {
  private canvas: OffscreenCanvas;
  private ctx: OffscreenCanvasRenderingContext2D;
  private bg = "";

  private readonly size: Size2D;
  constructor(props: { size: Size2D }) {
    this.size = props.size;
    this.canvas = new OffscreenCanvas(props.size.width, props.size.height);
    this.ctx = this.canvas.getContext("2d")!;
  }

  async render(hero: Unit): Promise<FogOfWar["bg"]> {
    const hideFill = `rgba(0, 0, 0, ${constants.FOG_OF_WAR_OPACITY})`;
    const { ctx } = this;
    const { width, height } = this.size;

    ctx.clearRect(0, 0, width, height);
    ctx.globalCompositeOperation = "source-over";

    ctx.fillStyle = hideFill;
    ctx.lineWidth = 0;
    ctx.fillRect(0, 0, width, height);

    ctx.globalCompositeOperation = "destination-out";

    const { x, y } = hero.position.grid;

    ctx.beginPath();
    ctx.moveTo(x, y);

    for (const ray of hero.fieldOfView.rays) {
      ctx.lineTo(
        Math.round(ray.n.grid.x * ray.len.grid) + ray.position.grid.x,
        Math.round(ray.n.grid.y * ray.len.grid) + ray.position.grid.y,
      );
    }

    ctx.lineTo(x, y);
    ctx.closePath();
    ctx.ellipse(x, y, 1, 3, -Math.PI / 4, 0, 2 * Math.PI);
    ctx.fill();

    //
    const blob = await this.canvas.convertToBlob();

    this.bg = window.URL.createObjectURL(blob);

    return this.bg;
  }
}

export class LightRay {
  position: {
    grid: GridCoordinates;
    screen: ScreenCoordinates;
  } = {
    grid: { x: 0, y: 0 },
    screen: { x: 0, y: 0 },
  };
  len = {
    grid: 0,
    screen: 0,
  };
  n: {
    grid: { x: number; y: number };
    screen: { x: number; y: number };
  } = {
    grid: { x: 0, y: 0 },
    screen: { x: 0, y: 0 },
  };

  color = "";
  angle: AngleInRadians = 0;
  collidedWithEntity: Building | Unit | Vehicle | null = null;

  constructor(props: { position: GridCoordinates; radius: number; color: string }) {
    this.setPosition(props.position);
    this.setLen(props.radius);
    this.setColor(props.color);
    this.setRotation(0);
  }

  setRotation(angle: AngleInRadians) {
    this.angle = angle;

    this.n = {
      grid: { x: Math.cos(angle), y: Math.sin(angle) },
      screen: { x: Math.cos(angle), y: Math.sin(angle) },
    };
  }

  setPosition(position: GridCoordinates) {
    this.position = {
      grid: {
        x: position.x + 0.5,
        y: position.y + 0.5,
      },
      screen: {
        x: (position.x + 0.5) * constants.wireframeTileSize.width,
        y: (position.y + 0.5) * constants.wireframeTileSize.height,
      },
    };
  }

  setLen(len: number) {
    this.len = {
      grid: len,
      screen: len * constants.wireframeTileSize.width,
    };
  }

  setColor(color: string) {
    this.color = color;
  }

  cast(entities: Array<Building | Unit | Vehicle>) {
    let minDist = this.len.grid;
    let collidedWithEntity = null;
    this.collidedWithEntity = null;

    for (const entity of entities) {
      if (!entity.blocksRays) continue;

      const d = entity.rayDist2Polygon(this);

      if (d.distance < minDist) {
        minDist = d.distance;
        collidedWithEntity = d.entity;
      }
    }

    this.len = {
      grid: minDist,
      screen: minDist * constants.wireframeTileSize.width,
    };
    this.collidedWithEntity = collidedWithEntity;

    return collidedWithEntity;
  }
}

export default class WeaponSelectorMenu extends ActionsMenu {
  protected linesTiles = {
    top     : [2674, 2675, 2675, 2675, 2675, 2675, 2675, 2676],
    middle  : [2704, 2705, 2705, 2705, 2705, 2705, 2705, 2706],
    bottom  : [2734, 2735, 2735, 2735, 2735, 2735, 2735, 2736],
  };

  private readonly buttonWidth: number = 200;

  protected createAdditionalButtons() {
    const container = this.scene.add.container(0, 0);

    const { tile } = this;

    if (tile) {
      const tileUnit = tile.properties.tileUnit as TileUnit;
      const weapons = tileUnit.getWeaponsHittingOpponent();

      const weaponButtons = weapons.map((weapon, index) => {
        const coord = { x: 0, y: (index + 1) * 30 };
        return this.createWeaponButton({ coord, weapon });
      });

      container.add(weaponButtons);
    }

    return container;
  }

  protected createPermanentButtons() {
    const container = this.scene.add.container(0, 0);

    const cancel = this.createCancelButton();

    container.add(cancel);

    return container;
  }

  protected onPointerUpOutside() {
    this
      .hide()
      .sendAction(WeaponSelectorActions.cancel);
  }

  private createCancelButton() {
    const button = new ActionButton(this.scene, {
      text: 'cancel',
      width: 200,
    });

    button.on('click', () => {
      this
        .hide()
        .sendAction(WeaponSelectorActions.cancel);
    });

    return button.getContainer();
  }

  private createWeaponButton(config: CreateWeaponButtonConfig) {
    const { coord, weapon } = config;

    const button = new ActionButton(this.scene, {
      coord,
      text: `${weapon.name}         x${weapon.usage}`,
      width: this.buttonWidth,
    });

    button
      .on('click', () => {
        this
          .hide()
          .sendAction(WeaponSelectorActions.select, weapon);
      })
      .on('cusorchanged', () => {
        const { tile } = this;

        if (!tile) { return; }

        const tileUnit = tile.properties.tileUnit as TileUnit;
        tileUnit.showWeaponRange(weapon);
      });

    return button.getContainer();
  }

  /** Send attack's action to the scene (through event). */
  private sendAction(action: string, weapon?: Weapon) {
    this.scene.events.emit(`${weaponSelectorEvent}${action}`, this.tile, weapon);
    return this;
  }
}

export function agresiva(state: BattleState): BattleAction {
  const acciones = legalActions(state);
  const s = activeStack(state);
  if (s === null) throw new Error('sin stack activo');

  const disparo = acciones.find((a) => a.type === 'shoot');
  if (disparo !== undefined) return disparo;

  const ataque = acciones.find((a) => a.type === 'attack');
  if (ataque !== undefined) return ataque;

  const enemigos = enemiesOf(state, s);
  const movimientos = acciones.filter(
    (a): a is Extract<BattleAction, { type: 'move' }> => a.type === 'move',
  );
  if (movimientos.length > 0 && enemigos.length > 0) {
    const distancia = (h: { col: number; row: number }): number =>
      Math.min(...enemigos.flatMap((e) => stackHexes(e).map((eh) => hexDistance(h, eh))));
    return movimientos.reduce((mejor, m) => (distancia(m.to) < distancia(mejor.to) ? m : mejor));
  }

  return acciones.find((a) => a.type === 'defend') ?? acciones[0]!;
}

function shoot(state: BattleState, shooter: BattleStack, target: BattleStack, rng: Rng): void {
  const info = creature(shooter.creature);
  shooter.shotsLeft -= 1;
  const shots = hasTrait(info, 'double_shot') ? 2 : 1;

  for (let i = 0; i < shots && isAlive(target); i++) {
    const distance = Math.min(
      ...stackHexes(shooter).flatMap((sh) => stackHexes(target).map((th) => hexDistance(sh, th))),
    );
    const result = computeDamage(
      shooter,
      state.heroes[shooter.side],
      target,
      state.heroes[target.side],
      rng,
      { ranged: true, distance },
    );
    const killed = applyDamage(target, result.damage);

    if (result.lucky) state.log.push({ kind: 'luck', stack: shooter.id, good: true });
    state.log.push({
      kind: 'shoot',
      stack: shooter.id,
      target: target.id,
      damage: result.damage,
      killed,
    });
    if (!isAlive(target)) state.log.push({ kind: 'perished', stack: target.id });

    if (hasTrait(info, 'splash_shot')) splash(state, shooter, target, result.damage);
  }
}

function moveHero(
  state: GameState,
  heroId: string,
  to: Point,
  ctx: GameContext,
  alcance?: Reachable,
): void {
  const hero = heroById(state, heroId);
  const player = currentPlayer(state);
  if (hero.owner !== player.id) throw new Error('ese héroe no es tuyo');

  const camino = caminoDelHeroe(state, hero, to, alcance);
  if (camino === null) throw new Error(`no hay camino hasta (${to.x},${to.y})`);
  if (camino.length === 0) return;

  for (let i = 0; i < camino.length; i++) {
    const paso = camino[i] as (typeof camino)[number];
    const coste = paso.cost - (camino[i - 1]?.cost ?? 0);
    if (hero.movePoints < coste) {
      throw new Error('no quedan puntos de movimiento para llegar');
    }

    // Un enemigo en la casilla destino desencadena batalla y detiene la marcha.
    const enemigo = enemyAt(state, paso.at, player.id);
    if (enemigo !== null) {
      hero.movePoints -= coste;
      startBattle(state, hero, enemigo, ctx);
      return;
    }

    hero.movePoints -= coste;
    hero.at = paso.at;
    revealAround(state, hero);
    emit(state, {
      kind: 'hero_moved',
      hero: hero.id,
      to: paso.at,
      spent: coste,
      actor: hero.owner,
      at: paso.at,
    });
    collectAt(state, hero, paso.at);
  }
}

export function createGame(config: GameConfig): GameState {
  // El tope se valida AQUÍ y no solo en el borde del entorno, porque la regla es
  // del juego y no de quién la pide. `enteroDelEntorno` ya rechazaba un
  // `HEROES_MAX_DAYS=0` con una frase buena, pero `newGame({ maxDays: 0 })` —o
  // un `-5`— se aceptaba y jugaba **un día**, terminando «sin resolver» en
  // silencio: la misma regla con dos severidades según por qué puerta entres,
  // que es lo que este repositorio llama fallar callando.
  if (!Number.isInteger(config.maxDays) || config.maxDays < 1) {
    throw new Error(
      `una partida de ${config.maxDays} días no es una partida: el tope tiene que ser un entero ≥ 1`,
    );
  }

  const players: Player[] = config.players.map((p) => ({
    id: p.id,
    faction: p.faction,
    controller: p.controller,
    resources: addResources(DEFAULT_STARTING_RESOURCES, config.startingResources ?? {}),
    fog: new Set<string>(),
    memory: new Map<string, RememberedObject>(),
    defeated: false,
  }));

  const state: GameState = {
    seed: config.seed,
    day: 1,
    maxDays: config.maxDays,
    map: config.map,
    players,
    heroes: config.heroes.map((h) => ({ ...h, army: [...h.army] })),
    towns: config.towns.map((t) => ({
      ...t,
      available: { ...t.available },
      buildings: [...t.buildings],
    })),
    current: config.players[0]?.id ?? 0,
    pendingBattle: null,
    finished: null,
    log: [],
  };

  // Los pueblos arrancan con la hornada de la primera semana.
  for (const town of state.towns) applyWeeklyGrowth(town);

  for (const hero of state.heroes) {
    hero.movePoints = maxMovePoints(hero);
    revealAround(state, hero);
  }

  emit(state, { kind: 'day_start', day: 1, week: 1, actor: null, at: null });
  startTurn(state);
  return state;
}

function dibujarFotograma(): void {
  if (!needsRender) return;
  needsRender = false;

  const rect = syncCanvasSize();
  ctx!.clearRect(0, 0, rect.width, rect.height);

  if (session.scene === 'town' && session.activeTown !== null) {
    townShift = townLayout(rect.width, rect.height);
    drawTown(ctx!, {
      town: session.activeTown,
      purse: session.resources,
      transform: townShift,
      hover: hoverTown,
      interactive: session.isPlayersTurn,
    });
  } else if (session.scene === 'battle' && session.battle !== null) {
    const battle = session.battle;
    battleShift = battleOffset(rect.width, rect.height);

    const muertos = new Set(battle.stacks.filter((s) => s.count <= 0).map((s) => s.id));
    animator.observe(battle.log, muertos);
    const poses = new Map<string, Pose>();
    for (const s of battle.stacks) {
      const pose = animator.poseOf(s.id, { muerto: s.count <= 0, defendiendo: s.defending });
      if (pose !== null) poses.set(s.id, pose);
    }

    drawBattle(ctx!, {
      battle,
      movable: session.battleMovable(),
      hoverHex,
      hoverStack,
      // Sin hechizo elegido no hay nada que anillar: se reparte el conjunto
      // vacío en vez de montar uno nuevo en cada fotograma, que a 60 fps
      // mientras dura una animación son sesenta por segundo para nada.
      castTargets: session.selectedSpell === null ? SIN_OBJETIVOS : new Set(session.castTargets()),
      offset: battleShift,
      poses,
    });

    // Mientras haya una pose en marcha hay que seguir repintando.
    if (animator.busy) needsRender = true;
  } else {
    const centro = session.selectedHero?.at ?? session.myTowns()[0]?.at ?? { x: 0, y: 0 };
    camera = cameraFor(session.state, centro, rect.width, rect.height);
    drawAdventure(ctx!, {
      state: session.state,
      camera,
      viewer: session.viewer,
      selectedHero: session.selectedHeroId,
      hoverPath,
      revealAll: session.revealAll,
    });
  }

  // Lo que es marcado se pinta con `pintar`, que es el único `innerHTML` del
  // repo; lo que es texto sigue yendo por `textContent`, que no necesita
  // escapar nada porque no interpreta nada.
  const top = renderTopbar(session);
  elDay.textContent = top.day;
  pintar(elResources, top.resources);
  elTurn.textContent = top.turn;
  pintar(elSide, renderSide(session));
  pintar(elActions, renderActions(session));
  elStatus.textContent = session.status;
}

export function applyAction(
  state: BattleState,
  action: BattleAction,
  rng: Rng,
  movibles?: Movibles,
): void {
  if (state.finished !== null) throw new Error('la batalla ya ha terminado');
  const s = activeStack(state);
  if (s === null) throw new Error('no hay stack activo');
  if (movibles !== undefined && movibles.stack !== s.id) {
    throw new Error(`el recorrido que traes es de ${movibles.stack} y quien actúa es ${s.id}`);
  }

  switch (action.type) {
    case 'wait': {
      if (s.waited) throw new Error(`${s.id} ya esperó en esta ronda`);
      s.waited = true;
      state.log.push({ kind: 'wait', stack: s.id });
      state.queue.push(s.id);
      advance(state, rng);
      return;
    }

    case 'defend': {
      s.defending = true;
      state.log.push({ kind: 'defend', stack: s.id });
      endTurn(state, s, rng);
      return;
    }

    case 'move': {
      moveTo(state, s, action.to, movibles?.costs);
      endTurn(state, s, rng);
      return;
    }

    case 'attack': {
      const target = stackById(state, action.target);
      if (!isAlive(target)) throw new Error(`${target.id} ya está destruido`);
      if (target.side === s.side) throw new Error('no se puede atacar a un aliado');
      // Los hexes recorridos NO se guardan en el stack: viajan hasta el golpe
      // como argumento. Un campo `hexesMoved` habría que resetearlo en
      // `beginRound` y en `endTurn`, y el día que se olvidara uno el
      // contraatacante cargaría con los hexes de su turno anterior.
      const recorridos =
        action.from === undefined ? 0 : moveTo(state, s, action.from, movibles?.costs);
      if (!canReachMelee(s, target)) {
        throw new Error(`${s.id} no alcanza a ${target.id} cuerpo a cuerpo`);
      }
      melee(state, s, target, rng, recorridos);
      endTurn(state, s, rng);
      return;
    }

    case 'shoot': {
      const target = stackById(state, action.target);
      if (!isShooter(creature(s.creature))) throw new Error(`${s.id} no es tirador`);
      if (s.shotsLeft <= 0) throw new Error(`${s.id} se ha quedado sin munición`);
      if (isEngaged(state, s)) throw new Error(`${s.id} tiene un enemigo encima`);
      if (!isAlive(target)) throw new Error(`${target.id} ya está destruido`);
      if (target.side === s.side) throw new Error('no se puede disparar a un aliado');
      shoot(state, s, target, rng);
      endTurn(state, s, rng);
      return;
    }

    case 'cast': {
      castHeroSpell(state, s.side, action.spell, action.target);
      // Lanzar un hechizo no consume el turno del stack: el héroe actúa aparte.
      return;
    }
  }
}

export function receiveSortie(w: World, id: SortieId, lane: number, kickback: number): Creep {
  const def = SORTIES[id];
  const stats = scaledStats(def.enemy, w.wave.index, w.rules);
  return spawnCreep(w, def.enemy, {
    ...stats,
    origin: 'sortie',
    leakDamage: def.weight,
    route: lane,
    kickback,
  });
}

function detonate(w: World, p: Projectile, s: TowerStats, source: Tower | undefined): void {
  const r = s.splashRadius;
  const r2 = r * r;

  // Announced before the damage loop, and unconditionally: a detonation that
  // caught nothing is exactly the one the player most needs to see, because it
  // is the one telling them the station is mistimed or misplaced.
  w.events.push({ type: 'blast', x: p.x, y: p.y, radius: r, defId: p.defId });

  for (const c of w.creeps) {
    // The direct hit was already paid in full by the caller.
    if (c.dead || c === p.target) continue;

    const dx = c.x - p.x;
    const dy = c.y - p.y;
    const d2 = dx * dx + dy * dy;
    if (d2 > r2) continue;

    const falloff = 1 - (Math.sqrt(d2) / r) * (1 - s.splashFalloff);
    hit(w, c, p.damage * falloff, s, source);
  }
}

function stepHoming(w: World, p: Projectile, s: TowerStats, dt: number): void {
  if (!p.target.dead) {
    p.tx = p.target.x;
    p.ty = p.target.y;
  }

  const dx = p.tx - p.x;
  const dy = p.ty - p.y;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const travel = p.speed * dt;

  if (dist > travel) {
    const k = travel / dist;
    p.x += dx * k;
    p.y += dy * k;
    return;
  }

  p.x = p.tx;
  p.y = p.ty;
  p.dead = true;

  // The firing station may have been sold mid-flight; attribution then finds
  // nothing and the damage still lands, which is the right outcome.
  const source = towerById(w, p.towerId);
  // damageCreep no-ops on an already-dead contact, so a wasted shot is free.
  hit(w, p.target, p.damage, s, source);
  if (s.splashRadius > 0) detonate(w, p, s, source);
  if (s.chainJumps > 0) chain(w, p, s, source);
}

function chain(w: World, p: Projectile, s: TowerStats, source: Tower | undefined): void {
  const struck: EntityId[] = [p.target.id];
  let fromX = p.x;
  let fromY = p.y;
  let damage = p.damage;
  const reach2 = s.chainRange * s.chainRange;

  for (let jump = 0; jump < s.chainJumps; jump++) {
    let best: Creep | undefined;
    let bestD2 = reach2;

    for (const c of w.creeps) {
      if (c.dead || struck.includes(c.id)) continue;
      const dx = c.x - fromX;
      const dy = c.y - fromY;
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) {
        bestD2 = d2;
        best = c;
      }
    }

    // Nothing within reach ends the chain. A jump that found no one must not be
    // spent and then resumed from the same place on the next iteration, or the
    // loop would just re-scan and re-fail `chainJumps` times.
    if (best === undefined) return;

    damage *= s.chainFalloff;
    hit(w, best, damage, s, source);
    struck.push(best.id);
    fromX = best.x;
    fromY = best.y;
  }
}

function renderArmourLine(w: World, t: Tower, next: number | null): string {
  const ref = toughestArmour(w);
  if (ref === null) return '';

  const now = effectiveDamage(t.stats.damage, ref.armor);
  const after = next === null ? null : effectiveDamage(next, ref.armor);
  const kept = now / t.stats.damage;

  // Flagged past half, so "this is the wrong tool for that" reads without the
  // player doing the division.
  const cls = kept <= 0.5 ? ' class="bad"' : '';
  const name = ENEMIES[ref.defId].name;

  // A proportional bar rather than a percentage: the sliver *is* the 16%, so
  // the player reads how much of every hit survives instead of doing the
  // subtraction. The contact glyph names which one, so the line costs no words
  // — the sentence it replaced survives in `title`.
  const label =
    `${ref.inbound ? 'Inbound' : 'On the board'}: ${name} · ` +
    `${formatDamage(now)} of ${formatDamage(t.stats.damage)} per hit · ` +
    `armour eats ${Math.round((1 - kept) * 100)}%`;

  // The contact stays a glyph here, deliberately. Naming it would read better
  // in isolation but this is the inspector, under a ten-word budget, and the
  // glyph→name mapping is taught one panel over: renderNextContact now labels
  // every mark in the wave preview, which is the surface you read *before* the
  // wave rather than during it. aria-label carries the full sentence for screen
  // readers and costs nothing on screen.
  return (
    `<div class="line armour" title="${label}" aria-label="${label}">` +
    `${contactIcon(ref.defId, 18)}` +
    `<span class="bar"><i style="width:${(kept * 100).toFixed(1)}%"></i></span>` +
    `<b${cls}>${formatDamage(now)}${after === null ? '' : ` → ${formatDamage(after)}`}</b>` +
    `</div>`
  );
}

export function renderNextContact(w: World): string {
  const s = w.wave;
  if (s.phase === 'done' && w.creeps.length === 0) {
    return `<div class="head"><b>Route clear</b></div><div class="hint">Nothing else is coming.</div>`;
  }

  const plan = planWave(w.seed, s.index, w.rules, w.map.routes);
  if (plan.length === 0) {
    return `<div class="head"><b>Wave ${s.index + 1}</b></div>`;
  }

  // Grouped by type, in order of first arrival.
  //
  // This used to read `plan[0]`'s name and hp and apply them to `plan.length`,
  // which was true only while there was one contact type. With six it announced
  // wave 10 as "40 × Drifter" when barely a quarter of it was Drifters — a
  // confident lie, in the one panel whose entire job is telling the player what
  // to prepare for.
  const groups: { enemy: EnemyId; n: number; hp: number; shield: number }[] = [];
  for (const p of plan) {
    const hit = groups.find((g) => g.enemy === p.enemy);
    if (hit === undefined) groups.push({ enemy: p.enemy, n: 1, hp: p.hp, shield: p.shield });
    else hit.n++;
  }

  // Effective health, so a Warden's overshield counts toward "toughest" — it is
  // health the player has to chew through whatever pool it sits in.
  const toughest = groups.reduce((a, b) => (b.hp + b.shield > a.hp + a.shield ? b : a));

  // The real glyph at the real tint, not the name. The panel's whole job is
  // "prepare for this", and it was describing the wave in a language the board
  // does not use — the player had to translate "4 Warden" into the ringed pink
  // circle they were about to see. Armour and shield are visible *before* the
  // wave rather than only during it, which is the point at which they are still
  // actionable.
  // The name rides along under the glyph rather than living in a `title` that
  // never fires on touch. Learning which mark is a Warden is exactly what this
  // panel is for, and the glyph alone cannot teach it.
  const chips = groups
    .map(
      (g) =>
        `<span class="chip">` +
        `${contactIcon(g.enemy, 26)}<b>${g.n}</b>` +
        `<i class="cname">${ENEMIES[g.enemy].name}</i></span>`,
    )
    .join('');

  return (
    `<div class="head"><i class="dot contact"></i><b>Wave ${s.index + 1}</b>` +
    `<span class="blurb">${plan.length} inbound</span></div>` +
    `<div class="chips">${chips}</div>` +
    // One effective-health figure, because the biggest glyph above already
    // named which contact it belongs to. Shield counts: it is health the player
    // has to chew through whichever pool it sits in.
    `<div class="hint">Toughest <b>${toughest.hp + toughest.shield}</b> ehp</div>`
  );
}

export function moveCreeps(w: World, dt: number): void {
  for (const c of w.creeps) {
    if (c.dead) continue;

    // Per creep, not once for the whole loop: contacts on a multi-lane board
    // are walking different chains.
    const route = w.map.routes[c.route]!.waypoints;

    // Sampled once per creep, not once per leg: the budget below can cross
    // several legs in a tick, and charging the timer inside that loop would
    // make a slow burn off faster on a corner-heavy stretch than on a straight.
    const speed = c.slowTimer > 0 ? c.speed * c.slowFactor : c.speed;
    if (c.slowTimer > 0) {
      c.slowTimer = Math.max(0, c.slowTimer - dt);
      // Retire the factor with the timer so the two can never disagree; a stale
      // 0.55 sitting behind an expired timer is the kind of thing that only
      // shows up as a desync.
      if (c.slowTimer === 0) c.slowFactor = 1;
    }

    let budget = speed * dt;
    while (budget > 0) {
      const target = route[c.leg];

      // Ran off the end of the route: the creep reached the goal.
      if (target === undefined) {
        c.dead = true;
        // Floored at zero rather than allowed negative, so a heavy contact
        // landing on a one-life reserve reads as a loss and not as a debt. The
        // phase change on the next tick is what ends the run either way.
        w.lives = Math.max(0, w.lives - c.leakDamage);
        w.stats.leaks++;
        // Only wave contacts are itemised per wave — a sortie belongs to no
        // wave, and tallying it against whichever one happened to be spawning
        // would print leaks in a clear summary the wave never caused.
        if (c.origin === 'wave') waveStats(w, c.wave).leaked++;
        w.events.push({
          type: 'creepLeaked',
          x: c.x,
          y: c.y,
          cost: c.leakDamage,
          bought: c.origin === 'sortie',
        });
        // A sortie that lands pays *its sender*, who is not this world. The
        // event is the only way that money can travel; crediting it here would
        // pay the person who just took the hit.
        if (c.origin === 'sortie' && c.kickback > 0) {
          w.stats.sortiesTaken++;
          w.events.push({ type: 'sortieLanded', kickback: c.kickback, cost: c.leakDamage });
        }
        break;
      }

      const dx = target.x - c.x;
      const dy = target.y - c.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist <= budget) {
        // Snap to the corner so float error cannot accumulate across legs, then
        // carry the leftover distance into the next one.
        c.x = target.x;
        c.y = target.y;
        c.progress += dist;
        budget -= dist;
        c.leg++;
      } else {
        const k = budget / dist;
        c.x += dx * k;
        c.y += dy * k;
        c.progress += budget;
        budget = 0;
      }
    }
  }
}

export class Board {
    tileWidth: number = 32;
    tileHeight: number = 24;
    margin: number = 4;
    rows: number;
    cols: number;

    cells: Cell[] = [];

    pathFinder: PathFinder

    constructor(rows: number, cols: number, scene: ex.Scene) {
        this.rows = rows;
        this.cols = cols;
        for (let i = 0; i < this.rows * this.cols; i++) {
            const cell = new Cell(i % this.cols, Math.floor(i / this.cols), this);
            this.cells.push(cell);
            scene.add(cell);
        }

        // setup neighbors connections
        for (let cell of this.cells) {
            cell.pathNode.connections = cell.getNeighbors().map(c => c.pathNode);
        }

        this.pathFinder = new PathFinder(scene);
    }

    getCenter() {
        return ex.vec(
            this.cols * ((this.tileWidth + this.margin) * SCALE.x),
            this.rows * ((this.tileHeight + this.margin) * SCALE.y)
        ).scale(.5);
    }

    getUnits() {
        let result: Unit[] = [];
        for (let cell of this.cells) {
            if (cell.unit && cell.unit.active) {
                result.push(cell.unit);
            }
        }
        return result;
    }

    getEmptyCells(): Cell[] {
        return this.cells.filter(cell => !cell.unit);
    }

    getCellByWorldPos(pos: ex.Vector): Cell | null {
        return this.getCell(
            Math.floor((pos.x /*- BOARD_OFFSET.x*/) / ((this.tileWidth+this.margin) * SCALE.x)),
            Math.floor((pos.y /*- BOARD_OFFSET.y*/) / ((this.tileHeight+this.margin) * SCALE.y))
        );
    }

    getCell(x: number, y: number): Cell | null {
        if(x < 0 || x >= this.cols) return null;
        if(y < 0 || y >= this.rows) return null;
        return this.cells[x + y * this.cols];
     }
}

