export function setUnitPosition(state: GameMap, action: SetUnitPositionReducerAction): GameMap {
  const entity = state.getUnitById(action.entityId);

  if (entity) {
    state.setGridMatrixOccupancy([entity], -1);
    entity.setPosition(action.coordinates, state);
    state.setGridMatrixOccupancy([entity], 1);

    return { ...state };
  }

  return state;
}

export function endCombat(state: GameMap, action: EndCombatReducerAction): GameMap {
  const allAliveEnemies = state.getAliveEnemiesArray();

  allAliveEnemies.forEach((enemy) => {
    enemy.stop();
  });

  const combatQueue: GameMap["combatQueue"] = {
    currentUnitId: null,
    units: [],
  };

  return {
    ...state,
    ...{
      combatQueue,
    },
  };
}

export function enemyTurnNoActionPoints(this: GameContext, deltaTime: number, enemy: Unit) {
  const { gameState } = this;
  const hero = gameState.getHero();

  const currentIndex = gameState.combatQueue.units.findIndex((iter) => iter.id === gameState.combatQueue.currentUnitId);

  enemy.stop();
  enemy.restoreActionPoints();

  gameState.combatQueue.currentUnitId = gameState.combatQueue.units[currentIndex + 1]?.id || hero.id;
}

export function addUnit(state: GameMap, action: AddUnitReducerAction): GameMap {
  const unit = new Unit({
    gameState: state,
    unitType: action.unitType,
    position: action.position,
    rotation: action.rotation,
    isHero: false,
  });

  unit.setPosition(action.position, state);

  state.units[unit.id] = unit;
  state.setGridMatrixOccupancy([unit]);

  return {
    ...state,
    ...{
      selectedUnit: unit,
    },
  };
}

export function useEntityInUnitHand(state: GameMap, action: UseEntityInUnitHandReducerAction) {
  const { unit, hand, targetPosition, consumeActionPoints } = action;

  const weapon = unit.getCurrentWeapon();

  if (weapon && weapon.isReadyToUse(state)) {
    unit.inventory[hand]?.use(targetPosition, state);

    if (consumeActionPoints) {
      unit.consumeActionPoints(weapon.getCurrentAttackModeDetails().actionPointsConsumption);
    }
  }

  return { ...state };
}

