function resolveMajorBattle(
  attackerStr: number,
  effectiveDefender: number,
  rawDefenderStr: number,
  rng: () => number
): CombatResult {
  let currentAttacker = attackerStr;
  let currentDefender = rawDefenderStr;
  let currentEffectiveDefender = effectiveDefender;
  let rounds = 0;
  const maxRounds = 20; // safety cap

  while (currentAttacker > 0 && currentDefender > 0 && rounds < maxRounds) {
    rounds++;
    const total = currentAttacker + currentEffectiveDefender;
    const defenderPowerRatio = currentEffectiveDefender / total;
    const attackerPowerRatio = currentAttacker / total;

    // Each side inflicts damage proportional to its power ratio, with randomness
    const attackerDamage = currentAttacker * defenderPowerRatio * (0.15 + rng() * 0.1);
    const defenderDamage = currentDefender * attackerPowerRatio * (0.15 + rng() * 0.1);

    currentAttacker = Math.max(0, currentAttacker - Math.round(attackerDamage));
    currentDefender = Math.max(0, currentDefender - Math.round(defenderDamage));

    // Recalculate effective defender (fort/terrain bonus stays, but proportional to remaining)
    if (rawDefenderStr > 0) {
      const defenderRatio = currentDefender / rawDefenderStr;
      const bonuses = effectiveDefender - rawDefenderStr;
      currentEffectiveDefender = currentDefender + bonuses * defenderRatio;
    }
  }

  const winner: 'attacker' | 'defender' = currentAttacker > currentDefender ? 'attacker' : 'defender';
  const attackerCasualties = attackerStr - currentAttacker;
  const defenderCasualties = rawDefenderStr - currentDefender;

  return { winner, attackerCasualties, defenderCasualties, rounds };
}

export function dealHand(rng: Rng, deck: readonly SideCard[]): SideCard[] {
  const shuffled = [...deck];
  rng.shuffle(shuffled);
  const hand: SideCard[] = [];
  const seen = new Set<string>();
  for (const c of shuffled) {
    if (hand.length >= HAND_SIZE) break;
    if (seen.has(c.code)) continue;
    seen.add(c.code);
    hand.push(c);
  }
  for (let i = 0; hand.length < HAND_SIZE && shuffled.length > 0; i++) {
    hand.push(shuffled[i % shuffled.length]);
  }
  return hand;
}

export class MainDeck {
  private cards: number[] | null = null;

  constructor(
    private readonly rng: Rng,
    private readonly copies = 4,
  ) {}

  private refill(): void {
    const cards: number[] = [];
    for (let v = MAIN_DECK_MIN; v <= MAIN_DECK_MAX; v++) {
      for (let i = 0; i < this.copies; i++) cards.push(v);
    }
    this.rng.shuffle(cards);
    this.cards = cards;
  }

  draw(): number {
    if (!this.cards || this.cards.length === 0) this.refill();
    return this.cards!.pop()!;
  }

  get remaining(): number {
    return this.cards ? this.cards.length : 0;
  }
}

export function autoResolve(state: BattleState, rng: Rng, maxTurnos = 5000): BattleOutcome {
  let n = 0;
  while (state.finished === null && n < maxTurnos) {
    // El recorrido con el que se decidió viaja hasta el motor: `moveTo` lo
    // repetía entero para cobrar la carga.
    const { action, stack, costs } = chooseBattleActionAndCosts(state);
    applyAction(state, action, rng, { stack, costs });
    n++;
  }
  if (state.finished === null) {
    // Empate por agotamiento: gana quien conserve más vida. No se deja colgada.
    const vida = (side: Side): number =>
      state.stacks.filter((s) => s.side === side).reduce((t, s) => t + stackHp(s), 0);
    const winner: Side = vida('attacker') >= vida('defender') ? 'attacker' : 'defender';
    state.finished = { winner };
    state.log.push({ kind: 'finished', winner });
  }
  return { winner: state.finished.winner, state, rounds: state.round };
}

export function construirVista(state: GameState, directorLog: readonly string[]): SpectatorView {
