  };
}

export function serializeBattleTurn(
  battle: BattleState,
  side: Side,
  vista: VistaDeBatalla,
): unknown {
  const stackView = (s: (typeof battle.stacks)[number]) => {
    const info = creature(s.creature);
    return {
      id: s.id,
      side: s.side,
      creature: s.creature,
      name: info.name,
      count: s.count,
      hp: stackHp(s),
      hex: s.hex,
      occupies: stackHexes(s),
      speed: stackSpeed(s),
      attack: info.attack,
      defense: info.defense,
      damage: info.damage,
      shooter: isShooter(info),
      shotsLeft: s.shotsLeft,
      traits: info.traits ?? [],
      // La suerte va ya con los efectos aplicados: el contrato promete el
      // valor con el que se va a tirar, no el de la ficha. La moral no tiene
      // efectos temporales que aplicar, así que es la suya y ya.
      morale: s.morale,
      luck: effectiveLuck(s),
      // Y aparte, cuánto le queda a cada cosa: sin esto el agente ve el número
      // cambiar de una ronda a otra sin saber por qué ni hasta cuándo.
      effects: s.effects.map((e) => ({
        kind: e.kind,
        amount: e.amount,
        source: e.source,
        roundsLeft: e.roundsLeft,
      })),
      defending: s.defending,
      waited: s.waited,
    };
  };

  const hero = battle.heroes[side];
  const propia = vista === 'propia';
  const activo = activeStack(battle);

  return {
    kind: 'battle_turn',
    round: battle.round,
    yourSide: side,
    activeStack: battle.activeId,
    board: { width: 11, height: 9, layout: 'offset odd-r; el atacante entra por la columna 0' },
    stacks: battle.stacks.filter((s) => s.count > 0).map(stackView),
    hero:
      hero === null
        ? null
        : {
            name: hero.name,
            attack: hero.attack,
            defense: hero.defense,
            spellPower: hero.spellPower,
            castThisRound: hero.castThisRound,
            // Los dos únicos campos del bando, juntos y en una línea que se lee:
            // con qué maná cuenta y qué sabe lanzar. De un héroe ajeno no salen.
            ...(propia ? { mana: hero.mana, spells: hero.spells } : {}),
          },
    // Todas las acciones legales del stack activo: elegir una nunca falla —
    // cuando te toca. Si el stack activo no es de `side`, esta lista es la de
    // OTRO y sus `cast` son su libro y su maná: no se manda.
    ...(propia && activo !== null && activo.side === side
      ? { legalActions: legalActions(battle) }
      : {}),
    log: battle.log.slice(-30),
  };
}

export function dealCards(deck: Readonly<Deck>): [Deck, Player] {
  const deckCopy = deck.slice();
  const player = makePlayer();
  player.hand = deckCopy.splice(-STARTING_HAND_SIZE);
  player.offHand.faceDown = deckCopy.splice(
    -STARTING_FACEDOWN_SIZE
  ) as OffHandCards;
  return [deckCopy, player];
}

export class Guard extends BaseState {
	constructor(stateMachine) {
		super(stateMachine);

		const gameLoop = managers.get('gameLoop');

		const atackSpeed = this.entity.stats.attackSpeed;

		this.cdId = gameLoop.setCD(atackSpeed, true);
	}

	update() {
		const { entityManager, gameLoop } = managers.get(['entityManager', 'gameLoop']);

		const target = entityManager.findNearestEntity(this.entity, entityManager.enemies);

		if (gameLoop.isCDReady(this.cdId) && target) {
			this.stateMachine.setState('Shoot', { spawner: this.entity, target });
		}
	}
}

export function toughestArmour(w: World): ArmourReference | null {
  let best: ArmourReference | null = null;

  for (const c of w.creeps) {
    if (c.dead) continue;
    const armor = ENEMIES[c.defId].armor;
    if (armor > 0 && (best === null || armor > best.armor)) {
      best = { defId: c.defId, armor, inbound: false };
    }
  }
  if (best !== null) return best;

  for (const spawn of planWave(w.seed, w.wave.index, w.rules, w.map.routes)) {
    const armor = ENEMIES[spawn.enemy].armor;
    if (armor > 0 && (best === null || armor > best.armor)) {
      best = { defId: spawn.enemy, armor, inbound: true };
    }
  }
  return best;
}

export function upgradeCost(
  t: Tower,
  path: UpgradePath,
  ceiling: number = BALANCE.upgrade.maxTier,
): number | null {
  // A station with no damage has no damage path. `damageAtTier` multiplies the
  // def's damage, so on an Overclock every tier of this track is a purchase
  // that provably cannot move a number the sim reads — a money sink, not a
  // decision. Priced as unavailable rather than left to sell nothing.
  if (path === 'damage' && !hasDamagePath(t.defId)) return null;
  const tier = t.tiers[path];
  // The ceiling defaults to the global maximum, which is what the campaign and
  // Race always pass. Versus passes `tierCeiling(w)` so the era caps it.
  if (tier >= ceiling) return null;
  return Math.round(TOWERS[t.defId].cost * BALANCE.upgrade.costFactor * tier);
}

export function computeStats(defId: TowerId, tiers: TowerTiers): TowerStats {
  const def = TOWERS[defId];
  // Annotated mutable: inferred, the fields would be unions of the five defs'
  // literal values, and the += below could not write to them.
  const stats: { -readonly [K in keyof TowerStats]: number } = {
    range: rangeAtTier(defId, tiers.range),
    damage: damageAtTier(defId, tiers.damage),
    fireInterval: def.fireInterval,
    projectileSpeed: def.projectileSpeed,
    pierce: def.pierce,
    splashRadius: def.splashRadius,
    splashFalloff: def.splashFalloff,
    slowFactor: def.slowFactor,
    slowSeconds: def.slowSeconds,
    chainJumps: def.chainJumps,
    chainRange: def.chainRange,
    chainFalloff: def.chainFalloff,
    rampPerSecond: def.rampPerSecond,
    rampMax: def.rampMax,
    buffShotsPerSecond: def.buffShotsPerSecond,
  };

  // Widened from the def's literal type: each station's `perTier` is a narrow
  // `as const` shape, and the loop needs the general one.
  const perTier: Readonly<Partial<TowerStats>> = def.effectUpgrade.perTier;
  const steps = tiers.effect - 1;
  if (steps > 0) {
    for (const key of Object.keys(perTier) as (keyof TowerStats)[]) {
      stats[key] += perTier[key]! * steps;
    }
  }
  return stats;
}

export function createLoop(world: World, onRender: () => void): GameLoop {
  const acc: Accumulator = { debt: 0 };
  let last = 0;
  let rafId = 0;
  let hidden = false;

  const loop: GameLoop = { speed: 1, paused: false, start, stop };

  function frame(now: number): void {
    rafId = requestAnimationFrame(frame);

    const elapsed = now - last;
    last = now;

    if (!loop.paused && !hidden) advance(world, acc, elapsed, loop.speed);

    // Render every frame regardless — the HUD and hover feedback must stay
    // responsive while paused.
    onRender();
  }

  function start(): void {
    if (rafId !== 0) return;
    last = performance.now();
    acc.debt = 0;
    rafId = requestAnimationFrame(frame);
  }

  function stop(): void {
    if (rafId === 0) return;
    cancelAnimationFrame(rafId);
    rafId = 0;
  }

  // Auto-pause when the tab is hidden. Correct tower defense behaviour on its
  // own, and in Race mode it is free fairness: ranking is waves cleared first
  // and elapsed time only third, so a hidden tab simply resumes later against
  // an identical board rather than being punished.
  document.addEventListener('visibilitychange', () => {
    hidden = document.hidden;
    if (!hidden) {
      // Returning from hidden: discard the debt accrued while away.
      last = performance.now();
      acc.debt = 0;
    }
  });

  return loop;
}

export async function createRenderer(
  mount: HTMLElement,
  width: number,
  height: number,
  field: SectorField,
): Promise<Renderer> {
  const app = new Application();

  // v8: init() is ASYNC. (v7's `new Application({...})` is gone — most tutorials
  // online are still v7 and will not work.)
  await app.init({
    width,
    height,
    background: field.bg,

    // Crisp on retina without changing our logical coordinate space.
    resolution: window.devicePixelRatio || 1,
    autoDensity: true,

    antialias: true,

    // We drive rendering from our own fixed-timestep loop, so Pixi must not
    // start its own ticker. See src/app/loop.ts.
    autoStart: false,

    // WebGL rather than WebGPU: fewer driver edge cases, and nothing here needs
    // compute. Revisit only if profiling ever says to.
    preference: 'webgl',
  });

  // v8: `app.canvas`, not `app.view`.
  mount.appendChild(app.canvas);

  fitCanvas(app);
  watchViewport(() => {
    fitCanvas(app);
  });

  const layers: Layers = {
    map: new Container(),
    towers: new Container(),
    creeps: new Container(),
    projectiles: new Container(),
    effects: new Container(),
    overlay: new Container(),
  };

  app.stage.addChild(
    layers.map,
    layers.towers,
    layers.creeps,
    layers.projectiles,
    layers.effects,
    layers.overlay,
  );

  return { app, layers };
}

function renderPathButtons(w: World, t: Tower): string {
  return UPGRADE_PATHS.filter((path) => path !== 'damage' || hasDamagePath(t.defId)).map((path) => {
    const ceiling = tierCeiling(w);
    const cost = upgradeCost(t, path, ceiling);
    const next = nextStats(t, path, ceiling);
    const { label, value } = pathPreview(t, path, next);
    // Pips always show the full ladder, never the era's slice of it: a track
    // capped at Mk II by the era is *held back*, and drawing two pips would say
    // it was finished. The disabled button says why.
    const pips = tierPips(t.tiers[path], BALANCE.upgrade.maxTier);

    // The dial shows where this path sits on the station's collar, so the
    // board's positional code is taught at the moment the player buys into it.
    const dial = pathDial(path);

    // Label+pips over value+price, two columns — not four stacked rows. The
    // deck is 150px tall and three of these sit under the portrait band; a
    // stacked button was the difference between fitting and spilling out of
    // the panel at both ends.
    if (cost === null) {
      return `<span class="path maxed"><label>${dial}${label}</label>${pips}<b>${value}</b><em>Max</em></span>`;
    }
    return (
      `<button class="path${w.money < cost ? ' poor' : ''}" data-act="upgrade" data-path="${path}">` +
      `<label>${dial}${label}</label>${pips}<b>${value}</b><em>$${cost}</em></button>`
    );
  }).join('');
}

function pickTarget(w: World, t: Tower): Creep | undefined {
  const r2 = t.stats.range * t.stats.range;

  /**
   * A ramping station holds its target while that target is alive and in reach.
   *
   * This is the one deliberate exception to the no-caching rule above, and it
   * exists because without it the mechanic cannot function. `first` re-picks the
   * contact furthest along every single tick, and in a moving stream that is a
   * different contact constantly — so a Filament reset its ramp perpetually and
   * measured *weaker* than pure Singularity, a station with no damage at all.
   *
   * The rule's usual objection — a tower fixated on something about to die
   * elsewhere — is precisely the trade a beam is supposed to make. It is also
   * scoped: only stations that actually ramp are sticky, so the default
   * behaviour of the other four is untouched.
   */
  if (t.stats.rampPerSecond > 0 && t.focusId !== null) {
    for (const c of w.creeps) {
      if (c.dead || c.id !== t.focusId) continue;
      const dx = c.x - t.x;
      const dy = c.y - t.y;
      if (dx * dx + dy * dy <= r2) return c;
      break;
    }
  }

  let best: Creep | undefined;
  let bestScore = -Infinity;

  for (const c of w.creeps) {
    if (c.dead) continue;
    const dx = c.x - t.x;
    const dy = c.y - t.y;
    const d2 = dx * dx + dy * dy;
    if (d2 > r2) continue;

    const s = score(w, t.targeting, c, d2);
    // Strictly greater, so ties go to the creep found first. That keeps the
    // choice deterministic given a deterministic creep array, which is what
    // Race-mode fairness rests on.
    if (s > bestScore) {
      bestScore = s;
      best = c;
    }
  }

  return best;
}

function buildEndMarkers(map: MapDef, field: SectorField): Graphics {
  const g = new Graphics();

  // One chevron per *entry tile*, not per lane. Crown runs four lanes out of
  // two spawns, and stacking two chevrons on one tile just draws it darker.
  const drawn = new Set<string>();

  for (const route of map.routes) {
    // The spawn point sits one tile off-board; draw the chevron on the first
    // on-board tile instead, pointing the way creeps will travel.
    const entry = route.waypoints[0]!;
    const first = route.waypoints[1];
    if (first === undefined) continue;

    const key = `${first.x},${first.y}`;
    if (drawn.has(key)) continue;
    drawn.add(key);

    const dx = Math.sign(first.x - entry.x);
    const dy = Math.sign(first.y - entry.y);
    const ax = first.x * TILE_PX;
    const ay = first.y * TILE_PX;
    const r = TILE_PX * 0.3;

    // Tip points along travel; the base is the perpendicular through the centre.
    g.moveTo(ax + dx * r, ay + dy * r)
      .lineTo(ax - dx * r + dy * r, ay - dy * r + dx * r)
      .lineTo(ax - dx * r - dy * r, ay - dy * r - dx * r)
      .fill({ color: field.spawn, alpha: 0.85 });
  }

  const gx = map.goal.x * TILE_PX;
  const gy = map.goal.y * TILE_PX;
  const goal = field.goal;

  // The bloom is the `falloff` sprite under the tile field, not a disc here —
  // see the halos added in `buildMapLayer`. What is left in this Graphics is
  // only what has to sit *above* the board: the rings and the core.
  for (const [radius, width, alpha] of PULSAR_RINGS) {
    g.circle(gx, gy, TILE_PX * radius).stroke({ width, color: goal, alpha });
  }
  // Core: a soft shoulder under a hard centre, so the middle blooms instead of
  // sitting there as a flat dot the rings happen to be centred on. It grew with
  // the rings — a 0.08-tile dot inside a 2.5-tile ring stack would read as a
  // target the rings were aimed at rather than as the thing emitting them.
  g.circle(gx, gy, TILE_PX * 0.34).fill({ color: goal, alpha: 0.16 });
  g.circle(gx, gy, TILE_PX * 0.2).fill({ color: goal, alpha: 0.34 });
  g.circle(gx, gy, TILE_PX * 0.11).fill({ color: goal, alpha: 0.95 });

  return g;
}

export function analyzeComposition(
  towers: TowerComposition[],
  levelConfig: LevelConfig,
  difficulty: Difficulty = Difficulty.Normal
): CompositionAnalysis {
  const mods = DIFFICULTY_MODS[difficulty];
  const startingGold = Math.round(levelConfig.startingGold * mods.goldMult);

  let totalCost = 0;
  let totalDPS = 0;
  let hasFlyingCapable = false;
  let hasCloseRange = false;

  for (const tower of towers) {
    const levels = TOWER_LEVELS[tower.type];
    const config = levels[Math.min(tower.level, levels.length - 1)];
    const cost = calcTotalCost(levels, tower.level) * tower.count;
    const dps = calcEffectiveDPS(config, 2) * tower.count;

    totalCost += cost;
    totalDPS += dps;

    if (config.canTargetFlying !== false) {
      hasFlyingCapable = true;
    }

    if (config.range <= 2.5) hasCloseRange = true;
  }

  const level = analyzeLevel(levelConfig, difficulty);
  const hasFlying = level.waves.some((w) => w.hasFlying);
  const hasStealth = level.waves.some((w) => w.hasStealth);

  return {
    towers,
    totalCost,
    totalDPS: Math.round(totalDPS),
    canHandleFlying: !hasFlying || hasFlyingCapable,
    canHandleStealth: !hasStealth || hasCloseRange,
    goldRemaining: startingGold + level.totalReward - totalCost,
  };
}

export class TowerManager {
  private towers: Tower[] = [];
  private group: Group;
  private map: GameMap;
  private distanceField: DistanceField;

  constructor(group: Group, map: GameMap, distanceField: DistanceField) {
    this.group = group;
    this.map = map;
    this.distanceField = distanceField;
  }

  getDistanceField(): DistanceField {
    return this.distanceField;
  }

  canPlace(gridPos: GridPosition): boolean {
    const cell = this.map.getCellAt(gridPos.row, gridPos.col);
    return !!cell && cell.cellType === CellType.Buildable && !cell.occupied;
  }

  place(config: TowerConfig, gridPos: GridPosition): Tower | null {
    if (!this.canPlace(gridPos)) return null;

    const cell = this.map.getCellAt(gridPos.row, gridPos.col)!;
    const worldPos = this.map.getWorldPosition(gridPos);
    const tower = new Tower(config, gridPos, worldPos.x, worldPos.z);
    cell.occupied = true;
    this.towers.push(tower);

    this.group.add(tower.getObject3D());
    tower.startPlacementAnimation();
    return tower;
  }

  remove(tower: Tower): void {
    const cell = this.map.getCellAt(tower.gridPos.row, tower.gridPos.col);
    if (cell) cell.occupied = false;
    this.group.remove(tower.getObject3D());
    tower.dispose();
    const idx = this.towers.indexOf(tower);
    if (idx !== -1) this.towers.splice(idx, 1);

  }

  getTowerAt(gridPos: GridPosition): Tower | undefined {
    return this.towers.find(
      (t) => t.gridPos.row === gridPos.row && t.gridPos.col === gridPos.col,
    );
  }

  upgradeTower(tower: Tower, newConfig: TowerConfig): void {
    tower.upgrade(newConfig);
  }

  getTowers(): readonly Tower[] {
    return this.towers;
  }

  update(delta: number): void {
    for (const tower of this.towers) {
      tower.update(delta);
    }
  }

  dispose(): void {
    for (const tower of this.towers) {
      this.group.remove(tower.getObject3D());
      tower.dispose();
    }
    this.towers = [];
  }
}

export function generateBudgetWave(
  budget: number,
  level: number,
  availableTypes: EnemyConfig[],
  rand: () => number,
): WaveConfig {
  const hpScale = calcHPScale(level);
  const entries: WaveConfig["entries"] = [];
  let remaining = budget;

  // Shuffle available types for variety
  const shuffled = [...availableTypes];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  for (const baseConfig of shuffled) {
    if (remaining <= 0) break;

    const category = classifyEnemy(baseConfig);
    const cost = ENEMY_BUDGET_COST[category] ?? 5;
    const maxCount = Math.floor(remaining / cost);
    if (maxCount <= 0) continue;

    // Random count between 1 and maxCount (biased toward fewer for expensive types)
    const count =
      cost >= 30
        ? Math.min(maxCount, 1 + Math.floor(rand() * 2))
        : Math.min(maxCount, 2 + Math.floor(rand() * (maxCount - 1)));

    if (count <= 0) continue;

    entries.push({
      count,
      spawnInterval: Math.max(0.3, 1.2 - level * 0.05),
      enemyConfig: {
        ...baseConfig,
        hp: Math.round(baseConfig.hp * hpScale),
        speed: baseConfig.speed + level * 0.05,
        reward: Math.max(
          1,
          Math.round(baseConfig.reward * calcRewardScale(level)),
        ),
      },
    });

    remaining -= count * cost;
  }

  // If budget remains and we have entries, pad with basic enemies
  if (remaining > 5 && entries.length > 0) {
    const basicCost = ENEMY_BUDGET_COST["basic"];
    const padCount = Math.floor(remaining / basicCost);
    if (padCount > 0) {
      entries.push({
        count: padCount,
        spawnInterval: 0.8,
        enemyConfig: {
          ...BASIC_ENEMY,
          hp: Math.round(BASIC_ENEMY.hp * hpScale),
          speed: BASIC_ENEMY.speed + level * 0.05,
          reward: Math.max(
            1,
            Math.round(BASIC_ENEMY.reward * calcRewardScale(level)),
          ),
        },
      });
    }
  }

  return { entries };
}

export function endTurn(state: GameMap, action: EndTurnReducerAction): GameMap {
  const combatQueue: GameMap["combatQueue"] = {
    currentUnitId: state.combatQueue.units[0].id,
    units: state.combatQueue.units,
  };

  return {
    ...state,
    ...{
      combatQueue,
    },
  };
}

export function centerMapOnHero(state: GameUI, action: CenterMapOnHeroUIReducerAction): GameUI {
  const { x1, y1, x2, y2 } = state.viewport.screen;

  state.setScroll({
    x: action.unitCoordinates.x - (x2 - x1) / 2 + constants.tileSize.width / 2,
    y: action.unitCoordinates.y - (y2 - y1) / 2,
  });

  return { ...state };
}

export function combatScene(this: GameContext, deltaTime: number) {
  const { gameState } = this;
  const hero = gameState.getHero();

  gameState.combatQueue.units = gameState.getAliveEnemiesArray().filter((enemy) => {
    return !!enemy.getFirstAvailableWeaponInHands();
  });

  switch (gameState.combatQueue.currentUnitId) {
    case hero.id:
      heroTurn.apply(this, [deltaTime]);
      break;

    default:
      enemyTurn.apply(this, [deltaTime]);
  }
}

export function highlightUnitAtGunpoint(state: GameMap, action: HighlightUnitAtGunpointReducerAction) {
  const hero = state.getHero();
  const weapon = hero?.getCurrentWeapon();

  if (!weapon) return state;

  const unitAtGunpoint =
    !!weapon &&
    weapon.isReadyToUse(state) &&
    weapon.getAimCoordinates()?.x === action.unit.getRoundedPosition().x &&
    weapon.getAimCoordinates()?.y === action.unit.getRoundedPosition().y;

  const isChanged = action.unit.atGunpoint !== unitAtGunpoint;
  action.unit.setAtGunpoint(unitAtGunpoint);

  return isChanged ? { ...state } : state;
}

export function getIntoVehicle(state: GameMap, action: GetIntoVehicleReducerAction) {
  const { unit, vehicle } = action;

  state.deOccupyCell(unit.getRoundedPosition());
  unit.getIntoVehicle(vehicle);
  unit.setRotation(vehicle.rotation, false);
  vehicle.assignDriver(unit);

  const turnOnSfx = state.createSfx([vehicle.dictEntity.sfx["turnOn"].src], 1);
  const idleSfx = state.createSfx([vehicle.dictEntity.sfx["idle"].src], 1);

  if (turnOnSfx) {
    const stopTime = turnOnSfx.buffer!.duration * 1000 - 265;

    if (idleSfx) {
      window.setTimeout(() => {
        vehicle.currentPlayingSfx["idle"] = idleSfx;

        idleSfx.loop = true;
        idleSfx.start();
      }, stopTime);
    }

    turnOnSfx.start();
  }

  // vehicle.currentPlayingSfx[]
  //
  // state.playSfx([vehicle.dictEntity.sfx["turnOn"].src], 1, 0).then((a) => {
  //   console.log(a);
  //   state.playSfx([vehicle.dictEntity.sfx["idle"].src], 1, 0);
  // });

  return { ...state };
}

export function useMessages() {
  const { gameDispatch, uiDispatch } = useGameState();

  const notify_EntityTakesDamage = (entity: Unit | Vehicle) => {
    if (entity.damagePoints > -1) return;

    gameDispatch({
      type: "emitMessage",
      messageType: "tooltip",
      messageStyle: "red",
      messageShowStyle: "rise",
      position: entity.getRoundedPosition(),
      value: entity.damagePoints,
      timeToLiveMs: 1000,
    });
  };

  const notify_UnitEarnedXP = (unit: Unit, xp: number) => {
    gameDispatch({
      type: "emitMessage",
      messageType: "sticky",
      //messageStyle: "green",
      value: `+${xp} XP`,
      timeToLiveMs: 5000,
    });
  };

  const notify_UnitEarnedLevel = () => {
    gameDispatch({
      type: "emitMessage",
      messageType: "sticky",
      messageStyle: "green",
      value: `+1 Level`,
      onClick: () => {
        uiDispatch({ type: "setScene", scene: "unitCharacteristics" });
      },
    });
  };

  return { notify_EntityTakesDamage, notify_UnitEarnedXP, notify_UnitEarnedLevel };
}

export class MovableGameEntity extends GameEntity {
  public path: GridCoordinates[] = [];
  public pathQueue: PathQueue;
  public pathCompleteCallback: (() => void) | null = null;

  private collisionDetected = false;

  constructor(props: GameEntityProps) {
    super(props);

    this.pathQueue = new PathQueue();
  }

  public setPath(path: number[][]) {
    this.path = convertPathToCoordinatesArray(path);
  }

  public setPathCompleteCallback(callback: (() => void) | null) {
    this.pathCompleteCallback = callback;
  }

  public setPositionComplete() {
    if (this.pathCompleteCallback) {
      this.pathCompleteCallback();
    }
  }

  public convertCoordinatesToPathArray(coordinates: GridCoordinates[]) {
    return coordinates.map((iter) => [iter.x, iter.y]);
  }

  public clearPath() {
    this.pathQueue.points = [];
    this.path = [];
  }

  public setPosition(position: GridCoordinates, gameState: GameMap) {
    super.setPosition(position, gameState);

    this.collisionDetected = gameState.checkCollision(this);
  }

  public isCollisionDetected() {
    return this.collisionDetected;
  }
}

export function getDistanceBetweenEntities(
  entity1: Unit | Building | Vehicle,
  entity2: Unit | Building | Vehicle,
): number {
  const entity1Corners = [
    { x: entity1.position.grid.x, y: entity1.position.grid.y },
    { x: entity1.position.grid.x + entity1.size.grid.width, y: entity1.position.grid.y },
    { x: entity1.position.grid.x, y: entity1.position.grid.y + entity1.size.grid.length },
    { x: entity1.position.grid.x + entity1.size.grid.width, y: entity1.position.grid.y + entity1.size.grid.length },
  ];

  const entity2Corners = [
    { x: entity2.position.grid.x, y: entity2.position.grid.y },
    { x: entity2.position.grid.x + entity2.size.grid.width, y: entity2.position.grid.y },
    { x: entity2.position.grid.x, y: entity2.position.grid.y + entity2.size.grid.length },
    { x: entity2.position.grid.x + entity2.size.grid.width, y: entity2.position.grid.y + entity2.size.grid.length },
  ];

  let minDistance = Number.MAX_VALUE;

  for (const corner1 of entity1Corners) {
    for (const corner2 of entity2Corners) {
      const distance = Math.sqrt(Math.pow(corner1.x - corner2.x, 2) + Math.pow(corner1.y - corner2.y, 2));

      if (distance < minDistance) {
        minDistance = distance;
      }
    }
  }

  return minDistance;
}

export default class MapActionsMenu extends ActionsMenu {
  constructor(scene: Phaser.Scene, layer: Phaser.Tilemaps.DynamicTilemapLayer) {
    super(scene, layer);
  }

  protected createAdditionalButtons() {
    return this.scene.add.container(0, 0);
  }

  protected createPermanentButtons() {
    const cancel = this.createCancelButton();
    const endTurn = this.createEndTurnButton();
    const suspend = this.createSuspendButton();

    const container = this.scene.add
      .container(0, 0, [cancel, endTurn, suspend])
      .setVisible(false);

