    this.scene.events.emit(`${mapEvent}${action}`);
  }
}

function generateWildcardCandidates(
  nation: Nation,
  context: GameContext
): ActionCandidate[] {
  const { state } = context;
  const candidates: ActionCandidate[] = [];
  const atWar = state.wars.some(
    (w) => w.aggressorId === nation.id || w.defenderId === nation.id
  );

  // --- Spy on threatening neighbors ---
  const neighborIds = getNeighborNationIds(nation.id, state);
  for (const targetId of neighborIds) {
    const relation = nation.relations[targetId] ?? 0;
    if (relation >= 0) continue;

    // Pick the least-known intel track
    const intel = nation.intelOf[targetId];
    const tracks: ('military' | 'economic' | 'diplomatic' | 'political')[] = [
      'military', 'economic', 'diplomatic', 'political',
    ];
    const hiddenTrack = tracks.find(
      (t) => !intel || intel[t] === 'Hidden'
    );
    const approximateTrack = tracks.find(
      (t) => intel && intel[t] === 'Approximate'
    );
    const bestTrack = hiddenTrack ?? approximateTrack;

    if (bestTrack) {
      const threatFactor = Math.abs(relation) / 100;
      candidates.push({
        order: {
          type: 'spy',
          nationId: nation.id,
          targetNationId: targetId,
          intelTrack: bestTrack,
        },
        category: 'wildcard',
        score: 0.4 + threatFactor * 0.3,
      });
    }
  }

  // --- Hire mercenaries (at war + low manpower) ---
  if (atWar && nation.resources.manpower < 10 && nation.resources.gold >= 30) {
    candidates.push({
      order: {
        type: 'hire_mercenaries',
        nationId: nation.id,
        goldCost: 30,
        manpowerGain: 15,
      },
      category: 'wildcard',
      score: 0.7,
    });
  }

  // --- Restore eliminated allies ---
  for (const eliminated of state.nations) {
    if (eliminated.eliminatedOnTurn === undefined) continue;
    if (eliminated.exileWindowExpires === undefined) continue;
    if (state.turn > eliminated.exileWindowExpires) continue;

    const relation = nation.relations[eliminated.id] ?? 0;
    if (relation < 20) continue;
    if (nation.resources.influence < state.scenario.meta.exileRestoreCost) continue;

    candidates.push({
      order: {
        type: 'restore_nation',
        nationId: nation.id,
        targetNationId: eliminated.id,
      },
      category: 'wildcard',
      score: nation.utilityWeights.allianceBuilding * 0.5 + (relation / 100) * 0.3,
    });
  }

  return candidates;
}

function resolveCombatPhase(
  pendingBattles: PendingBattle[],
  armies: Army[],
  provinces: Province[],
  scenario: Scenario,
  turn: number
): CombatPhaseResult {
  let currentArmies = [...armies];
  let currentProvinces = [...provinces];
  const entries: ConflictReportEntry[] = [];

  for (const battle of pendingBattles) {
    const province = currentProvinces.find((p) => p.id === battle.provinceId);
    if (!province) continue;

    const attackerStrength = battle.attackerArmies.reduce((sum, a) => sum + a.strength, 0);
    const defenderStrength = battle.defenderArmies.reduce((sum, a) => sum + a.strength, 0);

    if (attackerStrength <= 0 && defenderStrength <= 0) continue;

    const fortBonus = getFortBonus(province.fortLevel);
    const terrainMod = getTerrainModifier(province.terrain);

    // Determine if major battle
    const combinedStrength = attackerStrength + defenderStrength;
    const majorThreshold = scenario.meta.majorBattleThreshold ?? 50;
    const isCapitalOrKey =
      province.strategicTag === 'Capital' || province.strategicTag === 'KeyRegion';
    const isMajor = combinedStrength > majorThreshold || isCapitalOrKey;

    // Seed from turn + province id hash for determinism
    const seed = hashSeed(turn, battle.provinceId);

    const params: CombatParams = {
      attackerStrength,
      defenderStrength,
      fortBonus,
      terrainModifier: terrainMod,
      seed,
    };

    const result = resolveCombat(params, isMajor);

    // Apply casualties
    currentArmies = applyCasualties(
      currentArmies,
      battle.attackerArmies.map((a) => a.id),
      result.attackerCasualties
    );
    currentArmies = applyCasualties(
      currentArmies,
      battle.defenderArmies.map((a) => a.id),
      result.defenderCasualties
    );

    // Remove eliminated armies (strength <= 0)
    currentArmies = currentArmies.filter((a) => a.strength > 0);

    // Province ownership changes if attacker wins and no defenders remain
    if (result.winner === 'attacker') {
      const remainingDefenders = currentArmies.filter(
        (a) => a.provinceId === battle.provinceId && a.ownerId === battle.defenderNationId
      );
      if (remainingDefenders.length === 0) {
        currentProvinces = currentProvinces.map((p) =>
          p.id === battle.provinceId
            ? { ...p, ownerId: battle.attackerNationId }
            : p
        );
      }
    }

    entries.push({
      type: 'battle',
      involvedNations: [battle.attackerNationId, battle.defenderNationId],
      provinceId: battle.provinceId,
      description: `Battle at ${province.name}: ${battle.attackerNationId} (${attackerStrength}) vs ${battle.defenderNationId} (${defenderStrength})`,
      resolution: `${result.winner} won (${result.rounds} round${result.rounds > 1 ? 's' : ''}). Casualties: attacker ${result.attackerCasualties}, defender ${result.defenderCasualties}.`,
    });
  }

  return { armies: currentArmies, provinces: currentProvinces, entries };
}

function bestHandPlay(game: PazaakGame, player: number): [PlayHandCard | null, number] {
  const me = game.players[player];
  if (me.playedThisTurn) {
    return [null, me.total];
  }

  let best: PlayHandCard | null = null;
  let bestTotal = me.total;
  let bestKey: [number, number] = [1, Math.abs(WINNING_TOTAL - me.total)];


  const legal = game.legalActions();
  for (const action of legal) {
    if (action.kind !== 'play') {
      continue;
    }
    const card = me.hand[action.handIndex]!;
    const opt = card.options[action.optionIndex];
    const result = me.total + opt.delta;
    const busts = result > WINNING_TOTAL ? 1 : 0;
    const distance = Math.abs(WINNING_TOTAL - result);
    const key: [number, number] = [busts, distance];


    if (key[0] < bestKey[0] || (key[0] === bestKey[0] && key[1] < bestKey[1])) {
      bestKey = key;
      best = action;
      bestTotal = result;
    }
  }

  return [best, bestTotal];
}

export function battleOwners(
  state: GameState,
  pending: PendingBattle,
): Readonly<Record<Side, PlayerId | null>> {
  const foe = pending.foe;
  const defender =
    foe.kind === 'monster'
      ? null
      : foe.kind === 'hero'
        ? heroById(state, foe.heroId).owner
        : townById(state, foe.townId).owner;
  return { attacker: heroById(state, pending.attackerHeroId).owner, defender };
}

export function forzarBatalla(state: GameState, ctx: GameContext, hero: Hero): Monstruo {
  const monstruo = monstruoVivo(state);
  hero.at = { x: monstruo.at.x - 1, y: monstruo.at.y };
  hero.movePoints = 5000;
  applyAdventureAction(
    state,
    { type: 'move_hero', hero: hero.id, to: monstruo.at },
    ctx,
    state.current,
  );
  if (state.pendingBattle === null) throw new Error('pisar al monstruo no abrió ninguna batalla');
  return monstruo;
}

function battleSideForHero(state: GameState, hero: Hero): BattleSide {
  const pueblo = state.towns.find(
    (t) => t.owner === hero.owner && pointKey(t.at) === pointKey(hero.at),
  );
  return {
    army: hero.army,
    hero: {
      name: hero.name,
      attack: hero.attack,
      defense: hero.defense,
      spellPower: hero.spellPower,
      knowledge: hero.knowledge,
      mana: hero.mana,
      castThisRound: false,
      spells: hero.spells,
    },
    moraleBonus: moraleBonus(hero) + (pueblo === undefined ? 0 : moraleFromBuildings(pueblo)),
    luckBonus: luckBonus(hero),
  };
}

function enemyAt(state: GameState, at: Point, player: PlayerId): BattleFoe | null {
  const obj = objectAt(state.map, at);
  if (obj !== undefined && obj.kind === 'monster' && !obj.defeated) {
    return { kind: 'monster', objectId: obj.id };
  }

  const heroeEnemigo = state.heroes.find(
    (h) => h.owner !== player && pointKey(h.at) === pointKey(at),
  );
  if (heroeEnemigo !== undefined) return { kind: 'hero', heroId: heroeEnemigo.id };

  const pueblo = state.towns.find((t) => pointKey(t.at) === pointKey(at));
  if (pueblo !== undefined && pueblo.owner !== player) {
    const defendido = !isArmyEmpty(pueblo.garrison);
    if (defendido) return { kind: 'town', townId: pueblo.id };
  }
  return null;
}

export function describeAccion(accion: BattleAction | AdventureAction): string {
  switch (accion.type) {
    case 'move':
      return `movimiento a (${accion.to.col},${accion.to.row})`;
    case 'attack':
      return `ataque a ${accion.target}`;
    case 'shoot':
      return `disparo a ${accion.target}`;
    case 'wait':
      return 'espera';
    case 'defend':
      return 'defensa';
    case 'cast':
      return `hechizo ${accion.spell}${accion.target === undefined ? '' : ` sobre ${accion.target}`}`;
    case 'move_hero':
      return `move_hero ${accion.hero} → (${accion.to.x},${accion.to.y})`;
    case 'hire_hero':
      return `hire_hero en ${accion.town}`;
    case 'recruit':
      return `recruit ${accion.count}× ${accion.creature} en ${accion.town}`;
    case 'build':
      return `build ${accion.building} en ${accion.town}`;
    case 'end_turn':
      return 'end_turn';
  }
}

function hireHero(state: GameState, townId: string): void {
  const town = townById(state, townId);
  const player = currentPlayer(state);
  if (town.owner !== player.id) throw new Error('ese pueblo no es tuyo');
  if (heroesOf(state, player.id).length >= MAX_HEROES_PER_PLAYER) {
    throw new Error('ya tienes el máximo de héroes');
  }
  if (player.resources.gold < HERO_HIRE_COST) throw new Error('oro insuficiente');
  if (state.heroes.some((h) => pointKey(h.at) === pointKey(town.at))) {
    throw new Error('ya hay un héroe en el pueblo');
  }

  const id = `hero-${player.id}-${state.heroes.length}-${state.day}`;
  const hero: Hero = {
    id,
    owner: player.id,
    name: `Capitán de ${town.name}`,
    faction: town.faction,
    attack: 1,
    defense: 1,
    spellPower: 1,
    knowledge: 1,
    mana: 10,
    level: 1,
    experience: 0,
    army: [null, null, null, null, null],
    at: town.at,
    movePoints: 0,
    spells: [],
    skills: {},
  };
  hero.movePoints = maxMovePoints(hero);

  player.resources = addResources(player.resources, { gold: -HERO_HIRE_COST });
  state.heroes.push(hero);
  emit(state, {
    kind: 'hero_hired',
    hero: id,
    town: town.id,
    actor: player.id,
    at: town.at,
  });

  takeGarrison(state, hero, town);
  revealAround(state, hero);
}

export function applyAdventureAction(
  state: GameState,
  action: AdventureAction,
  ctx: GameContext,
  quien: PlayerId,
  alcance?: Reachable,
): void {
  if (state.pendingBattle !== null) {
    throw new Error('hay una batalla pendiente de resolver');
  }
  // La partida terminada y el turno ajeno los dice `turnBlocker`, que es donde
  // vive la frase: aquí no se reescribe ninguna de las dos.
  const bloqueo = turnBlocker(state, quien);
  if (bloqueo !== null) throw new Error(bloqueo);

  // Quién actúa se anota ANTES de la acción: `end_turn` cambia `state.current`,
  // y el que acaba de meter su héroe en el castillo es el jugador saliente.
  const actor = currentPlayer(state).id;
  aplicar(state, action, ctx, alcance);

  // Y nada se aprende después del final. `aplicar` puede terminar la partida
  // —capturar el último castillo del rival lo hace—, y esta sincronía iba
  // detrás sin preguntar: en 34 de 200 semillas la crónica acababa con «Fin de
  // la partida» y DEBAJO «El jugador 1 aprende: Prisa, Lentitud», que además se
  // pinta así en pantalla. La regla que rompía está escrita en `settleBattle`
  // —`game_over` es el ÚLTIMO hecho del registro— y no la vigilaba nadie;
  // ahora sí (`test/invariantes.test.ts`).
  if (state.finished === null) syncSpellbooks(state, actor);
}

function strike(
  state: BattleState,
  attacker: BattleStack,
  target: BattleStack,
  rng: Rng,
  retaliation: boolean,
  hexesMoved: number,
): void {
  const info = creature(attacker.creature);
  const result = computeDamage(
    attacker,
    state.heroes[attacker.side],
    target,
    state.heroes[target.side],
    rng,
    { chargeHexes: hexesMoved },
  );
  const killed = applyDamage(target, result.damage);

  if (result.lucky) state.log.push({ kind: 'luck', stack: attacker.id, good: true });
  if (result.unlucky) state.log.push({ kind: 'luck', stack: attacker.id, good: false });

  state.log.push({
    kind: 'attack',
    stack: attacker.id,
    target: target.id,
    damage: result.damage,
    killed,
    retaliation,
    // La carga la dice `computeDamage`, que es quien la cobró: preguntarlo otra
    // vez aquí dejaba el parte contando 7 hexes mientras el bono se había
    // topado en los 5 que caben en +50 %.
    ...(result.charge > 0 ? { charge: result.charge } : {}),
  });

  // Los vampiros señores recuperan efectivos con lo que drenan.
  if (hasTrait(info, 'life_drain') && !retaliation) {
    healFromDrain(attacker, result.damage);
  }

  // Lo que el golpe deja pegado. Va ANTES del contraataque a propósito: al
  // dragón óseo le devuelven el golpe ya asustados, que es donde se nota.
  // Un contraataque no asusta ni maldice: solo el que ataca de verdad.
  if (!retaliation && isAlive(target)) {
    for (const { trait, effect } of ON_HIT_EFFECTS) {
      if (hasTrait(info, trait)) applyStackEffect(state, target, effect);
    }
  }

  if (!isAlive(target)) state.log.push({ kind: 'perished', stack: target.id });
}

function handleBattleClick(px: number, py: number): void {
  const battle = session.battle;
  if (battle === null || battle.finished !== null) return;

  const hex = hexAtPixel(px, py, battleShift);
  if (hex === null) return;

  const objetivo = stackAt(hex);
  const acciones = session.battleLegalActions();

  // Con un hechizo elegido, el clic apunta: va ANTES que atacar y moverse, y la
  // acción que se emite sale de la lista de legales — nunca se construye aquí.
  const hechizo = session.selectedSpell;
  if (hechizo !== null) {
    if (objetivo === undefined) {
      session.status = 'Elige una unidad sobre la que lanzarlo, o pulsa Escape para cancelar.';
      return;
    }
    const conjuro = acciones.find(
      (a) => a.type === 'cast' && a.spell === hechizo && a.target === objetivo.id,
    );
    if (conjuro !== undefined) {
      session.playBattleAction(conjuro);
      return;
    }
    // La selección se mantiene: quien apuntó mal vuelve a apuntar sin repetir
    // el viaje al botón.
    session.status = session.castRejection(objetivo.id);
    return;
  }

  // Clic sobre un enemigo: disparar si se puede, si no cargar contra él.
  if (objetivo !== undefined && objetivo.side === 'defender') {
    const disparo = acciones.find((a) => a.type === 'shoot' && a.target === objetivo.id);
    if (disparo !== undefined) {
      session.playBattleAction(disparo);
      return;
    }
    const cuerpoACuerpo =
      acciones.find(
        (a) => a.type === 'attack' && a.target === objetivo.id && a.from === undefined,
      ) ?? acciones.find((a) => a.type === 'attack' && a.target === objetivo.id);
    if (cuerpoACuerpo !== undefined) {
      session.playBattleAction(cuerpoACuerpo);
      return;
    }
    session.status = 'No alcanzas a esa unidad este turno.';
    return;
  }

  const movimiento = acciones.find((a) => a.type === 'move' && hexKey(a.to) === hexKey(hex));
  if (movimiento !== undefined) {
    session.playBattleAction(movimiento);
    return;
  }
  session.status = 'No puedes llegar a ese hexágono.';
}

function drawObject(ctx: CanvasRenderingContext2D, obj: MapObject, x: number, y: number): void {
  const cx = x + TILE / 2;
  const cy = y + TILE / 2;

  switch (obj.kind) {
    case 'town': {
      ctx.fillStyle = playerColor(obj.owner);
      ctx.fillRect(x + 5, y + 12, TILE - 10, TILE - 17);
      ctx.fillRect(x + 9, y + 5, 6, 10);
      ctx.fillRect(x + TILE - 15, y + 5, 6, 10);
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.strokeRect(x + 5.5, y + 12.5, TILE - 11, TILE - 18);
      break;
    }
    case 'mine': {
      // La montaña va siempre: el icono encima dice qué se extrae y el color
      // del borde, de quién es.
      ctx.fillStyle = playerColor(obj.owner);
      ctx.beginPath();
      ctx.moveTo(cx, y + 7);
      ctx.lineTo(x + TILE - 7, y + TILE - 7);
      ctx.lineTo(x + 7, y + TILE - 7);
      ctx.closePath();
      ctx.fill();
      const icono = asset('icons', obj.resource);
      if (icono !== null) {
        ctx.drawImage(icono, cx - 9, cy - 2, 18, 18);
      } else {
        ctx.fillStyle = RESOURCE_COLORS[obj.resource];
        ctx.beginPath();
        ctx.arc(cx, cy + 4, 4, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case 'resource': {
      if (obj.taken) return;
      const icono = asset('icons', obj.resource);
      if (icono !== null) {
        ctx.drawImage(icono, x + 6, y + 6, TILE - 12, TILE - 12);
        break;
      }
      ctx.fillStyle = RESOURCE_COLORS[obj.resource];
      ctx.beginPath();
      ctx.arc(cx, cy, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.stroke();
      break;
    }
    case 'chest': {
      if (obj.taken) return;
      ctx.fillStyle = '#a8762c';
      ctx.fillRect(x + 11, y + 14, TILE - 22, TILE - 26);
      ctx.fillStyle = '#d9a441';
      ctx.fillRect(x + 11, y + 18, TILE - 22, 3);
      break;
    }
    case 'monster': {
      if (obj.defeated) return;
      ctx.fillStyle = '#2b2119';
      ctx.beginPath();
      ctx.arc(cx, cy, 11, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#b4553f';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#e8dcc4';
      ctx.font = 'bold 11px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String(obj.count), cx, cy);
      break;
    }
  }
}

export function bot(pile: Pile, player: Player): Card | undefined {
  const visibleHand = [
    player.hand,
    player.offHand.faceUp.filter((card) => card !== undefined) as Cards,
  ].find((hand) => hand.length);
  if (visibleHand !== undefined) {
    const playable = playableCards(pile);
    const choice = visibleHand.filter((card) =>
      playable.some((playableCard) => getRank(playableCard) === getRank(card))
    );
    if (!choice.length) return;
    return choice[Math.floor(Math.random() * choice.length)];
  }
  return player.offHand.faceDown.find((card) => card !== undefined);
}

export class FollowTarget extends BaseState {
	private lastAngle = 0;
	private rotationOffset = 90; // Offset for sprite orientation

	update(deltaTime: number) {
		const { target } = this.stateMachine.context;

		if (target?.isInteractable) {
			this.followTarget(deltaTime, target);
		} else {
			this.stateMachine.setState('FollowAngle', {
				angle: this.lastAngle
			});
		}
	}

	getTopMiddlePoint(entity): Vector2 {
		const boundingBox = boundingBoxFromPoint(entity.position, entity.width, entity.height);
		return boundingBox.topMiddle;
	}

	followTarget(deltaTime: number, target: any) {
		const entityCenter = this.entity.boundingBox.center;
		const targetTopMiddle = this.getTopMiddlePoint(target);

		// Calculate angle from entity center to target's top middle point
		this.lastAngle = angleToTarget(entityCenter, target.boundingBox.center);

		// Update entity rotation with offset
		this.entity.rotation = (this.lastAngle * 180) / Math.PI + this.rotationOffset;

		// Get movement direction from the angle
		const direction = getDirectionFromAngle(this.lastAngle);

		// Calculate velocity
		const velocity = direction.multiply(this.entity.stats.speed * deltaTime);

		// Update the entity position
		this.entity.position = this.entity.position.add(velocity);
	}
}

function hit(w: World, c: Creep, amount: number, s: TowerStats, source: Tower | undefined): void {
  damageCreep(w, c, amount, source);
  applySlow(c, s);
}

function applySlow(c: Creep, s: TowerStats): void {
  if (s.slowSeconds <= 0 || s.slowFactor >= 1) return;

  if (c.slowTimer <= 0 || s.slowFactor < c.slowFactor) c.slowFactor = s.slowFactor;
  c.slowTimer = Math.max(c.slowTimer, s.slowSeconds);
  // The ring reads `slowTimer / slowMax`, so the denominator has to grow with a
  // refresh that extended the slow — otherwise a re-hit would show an arc
  // stuck at full and the countdown would stop meaning anything.
  c.slowMax = Math.max(c.slowMax, c.slowTimer);
}

export function upgradeError(
  w: World,
  t: Tower | undefined,
  path: UpgradePath,
): TowerActionError | null {
  if (t === undefined) return 'noSuchTower';
  // Checked before `upgradeCost` returns its null, because the two nulls mean
  // different things and only this one can tell them apart.
  if (path === 'damage' && !hasDamagePath(t.defId)) return 'noSuchPath';
  const cost = upgradeCost(t, path, tierCeiling(w));
  if (cost === null) return 'maxTier';
  if (w.money < cost) return 'tooPoor';
  return null;
}

export function upgradeTower(w: World, t: Tower, path: UpgradePath): number {
  const cost = upgradeCost(t, path)!;
  t.tiers[path]++;
  // A fresh object, never a mutation — in-flight projectiles hold the old one
  // as their snapshot. See the field's comment in `types.ts`.
  t.stats = computeStats(t.defId, t.tiers);
  t.spent += cost;
  w.money -= cost;
  w.stats.spent += cost;
  // Both an Overclock's range and its effect path change who it feeds and by
  // how much, so an upgrade is a buff-graph change like a build or a sell.
  refreshBuffs(w);
  return cost;
}

export function buildTower(w: World, defId: TowerId, col: number, row: number): Tower {
  const def = TOWERS[defId];
  const centre = tileCentre(col, row);

  const tiers: TowerTiers = { damage: 1, range: 1, effect: 1 };
  const tower: Tower = {
    id: w.nextId++,
    defId,
    col,
    row,
    x: centre.x,
    y: centre.y,
    tiers,
    stats: computeStats(defId, tiers),
    // Filled in by the `refreshBuffs` below, which also covers this station
    // being placed *into* an existing Overclock's reach.
    buffShots: 0,
    targeting: 'first',
    // Ready to fire the moment it lands, so a last-second build still helps.
    cooldown: 0,
    focusId: null,
    focusTime: 0,
    spent: def.cost,
    kills: 0,
    damageDealt: 0,
  };

  w.money -= def.cost;
  w.stats.spent += def.cost;
  w.towers.push(tower);
  refreshBuffs(w);
  return tower;
}

export function beginWave(w: World): void {
  const s = w.wave;

  if (s.phase === 'spawning') {
    w.events.push({ type: 'waveRejected', reason: 'spawning' });
    return;
  }
  if (s.phase === 'done') {
    w.events.push({ type: 'waveRejected', reason: 'done' });
    return;
  }

  // Captured before the timer is reset. The auto-start path arrives here with
  // the timer already at or below zero, so it earns nothing — the bonus is
  // strictly payment for time the player chose to give up.
  const secondsSaved = Math.max(0, s.timer);

  s.plan = planWave(w.seed, s.index, w.rules, w.map.routes);
  s.spawned = 0;
  s.timer = 0;
  s.phase = 'spawning';
  w.events.push({ type: 'waveStarted', wave: s.index, count: s.plan.length });

  if (secondsSaved > 0) {
    const bonus = Math.round(secondsSaved * BALANCE.rushBonusPerSecond);
    w.money += bonus;
    w.events.push({ type: 'waveRushed', wave: s.index, bonus, secondsSaved });
  }
}

export function updateWaves(w: World, dt: number): void {
  const s = w.wave;

  switch (s.phase) {
    case 'intermission':
      s.timer -= dt;
      if (s.timer <= 0) beginWave(w);
      break;

    case 'spawning': {
      s.timer += dt;
      // A `while`, not an `if`: at 4x speed, or with a tight rush wave, more
      // than one spawn can come due in a single 16ms tick.
      while (s.spawned < s.plan.length && s.plan[s.spawned]!.at <= s.timer) {
        const next = s.plan[s.spawned]!;
        spawnCreep(w, next.enemy, {
          hp: next.hp,
          bounty: next.bounty,
          shield: next.shield,
          wave: s.index,
          route: next.route,
        });
        s.spawned++;
      }

      if (s.spawned >= s.plan.length) {
        s.dispatchedThrough = s.index;
        // The intermission starts now, not when the board empties. This is what
        // makes waves overlap.
        if (s.index + 1 >= waveCount(w.rules)) {
          s.phase = 'done';
        } else {
          s.index++;
          s.phase = 'intermission';
          s.timer = BALANCE.intermission;
        }
      }
      break;
    }

    case 'done':
      break;
  }

  settleClearedWaves(w);
}

function stepPiercing(w: World, p: Projectile, s: TowerStats, dt: number): void {
  const fromX = p.x;
  const fromY = p.y;

  const dx = p.tx - p.x;
  const dy = p.ty - p.y;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const travel = p.speed * dt;

  if (dist > travel) {
    const k = travel / dist;
    p.x += dx * k;
    p.y += dy * k;
  } else {
    p.x = p.tx;
    p.y = p.ty;
    p.dead = true;
  }

  const source = towerById(w, p.towerId);

  // Swept, not point-sampled: at 14 tiles/sec a shot covers ~0.23 tiles per
  // tick against a 0.3-tile hitbox, so a point test would already be marginal
  // and any faster station would tunnel straight through a contact.
  //
  // Contacts are taken in array order rather than sorted along the segment.
  // Two in a single sweep is rare at these speeds, and array order is
  // deterministic — which is the property Race fairness actually needs.
  for (const c of w.creeps) {
    if (c.dead || p.hits.includes(c.id)) continue;

    const r = ENEMIES[c.defId].radius;
    if (segmentDistanceSq(c.x, c.y, fromX, fromY, p.x, p.y) > r * r) continue;

    p.hits.push(c.id);
    hit(w, c, p.damage, s, source);

    if (p.pierce <= 0) {
      p.dead = true;
      break;
    }
    p.pierce--;
  }
}

export function planWave(
  seed: number,
  waveIndex: number,
  rules: Rules = DEFAULT_RULES,
  routes: readonly MapRoute[] = SINGLE_ROUTE,
): PlannedSpawn[] {
  const def = defFor(rules, waveIndex);
  if (def === undefined) return [];

  // The *true* index, never the wrapped one. This is the whole of the endless
  // arc: composition repeats, difficulty does not. Wrapping the stream too
  // would make wave 25 a byte-identical replay of wave 13 — same jitter, same
  // lane deal — and the board would visibly loop.
  const rng = streamFor(seed, STREAM.WAVE, waveIndex);

  const plan: PlannedSpawn[] = [];
  for (const group of def.groups) {
    const enemy = group.enemy as EnemyId;
    const stats = scaledStats(enemy, waveIndex, rules);
    const jitter = group.every * BALANCE.spawnJitter;
    const lane = laneDealer(group.route, routes, waveIndex);

    for (let i = 0; i < group.count; i++) {
      plan.push({
        // Clamped at 0 so jitter can't pull the first spawn of a group before
        // the group is meant to begin.
        at: Math.max(0, group.after + i * group.every + randRange(rng, -jitter, jitter)),
        enemy,
        ...stats,
        // Dealt by position *within the group*, before the sort below. Sort is
        // stable, so jitter reordering neighbours cannot reshuffle lanes.
        route: lane(i),
      });
    }
  }

  // Groups may overlap in time, and jitter can reorder neighbours. The spawner
  // walks this list in order, so sorting is what makes it correct rather than
  // merely tidy.
  plan.sort((a, b) => a.at - b.at);
  return plan;
}

function settleClearedWaves(w: World): void {
  const s = w.wave;

  let lowestLive = Infinity;
  for (const c of w.creeps) {
    // Sorties belong to no wave and must never hold one open. Without this a
    // single slow contact sent by an opponent would freeze `clearedThrough`
    // for as long as it walked — no clear reward, and a Race status pump stuck
    // reporting the same wave. See `Creep.origin`.
    if (c.origin === 'sortie') continue;
    if (!c.dead && c.wave < lowestLive) lowestLive = c.wave;
  }

  // A queued split is a promise of live contacts in the parent's wave, so it
  // counts as one. Today's phase order drains the queue in the same tick it is
  // filled, so this window never opens in play — but settlement would then be
  // relying on `resolveSplits` happening to sit between the systems that fill
  // the queue and the next `updateWaves`. Reading the queue directly makes the
  // rule true regardless of order, and the alternative failure is the worst
  // kind: a wave paying out, or a run declaring victory, with contacts about
  // to appear on the board.
  for (const s of w.pendingSplits) {
    if (s.parent.origin === 'sortie') continue;
    if (s.parent.wave < lowestLive) lowestLive = s.parent.wave;
  }

  // Only waves that are both fully spawned and entirely gone from the board.
  const clearable = Math.min(s.dispatchedThrough, lowestLive - 1);
  while (s.clearedThrough < clearable) {
    s.clearedThrough++;
    w.money += BALANCE.waveClearReward;

    const tally = waveStats(w, s.clearedThrough);
    w.events.push({
      type: 'waveCleared',
      wave: s.clearedThrough,
      kills: tally.kills,
      bounty: tally.bounty,
      leaked: tally.leaked,
      reward: BALANCE.waveClearReward,
    });
  }

  if (s.clearedThrough >= waveCount(w.rules) - 1 && w.phase === 'playing') {
    w.phase = 'won';
    w.events.push({ type: 'gameOver', won: true });
  }
}

export function buildMapLayer(map: MapDef, tex: Textures, field: SectorField): MapLayer {
  const layer = new Container();

  // Beneath the tiles, which are baked translucent so it shows through.
  layer.addChild(buildStarfield(map.cols * TILE_PX, map.rows * TILE_PX, field));

  // Below the tiles, so a bloom can never dim ground the player has to build on.
  layer.addChild(halo(tex, map.goal.x, map.goal.y, PULSAR_REACH, field.goal, field.bloomAlpha));
  const entries = spawnPoints(map);
  for (const e of entries) {
    layer.addChild(halo(tex, e.x, e.y, PULSAR_REACH, field.spawn, field.bloomAlpha * SPAWN_SHARE));
  }

  const dist = routeDistance(map);
  layer.addChild(buildTileField(map, tex, field, dist, routeSpill(map, dist, SPILL_RINGS)));

  // Above the tiles, because ground is translucent: a wash underneath would
  // arrive at `1 - groundAlpha` and be most of a layer you paid for and cannot
  // see. Above, it lands at the value it was authored at.
  layer.addChild(wash(tex, map, map.goal, WASH_REACH, field.lit, field.litAlpha));
  for (const e of entries) {
    layer.addChild(wash(tex, map, e, HAZE_REACH, field.haze, field.hazeAlpha));
  }

  // Over the tiles, under the lattice — see `buildNebula` for why this is not
  // where the design put it.
  layer.addChild(buildNebula(map, field));

  layer.addChild(buildLattice(map, field));

  const stream = buildStream(map, tex, field);
  for (const run of stream) layer.addChild(run);

  layer.addChild(buildRouteLine(map, field));
  layer.addChild(buildEndMarkers(map, field));

  return {
    view: layer,
    step(dt) {
      // Constant, and deliberately **not** scaled by the 1x/2x/4x multiplier.
      // A current that sped up with the game would read as the board reacting
      // to the speed control rather than as something the road is doing.
      for (const run of stream) run.tilePosition.x -= STREAM_TILES_PER_SEC * TILE_PX * dt;
    },
  };
}

function run(
  map: MapDef,
  rules: ReturnType<typeof resolveRules>,
  seed: number,
  stopBuyingAfter = Infinity,
  strategy: Strategy = STRATEGIES[0]!,
): Result {
  // Attacking reach only — Overclock's radius buffs stations rather than
  // covering road, so ranking tiles by it would rank them for nothing.
  const reach = Math.max(...BUILD.filter((b) => TOWERS[b].buffShotsPerSecond === 0).map((b) => TOWERS[b].range));
  const spots = buildOrder(map, reach, strategy.how);
  const w = createWorld(map, seed, rules);
  const taken = new Set<number>();
  let next = 0;

  for (let i = 0; i < 600_000 && w.phase === 'playing'; i++) {
    // Step over locked stations rather than waiting on them, as a local offset
    // that does not burn cycle phase — see the same block in `sweep.ts` for both
    // what holding the cursor cost and what advancing it per tick cost.
    let skip = 0;
    while (skip < BUILD.length && w.wave.index < TOWERS[BUILD[(next + skip) % BUILD.length]!].unlockWave) {
      skip++;
    }
    if (skip === BUILD.length) {
      stepWorld(w, 1 / 60);
      w.events.length = 0;
      continue;
    }

    const want = BUILD[(next + skip) % BUILD.length]!;
    const def = TOWERS[want];
    // Support does not take tiles in rank order, and the best tiles are held
    // back for stations still locked. Shared with `sweep.ts` rather than
    // reimplemented, which is this module's whole reason for existing.
    const reserve = strategy.hold
      ? new Set(
          BUILD.filter(
            (b) => TOWERS[b].buffShotsPerSecond === 0 && w.wave.index < TOWERS[b].unlockWave,
          ),
        ).size
      : 0;
    const at = spotFor(
      spots,
      taken,
      def.buffShotsPerSecond > 0 ? { range: def.range, towers: w.towers } : null,
      reserve,
    );
    // Money still blocks rather than skipping: waiting to afford what the build
    // asked for is what a player does, where skipping to a cheaper station
    // would quietly rewrite the mix being measured.
    if (at >= 0 && w.money >= def.cost && w.wave.clearedThrough + 1 < stopBuyingAfter) {
      w.commands.push({ type: 'placeTower', defId: want, col: spots[at]![0], row: spots[at]![1] });
      taken.add(at);
      next += skip + 1;
    }
    stepWorld(w, 1 / 60);
    w.events.length = 0;
  }

  return {
    won: w.phase === 'won',
    cleared: w.wave.clearedThrough + 1,
    lives: w.lives,
    money: Math.floor(w.money),
  };
}

function renderTop(w: World, speed: number, paused: boolean): string {
  const s = w.wave;
  // An endless arc has no denominator — see `heldLabel`. On Front Line, waves
  // held is a score rather than progress toward anything, because there is
  // nothing to be partway through.
  const held = heldLabel(w);

  let label: string;
  let fill: number;
  if (s.phase === 'intermission') {
    label = `wave ${s.index + 1} · in ${Math.ceil(s.timer)}s`;
    fill = 1 - Math.max(0, s.timer) / BALANCE.intermission;
  } else if (s.phase === 'spawning') {
    // A contact glyph rather than the word "alive": the deck is teaching this
    // vocabulary two rows down, and one dot the player already recognises beats
    // a noun. Not three anonymous dots, which invite reading "3 alive".
    label =
      `wave ${s.index + 1} · <i class="dot contact"></i>${aliveInWave(w, s.index)}` +
      ` of ${s.plan.length}`;
    fill = s.plan.length === 0 ? 0 : s.spawned / s.plan.length;
  } else {
    label = 'last wave out';
    fill = 1;
  }

  // The alarm is the width of the screen rather than one red digit, because a
  // player at four lives is looking at the board, not at the stat cells — and
  // the collapsed deck's status strip, which used to carry this, is gone.
  //
  // The fill's *geometry* is untouched: `--ribbon` recolours it, so it still
  // reads as a progress value rather than as a second quantity. If it ever
  // starts reading as "42% doomed", drop `.crit` to a rim and border only and
  // leave the fill on the accent.
  const crit = w.lives <= BALANCE.critLives;

  const speeds = SPEEDS.map(
    (v) =>
      `<button data-act="speed" data-v="${v}" class="${v === speed ? 'on' : ''}">${v}×</button>`,
  ).join('');

  return (
    // No sigil. Costs lost theirs in the deck, and a currency mark repeated on
    // every price is a character the player has already agreed to.
    `<div class="stat"><label>Cash</label><b>${w.money}</b></div>` +
    `<div class="stat"><label>Lives</label><b class="${crit ? 'crit' : ''}">${w.lives}</b></div>` +
    `<div class="stat"><label>Waves held</label><b>${held}</b></div>` +
    renderEraRail(w) +
    `<div class="ribbon${crit ? ' crit' : ''}"><span>${label}</span>` +
    `<i style="width:${(clamp01(fill) * 100).toFixed(1)}%"></i></div>` +
    `<div class="seg speeds">${speeds}</div>` +
    // aria-label rather than title: the glyph is universal, Esc means nothing
    // on a touch device, and a tooltip that never fires there is dead weight.
    `<button class="icon" data-act="pause" aria-label="${paused ? 'Resume' : 'Pause'}">` +
    `${paused ? '▶' : '❚❚'}</button>`
  );
}

