export class DamageValueDisplay {

  static DEFAULT_FONT_STYLE: TextOptions = { style: { fill: { color: '#ff0000', alpha: 1 }, fontSize: 24, align: 'left' } };
  static DEFAULT_DURATION_IN_MILLIS: number = 500;

  private attackNumberText = new Text({ ...DamageValueDisplay.DEFAULT_FONT_STYLE, text: this.damageValue });
  private travelDistance: Coords = { x: 10, y: -105 };
  private startingDurationInMillis: number = DamageValueDisplay.DEFAULT_DURATION_IN_MILLIS;

  public constructor(private damageValue: string, private view: Container, public remainingDurationInMillis: number, coords: Coords) {
    this.startingDurationInMillis = remainingDurationInMillis;
    this.attackNumberText.position = coords;
    this.attackNumberText.text = "" + damageValue;
    this.view.addChild(this.attackNumberText);
  }

  public update(delta: number) {
    if (delta == 0 || this.startingDurationInMillis == 0) {
      return;
    }

    this.remainingDurationInMillis -= delta;
    this.attackNumberText.position.x += this.travelDistance.x / (this.startingDurationInMillis / delta);
    this.attackNumberText.position.y += this.travelDistance.y / (this.startingDurationInMillis / delta);
    if (this.remainingDurationInMillis <= 0) {
      this.view.removeChild(this.attackNumberText);
      this.attackNumberText.destroy();
    }
  }
}

export class SceneSetup {
  readonly scene: Scene;
  readonly towerGroup = new Group();
  readonly enemyGroup = new Group();
  readonly projectileGroup = new Group();
  readonly effectGroup = new Group();
  readonly uiGroup = new Group();

  constructor() {
    this.scene = new Scene();
    this.scene.background = new Color(0x1a1a2e);

    const ambient = new AmbientLight(0xffffff, 0.6);
    this.scene.add(ambient);
    const directional = new DirectionalLight(0xffffff, 0.8);
    directional.position.set(5, 10, 7);
    this.scene.add(directional);

    // Layer groups (persistent — children cleared per level)
    this.scene.add(
      this.towerGroup,
      this.enemyGroup,
      this.projectileGroup,
      this.effectGroup,
      this.uiGroup,
    );
  }

  applyFog(mapDiag: number, camDist: number): void {
    const fogNear = camDist + mapDiag * 0.5;
    const fogFar = camDist + mapDiag * 2.0;
    this.scene.fog = new Fog(0x1a1a2e, fogNear, fogFar);
  }

  clearGroups(): void {
    this.towerGroup.clear();
    this.enemyGroup.clear();
    this.projectileGroup.clear();
    this.effectGroup.clear();
    this.uiGroup.clear();
  }
}

export class DamageNumbers {
  private container: HTMLDivElement;
  private numbers: FloatingNumber[] = [];
  private camera: Camera | null = null;
  private tempVec = new Vector3();

  constructor() {
    this.container = document.createElement("div");
    this.container.className = "fixed inset-0 pointer-events-none z-[12] overflow-hidden";
    document.body.appendChild(this.container);
  }

  setCamera(camera: Camera): void {
    this.camera = camera;
  }

  spawn(x: number, y: number, z: number, damage: number, color = "#fff"): void {
    const el = document.createElement("div");
    el.textContent = `-${Math.round(damage)}`;
    el.className = "absolute text-sm font-bold font-game whitespace-nowrap will-change-[transform,opacity]";
    el.style.color = color;
    el.style.textShadow = "0 1px 3px rgba(0,0,0,0.8)";
    el.style.transform = "translate(-50%, -50%)";
    this.container.appendChild(el);

    this.numbers.push({ el, x, y: y + 0.5, z, age: 0, lifespan: LIFESPAN });
  }

  update(delta: number): void {
    if (!this.camera) return;

    const w = window.innerWidth;
    const h = window.innerHeight;

    for (let i = this.numbers.length - 1; i >= 0; i--) {
      const num = this.numbers[i];
      num.age += delta;

      if (num.age >= num.lifespan) {
        num.el.remove();
        this.numbers[i] = this.numbers[this.numbers.length - 1];
        this.numbers.pop();
        continue;
      }

      const t = num.age / num.lifespan;

      // Float upward in world space
      num.y += delta * 1.5;

      // Project to screen
      this.tempVec.set(num.x, num.y, num.z).project(this.camera);
      const screenX = (this.tempVec.x * 0.5 + 0.5) * w;
      const screenY = (-this.tempVec.y * 0.5 + 0.5) * h;

      // Behind camera check
      if (this.tempVec.z > 1) {
        num.el.style.display = "none";
        continue;
      }
      num.el.style.display = "";

      const scale = 1 + t * 0.3;
      num.el.style.transform = `translate(-50%, -50%) translate(${screenX}px, ${screenY}px) scale(${scale})`;
      num.el.style.opacity = String(1 - t);
    }
  }

  dispose(): void {
    for (const num of this.numbers) {
      num.el.remove();
    }
    this.numbers = [];
    this.container.remove();
  }
}

export class WaveManager {
  private waves: WaveConfig[];
  private enemyManager: EnemyManager;
  private eventBus: EventBus;

  private currentWave = 0;
  private entryIndex = 0;
  private spawnedInEntry = 0;
  private spawnTimer = 0;
  private state: WaveState = "idle";

  constructor(
    waves: WaveConfig[],
    enemyManager: EnemyManager,
    eventBus: EventBus,
  ) {
    this.waves = waves;
    this.enemyManager = enemyManager;
    this.eventBus = eventBus;
  }

  get waveNumber(): number {
    return this.currentWave + 1;
  }

  get totalWaves(): number {
    return this.waves.length;
  }

  get isIdle(): boolean {
    return this.state === "idle";
  }

  get isDone(): boolean {
    return this.state === "done";
  }

  startWave(): boolean {
    if (this.state !== "idle") return false;
    if (this.currentWave >= this.waves.length) return false;

    this.entryIndex = 0;
    this.spawnedInEntry = 0;
    this.spawnTimer = 0;
    this.state = "spawning";
    this.eventBus.emit("wave-start", { wave: this.currentWave + 1 });
    return true;
  }

  update(delta: number): void {
    if (this.state === "spawning") {
      this.updateSpawning(delta);
    } else if (this.state === "active") {
      // Wait for all enemies to be killed or reach goal
      if (this.enemyManager.getEnemies().length === 0) {
        this.eventBus.emit("wave-complete", { wave: this.currentWave + 1 });
        this.currentWave++;
        if (this.currentWave >= this.waves.length) {
          this.state = "done";
        } else {
          this.state = "idle";
        }
      }
    }
  }

  private updateSpawning(delta: number): void {
    const wave = this.waves[this.currentWave];
    const entry = wave.entries[this.entryIndex];

    this.spawnTimer -= delta;
    if (this.spawnTimer <= 0) {
      this.enemyManager.spawn(entry.enemyConfig);
      this.spawnedInEntry++;
      this.spawnTimer = entry.spawnInterval;

      if (this.spawnedInEntry >= entry.count) {
        this.entryIndex++;
        this.spawnedInEntry = 0;

        if (this.entryIndex >= wave.entries.length) {
          this.state = "active";
        }
      }
    }
  }

  /** Add a wave dynamically (for endless mode). */
  addWave(wave: WaveConfig): void {
    this.waves.push(wave);
  }

  dispose(): void {
    // No own resources
  }
}

export class GameStateManager {
  private state: GameState;
  private eventBus: EventBus;
  private handleEnemyKilled: (data: { reward: number }) => void;
  private handleEnemyReachedGoal: (data: { damage: number }) => void;
  private handleWaveComplete: (data: { wave: number }) => void;

  constructor(eventBus: EventBus, totalWaves: number, options: GameStateOptions = {}) {
    this.eventBus = eventBus;
    this.state = {
      gold: options.startingGold ?? STARTING_GOLD,
      lives: options.startingLives ?? STARTING_LIVES,
      wave: 0,
      totalWaves,
      level: options.level ?? 1,
      levelName: options.levelName ?? "",
      isGameOver: false,
      isWin: false,
    };

    this.handleEnemyKilled = ({ reward }) => {
      this.addGold(reward);
    };

    this.handleEnemyReachedGoal = ({ damage }) => {
      this.loseLives(damage);
    };

    this.handleWaveComplete = ({ wave }) => {
      this.state.wave = wave;
      if (wave >= totalWaves) {
        this.state.isWin = true;
        this.state.isGameOver = true;
        this.eventBus.emit("game-over", { win: true });
      }
    };

    this.eventBus.on("enemy-killed", this.handleEnemyKilled);
    this.eventBus.on("enemy-reached-goal", this.handleEnemyReachedGoal);
    this.eventBus.on("wave-complete", this.handleWaveComplete);
  }

  getState(): Readonly<GameState> {
    return this.state;
  }

  get gold(): number {
    return this.state.gold;
  }

  get lives(): number {
    return this.state.lives;
  }

  canAfford(cost: number): boolean {
    return this.state.gold >= cost;
  }

  spendGold(amount: number): boolean {
    if (!this.canAfford(amount)) return false;
    this.state.gold -= amount;
    this.eventBus.emit("gold-changed", { gold: this.state.gold });
    return true;
  }

  addGold(amount: number): void {
    this.state.gold += amount;
    this.eventBus.emit("gold-changed", { gold: this.state.gold });
  }

  private loseLives(amount: number): void {
    if (this.state.isGameOver) return;
    this.state.lives -= amount;
    this.eventBus.emit("lives-changed", { lives: this.state.lives });

    if (this.state.lives <= 0) {
      this.state.lives = 0;
      this.state.isGameOver = true;
      this.state.isWin = false;
      this.eventBus.emit("game-over", { win: false });
    }
  }

  dispose(): void {
    this.eventBus.off("enemy-killed", this.handleEnemyKilled);
    this.eventBus.off("enemy-reached-goal", this.handleEnemyReachedGoal);
    this.eventBus.off("wave-complete", this.handleWaveComplete);
  }
}

export class InfluenceMap {
  readonly rows: number;
  readonly cols: number;
  private danger: number[][];
  private cellSize: number;
  private offsetX: number;
  private offsetZ: number;

  constructor(config: MapConfig) {
    this.rows = config.rows;
    this.cols = config.cols;
    this.cellSize = config.cellSize;
    // Map centering offsets (same as GameMap/gridToWorld)
    this.offsetX = ((config.cols - 1) * config.cellSize) / 2;
    this.offsetZ = ((config.rows - 1) * config.cellSize) / 2;
    this.danger = [];
    this.clear();
  }

  /** Reset all danger values to 0. */
  clear(): void {
    this.danger = [];
    for (let r = 0; r < this.rows; r++) {
      this.danger[r] = new Array<number>(this.cols).fill(0);
    }
  }

  /**
   * Rebuild the danger map from current tower positions.
   * Each tower emits influence: danger = max(0, range - distance).
   * Overlapping tower ranges stack additively.
   */
  rebuild(towers: readonly Tower[]): void {
    this.clear();

    for (const tower of towers) {
      const towerPos = tower.getObject3D().position;
      const range = tower.config.range;
      const damage = tower.config.damage;

      // Convert world position to grid position
      const gridCol = Math.round((towerPos.x + this.offsetX) / this.cellSize);
      const gridRow = Math.round((towerPos.z + this.offsetZ) / this.cellSize);

      // Cells within range
      const cellRange = Math.ceil(range / this.cellSize);

      for (let dr = -cellRange; dr <= cellRange; dr++) {
        for (let dc = -cellRange; dc <= cellRange; dc++) {
          const r = gridRow + dr;
          const c = gridCol + dc;
          if (r < 0 || r >= this.rows || c < 0 || c >= this.cols) continue;

          // World-space distance from tower center to cell center
          const cellWorldX = c * this.cellSize - this.offsetX;
          const cellWorldZ = r * this.cellSize - this.offsetZ;
          const dx = cellWorldX - towerPos.x;
          const dz = cellWorldZ - towerPos.z;
          const dist = Math.sqrt(dx * dx + dz * dz);

          if (dist <= range) {
            // Danger falls off linearly with distance, weighted by tower damage
            const influence = (1 - dist / range) * damage;
            this.danger[r][c] += influence;
          }
        }
      }
    }
  }

  /** Get the danger value at a grid position. */
  getDanger(row: number, col: number): number {
    if (row < 0 || row >= this.rows || col < 0 || col >= this.cols) return 0;
    return this.danger[row][col];
  }

  /** Get the danger value at a world position. */
  getDangerAtWorld(worldX: number, worldZ: number): number {
    const col = Math.round((worldX + this.offsetX) / this.cellSize);
    const row = Math.round((worldZ + this.offsetZ) / this.cellSize);
    return this.getDanger(row, col);
  }

  /** Get the raw danger grid (for debugging/visualization). */
  getDangerGrid(): readonly number[][] {
    return this.danger;
  }
}

export function cautious(state: GameState, id: LeaderId = 'player1'): Order[] {
  const me = state.leaders[id];
  if (!me || !me.alive) return [];
  const orders: Order[] = [];
  const tryAdd = adder(state, id, me.ap, orders);
  const others = aliveOthers(state, id);

  if (state.round <= 2) tryAdd({ kind: 'build-factory' });
  if (me.stockpile.shields === 0) tryAdd({ kind: 'build-defence', type: 'shield' });

  const attacked = respondToAttackers(state, id, tryAdd, 2);

  if (!attacked) {
    // No first strike — only finish an already-wounded rival.
    const wounded = others
      .filter((t) => state.leaders[t].population <= 10)
      .sort((a, b) => state.leaders[a].population - state.leaders[b].population);
    if (wounded.length > 0) {
      const target = wounded[0];
      if (!tryAdd({ kind: 'launch', target, delivery: 'missile', warhead: 'small', targetType: 'people' })) {
        tryAdd({ kind: 'build-missile' });
        tryAdd({ kind: 'build-warhead', yield: 'small' });
        tryAdd({ kind: 'launch', target, delivery: 'missile', warhead: 'small', targetType: 'people' });
      }
    }
    if (state.round % 3 === 0) {
      const friendly = others
        .filter((t) => (me.grudge[t] ?? 0) === 0)
        .sort((a, b) => state.leaders[b].population - state.leaders[a].population);
      if (friendly.length > 0) tryAdd({ kind: 'woo', target: friendly[0] });
    }
  }
  return orders;
}

export function balanced(state: GameState, id: LeaderId = 'player1'): Order[] {
  const me = state.leaders[id];
  if (!me || !me.alive) return [];
  const orders: Order[] = [];
  const tryAdd = adder(state, id, me.ap, orders);
  const others = aliveOthers(state, id);

  // Economy + standing defence.
  if (state.round <= 3) tryAdd({ kind: 'build-factory' });
  if (me.stockpile.shields === 0) tryAdd({ kind: 'build-defence', type: 'shield' });

  const attacked = respondToAttackers(state, id, tryAdd, 4);

  if (!attacked) {
    // Unthreatened: opportunistically strike the weakest rival (pre-emptive but
    // not indiscriminate — only the most vulnerable, and only a measured salvo).
    const weakest = [...others].sort(
      (a, b) => state.leaders[a].population - state.leaders[b].population,
    )[0];
    if (weakest !== undefined) {
      let shots = 0;
      let guard = 0;
      while (shots < 2 && guard < 6) {
        guard++;
        const launch: Order = {
          kind: 'launch', target: weakest, delivery: 'missile', warhead: 'small', targetType: 'people',
        };
        if (tryAdd(launch)) { shots++; continue; }
        const b1 = tryAdd({ kind: 'build-missile' });
        const b2 = tryAdd({ kind: 'build-warhead', yield: 'small' });
        if (!b1 && !b2) break;
      }
    }
  }
  // Keep an extra warhead in reserve if AP remains.
  tryAdd({ kind: 'build-warhead', yield: 'small' });
  return orders;
}

function storyBody(f: RoundFacts, leaders: GameState['leaders']): string {
  const sentences: string[] = [];
  if (f.peopleLost > 0) {
    sentences.push(
      f.attackers.length === 1
        ? `A strike from ${leaders[f.attackers[0]].name} removed ${f.peopleLost} million citizens from the census.`
        : `A strike removed ${f.peopleLost} million citizens from the census.`,
    );
  }
  if (f.factoriesLost > 0) {
    sentences.push(
      f.factoriesLost === 1
        ? '1 factory now qualifies as open-plan.'
        : `${f.factoriesLost} factories now qualify as open-plan.`,
    );
  }
  if (f.interceptedAsDefender) {
    sentences.push('Air defences held; one incoming warhead retired over open water.');
  }
  if (f.launches > 0) {
    sentences.push(
      f.launches === 1
        ? '1 launch order was filed and, regrettably, executed.'
        : `${f.launches} launch orders were filed and, regrettably, executed.`,
    );
  }
  if (f.propagandaReceived > 0) {
    sentences.push(`${f.propagandaReceived} million citizens defected after reading a leaflet.`);
  }
  if (f.propagandaSent > 0) {
    sentences.push(`Leaflet drops persuaded ${f.propagandaSent} million foreigners to relocate.`);
  }
  if (f.factoryBuilt) {
    sentences.push('Ground was broken on a new factory.');
  }
  if (f.wooTarget !== null) {
    sentences.push(`Diplomatic flowers were dispatched to ${leaders[f.wooTarget].name}.`);
  }
  if (sentences.length === 0) {
    return 'No orders of consequence were filed. Analysts describe the restraint as "suspicious."';
  }
  return sentences.slice(0, 3).join(' ');
}

export function applyLaunches(
  state: GameState,
  launches: Launch[],
  incoming?: IncomingCounter,
): LaunchesResult {
  const next: GameState = structuredClone(state);
  const events: ResolutionEvent[] = [];
  // Thread the counter across calls so the Nth-incoming tally is round-scoped,
  // not per-call. Clone the provided counter so callers can diff old vs new.
  const counter: IncomingCounter = incoming
    ? structuredClone(incoming)
    : makeIncomingCounter(next.cast);

  for (const l of launches) {
    const receiver = next.leaders[l.to];
    if (!receiver || !receiver.alive) continue;

    events.push({
      kind: 'MissileLaunched',
      from: l.from,
      to: l.to,
      delivery: l.delivery,
      warhead: l.warhead,
      targetType: l.targetType,
    });

    counter[l.to][l.delivery] += 1;
    const nth = counter[l.to][l.delivery];
    const defenders = l.delivery === 'missile' ? receiver.deployedShields : receiver.deployedAA;
    const p = interceptProbability(nth, defenders);
    const roll = nextRandom(next.rngState);
    next.rngState = roll.state;
    if (roll.value < p) {
      if (l.delivery === 'missile') receiver.deployedShields = Math.max(0, receiver.deployedShields - 1);
      else receiver.deployedAA = Math.max(0, receiver.deployedAA - 1);
      events.push({
        kind: 'MissileIntercepted',
        from: l.from,
        to: l.to,
        delivery: l.delivery,
        warhead: l.warhead,
      });
      continue;
    }

    if (l.targetType === 'people') {
      const deaths = peopleDeaths(l.warhead, receiver.population);
      receiver.population -= deaths;
      events.push({
        kind: 'ImpactPeople',
        from: l.from,
        target: l.to,
        warhead: l.warhead,
        deaths,
      });
      // P4c.1: bomber is reusable — restore on impact (lost only on intercept).
      if (l.delivery === 'bomber') {
        const attacker = next.leaders[l.from];
        if (attacker) attacker.stockpile.bombers += 1;
      }
    } else {
      const destroyed = factoriesDestroyed(l.warhead, receiver.factories);
      receiver.factories -= destroyed;
      events.push({
        kind: 'ImpactInfrastructure',
        from: l.from,
        target: l.to,
        warhead: l.warhead,
        factoriesDestroyed: destroyed,
      });
      // P4c.1: bomber is reusable — restore on impact (lost only on intercept).
      if (l.delivery === 'bomber') {
        const attacker = next.leaders[l.from];
        if (attacker) attacker.stockpile.bombers += 1;
      }
    }
  }

  return { state: next, events, incoming: counter };
}

export class UIManager {
    uiToWorldPos = new Map<UnitMenu, ex.Vector>();

    unitMenu: UnitMenu;
    dialogBox: DialogBox;
    constructor(private engine: ex.Engine) {
        this.unitMenu = new UnitMenu();
        document.body.appendChild(this.unitMenu);
        document.documentElement.style.setProperty('--pixel-conversion', this.worldDistanceToPage(1).toString());
        window.addEventListener('resize', () => {
            document.documentElement.style.setProperty('--pixel-conversion', this.worldDistanceToPage(1).toString());

            const menuPos = this.uiToWorldPos.get(this.unitMenu)
            if (menuPos) {
                const pagePos = this.engine.screen.worldToPageCoordinates(menuPos);
                this.unitMenu.left = pagePos.x + this.worldDistanceToPage(32);
                this.unitMenu.top = pagePos.y;
            }
        });

        this.dialogBox = new DialogBox();
        document.body.appendChild(this.dialogBox);
    }

    worldDistanceToPage(distance: number) {
        const pageOrigin = this.engine.screen.worldToPageCoordinates(ex.Vector.Zero);
        const pageDistance = this.engine.screen.worldToPageCoordinates(ex.vec(distance * SCALE.x, 0)).sub(pageOrigin);
        return pageDistance.x;
    }

    dismissAll() {
        this.unitMenu.hide();
    }

    showUnitMenu(unit: Unit, options: MenuOptions): UnitMenu {
        const menu = this.unitMenu;
        const pagePos = this.engine.screen.worldToPageCoordinates(unit.pos);
        menu.left = pagePos.x + this.worldDistanceToPage(32);
        menu.top = pagePos.y;
        menu.unit = unit;

        const move = () => {
            options.move();
            clearEvents();
        }
        const attack = () => {
            options.attack();
            clearEvents();
        }
        const pass = () => {
            options.pass();
            clearEvents();
        }

        menu.addEventListener('move', move);
        menu.addEventListener('attack', attack);
        menu.addEventListener('pass', pass);

        const clearEvents = () => {
            menu.removeEventListener('move', move);
            menu.removeEventListener('attack', attack);
            menu.removeEventListener('pass', pass);
        }

        menu.clearEvents = clearEvents;
        menu.show();
        menu.focus();

        this.uiToWorldPos.set(menu, unit.pos);

        return menu;
    }

    showDialog(text: string) {
        const box = this.dialogBox;
        box.text = (text);
        box.show();
        box.focus();
        return box;
    }
    hideDialog(){
        this.dialogBox.hide();
    }

    showNextMission(pos: ex.Vector) {

    }
}

