export function parseRouteFromHash(hash: string, isHostForRoom: (roomId: string) => boolean): Route {
  const room = /[#&]room=([^&]+)/.exec(hash);
  if (room) {
    const roomId = decodeURIComponent(room[1]);
    return { mode: 'online', roomId, isHost: isHostForRoom(roomId) };
  }
  if (hash === '#multiplayer') return { mode: 'multi-menu' };
  if (hash === '#singleplayer') return { mode: 'single-menu' };
  if (hash === '#deck-builder') return { mode: 'deck-builder' };
  if (hash === '#hotseat') return { mode: 'hotseat' };

  const quickOpponent = /^#quick-opponent=([a-z]+)$/.exec(hash);
  if (quickOpponent) {
    const pool = quickOpponent[1];
    return isCardPool(pool) ? { mode: 'quick-opponent', pool } : { mode: 'quick-setup' };
  }

  const quick = /^#quick(?:=([a-z]+))?(?:&companion=([a-z0-9-]+))?$/.exec(hash);
  if (quick) {
    const pool = quick[1];
    const companion = quick[2];
    return isCardPool(pool) ? { mode: 'quick-game', pool, ...(companion ? { companion } : {}) } : { mode: 'quick-setup' };
  }

  const campaign = /^#campaign(?:=([a-z]+))?$/.exec(hash);
  if (campaign) {
    const difficulty = campaign[1];
    return isDifficulty(difficulty) ? { mode: 'campaign-game', difficulty } : { mode: 'campaign' };
  }

  return { mode: 'main-menu' };
}

function experienceFor(pending: PendingBattle, ganador: Side): number {
  const perdedor: Side = ganador === 'attacker' ? 'defender' : 'attacker';
  let exp = bajasEnPuntosDeVida(pending.battle, perdedor);
  if (pending.battle.heroes[perdedor] !== null) exp += EXP_POR_DERROTAR_A_UN_HEROE;
  if (ganador === 'attacker' && pending.foe.kind === 'town') exp += EXP_POR_ASEDIO;
  return exp;
}

export function sidesOwnedBy(
  state: GameState,
  pending: PendingBattle,
  jugadores: Iterable<PlayerId>,
): ReadonlySet<Side> {
  const suyos = new Set(jugadores);
  const dueños = battleOwners(state, pending);
  const bandos = new Set<Side>();
  for (const bando of SIDES) {
    const dueño = dueños[bando];
    if (dueño !== null && suyos.has(dueño)) bandos.add(bando);
  }
  return bandos;
}

function meAtacan(semilla: number): Session {
  const s = new Session(semilla);
  const mio = heroesOf(s.state, 0)[0]!;
  const suyo = heroesOf(s.state, 1)[0]!;
  s.state.current = 1;
  suyo.movePoints = 100000;
  applyAdventureAction(s.state, { type: 'move_hero', hero: suyo.id, to: mio.at }, s.ctx, 1);
  if (s.state.pendingBattle === null) throw new Error('el rival no llegó a atacar');
  s.scene = 'battle';
  return s;
}

function bestCast(
  state: BattleState,
  s: BattleStack,
  acciones: readonly BattleAction[],
): BattleAction | null {
  const hero = state.heroes[s.side];
  if (hero === null) return null;

  let mejor: BattleAction | null = null;
  let mejorValor = 0;
  for (const a of acciones) {
    if (a.type !== 'cast' || a.target === undefined) continue;
    const sp = spell(a.spell);
    const valor = spellValue(hero, sp, stackById(state, a.target));
    if (valor < VALOR_MINIMO_POR_MANA * sp.cost) continue;
    if (valor > mejorValor) {
      mejorValor = valor;
      mejor = a;
    }
  }
  return mejor;
}

function applyStackEffect(state: BattleState, target: BattleStack, effect: StackEffect): void {
  if (isImmuneTo(target, effect)) {
    state.log.push({ kind: 'immune', stack: target.id, source: effect.source });
    return;
  }
  // Lo que se anota es el efecto YA colgado, no el que se pidió: si refrescó a
  // uno del mismo origen, las rondas que se leen en el parte son las que de
  // verdad le quedan.
  const vivo = applyEffect(target, effect);
  state.log.push({
    kind: 'effect',
    stack: target.id,
    effect: vivo.kind,
    amount: vivo.amount,
    source: vivo.source,
    rounds: vivo.roundsLeft,
  });
}

function jugar(state: BattleState, rng: Rng, tacticas: Record<Side, Tactica>): Resultado {
  let esperas = 0;
  let defensas = 0;
  for (let turno = 0; turno < 5000; turno++) {
    if (state.finished !== null) {
      return { winner: state.finished.winner, rounds: state.round, esperas, defensas };
    }
    const s = activeStack(state);
    if (s === null) throw new Error('no hay stack activo y la batalla no ha terminado');
    const accion = tacticas[s.side](state);
    if (accion.type === 'wait') esperas++;
    if (accion.type === 'defend') defensas++;
    applyAction(state, accion, rng);
  }
  throw new Error(`una batalla no ha terminado en 5000 turnos (ronda ${state.round})`);
}

function melee(
  state: BattleState,
  attacker: BattleStack,
  target: BattleStack,
  rng: Rng,
  hexesMoved: number,
): void {
  const info = creature(attacker.creature);
  const hits = hasTrait(info, 'double_attack') ? 2 : 1;

  for (let i = 0; i < hits && isAlive(target); i++) {
    strike(state, attacker, target, rng, false, hexesMoved);
  }

  // Contraataque: uno por ronda, y solo si el atacante lo permite.
  if (
    isAlive(target) &&
    isAlive(attacker) &&
    !target.retaliated &&
    !hasTrait(info, 'no_retaliation') &&
    canReachMelee(target, attacker)
  ) {
    // El contraataque no carga: se devuelve el golpe desde donde se está.
    target.retaliated = true;
    strike(state, target, attacker, rng, true, 0);
  }
}

export function renderActions(session: Session): Html {
  if (session.state.finished !== null) {
    return html`<button data-action="restart" class="primary">Partida nueva</button>`;
  }
  switch (session.scene) {
    case 'town':
      return html`<button data-action="close-town">Volver al mapa</button>`;
    case 'battle': {
      const battle = session.battle;
      if (battle !== null && battle.finished !== null) {
        return html`<button data-action="finish-battle" class="primary">Continuar</button>`;
      }
      return html`<button data-action="auto-battle">Resolver sola</button>`;
    }
    default:
      return html`
        <button data-action="toggle-fog">${session.revealAll ? 'Ocultar mapa' : 'Ver mapa entero'}</button>
        <button data-action="end-turn" class="primary" ${session.isPlayersTurn ? NADA : DESHABILITADO}>
          Fin de turno
        </button>`;
  }
}

export function castBlocker(
  state: BattleState,
  side: Side,
  spellId: string,
  targetId?: string,
): string | null {
  const hero = state.heroes[side];
  if (hero === null) return SIN_HEROE;
  if (hero.castThisRound) return 'el héroe ya lanzó un hechizo esta ronda';
  // El id se comprueba contra el libro ANTES de buscarlo en el catálogo: con un
  // id inventado, "no lo conoce" es más cierto y más útil que reventar.
  if (!hero.spells.includes(spellId)) return `el héroe no conoce "${spellId}"`;
  const s = spell(spellId);
  if (hero.mana < s.cost) return `maná insuficiente: cuesta ${s.cost} y quedan ${hero.mana}`;

  if (targetId !== undefined) {
    const target = state.stacks.find((t) => t.id === targetId);
    if (target === undefined) return `no hay ninguna unidad "${targetId}"`;
    return targetBlocker(hero, s, side, target);
  }
  return state.stacks.some((t) => targetBlocker(hero, s, side, t) === null)
    ? null
    : 'no hay ningún objetivo válido';
}

function startTurn(state: GameState): void {
  const player = currentPlayer(state);
  emit(state, { kind: 'turn_start', actor: player.id, at: null });

  // Ingresos del día: ayuntamientos y minas.
  let income = { ...EMPTY_RESOURCES };
  for (const town of townsOf(state, player.id)) {
    income = addResources(income, { gold: dailyIncome(town) });
    town.builtToday = false;
  }
  for (const obj of state.map.objects) {
    if (obj.kind === 'mine' && obj.owner === player.id) {
      income = addResources(income, { [obj.resource]: MINE_YIELD[obj.resource] });
    }
  }
  player.resources = addResources(player.resources, income);

  for (const hero of heroesOf(state, player.id)) {
    hero.movePoints = maxMovePoints(hero);
    // El maná se recupera poco a poco, salvo en un pueblo con gremio.
    const enPueblo = townsOf(state, player.id).some(
      (t) => pointKey(t.at) === pointKey(hero.at) && mageGuildLevel(t) > 0,
    );
    hero.mana = enPueblo ? maxMana(hero) : Math.min(maxMana(hero), hero.mana + 1);
    // Y mira alrededor al levantarse: un héroe quieto también ve. Sin esto, su
    // recuerdo de la mina que tiene al lado sería del día en que llegó.
    revealAround(state, hero);
  }
}

function castHeroSpell(
  state: BattleState,
  side: Side,
  spellId: string,
  targetId: string | undefined,
): void {
  // El nulo se comprueba aquí, y no solo dentro del bloqueador, porque el
  // estrechamiento no cruza la llamada. El motivo sigue escrito una sola vez.
  const hero = state.heroes[side];
  if (hero === null) throw new Error(`no se puede lanzar: ${SIN_HEROE}`);

  const blocker = castBlocker(state, side, spellId, targetId);
  if (blocker !== null) throw new Error(`no se puede lanzar: ${blocker}`);

  const s = spell(spellId);
  if (targetId === undefined) throw new Error(`"${s.name}" necesita un objetivo`);
  const target = stackById(state, targetId);

  hero.mana -= s.cost;
  hero.castThisRound = true;
  const result = castSpell(s, hero, target);

  state.log.push({
    kind: 'cast',
    side,
    spell: spellId,
    target: targetId,
    damage: result.damage,
    killed: result.killed,
  });

  // El hechizo no muta el stack: devuelve el efecto y lo cuelga el motor, que
  // es quien sabe anotarlo en el registro. Aquí no puede rebotar —`castBlocker`
  // rechaza al objetivo inmune antes de cobrar el maná—, pero `applyStackEffect`
  // sigue comprobándolo porque el mismo camino lo usan los golpes con rasgo.
  if (result.effect !== undefined) applyStackEffect(state, target, result.effect);
  if (!isAlive(target)) state.log.push({ kind: 'perished', stack: target.id });
  checkFinished(state);
}

function mejorCarga(
  state: BattleState,
  s: BattleStack,
  objetivo: BattleStack,
  cargas: readonly CargaContra[],
  costes: ReadonlyMap<string, Paso>,
): BattleAction {
  const miHeroe = state.heroes[s.side];
  const suHeroe = state.heroes[objetivo.side];
  // Sin el rasgo, `expectedDamage` da lo MISMO desde cualquier casilla: la
  // fórmula no mira el hex más que por la carga. No es una optimización, es lo
  // que significa — evaluarla casilla a casilla sería preguntar seis veces algo
  // cuya respuesta no depende de la pregunta. Con el daño empatado decide el
  // desempate, que es lo que decide hoy el 100 % de los casos.
  const cobraCarga = hasTrait(creature(s.creature), 'charge');

  let mejor = cargas[0] as CargaContra;
  let mejorDano = -1;
  let mejorCoste = Number.POSITIVE_INFINITY;
  for (const a of cargas) {
    const paso = costes.get(hexKey(a.from));
    // Inalcanzable salvo que la lista legal y su propio mapa discrepen: los
    // `from` salen de las claves de ese mapa. Si algún día discrepan, se dice;
    // no se elige una casilla a ciegas.
    if (paso === undefined) {
      throw new Error(`${s.id} no alcanza (${a.from.col},${a.from.row}): la lista legal miente`);
    }
    const coste = paso.steps;
    const dano = cobraCarga
      ? expectedDamage(s, miHeroe, objetivo, suHeroe, { chargeHexes: coste })
      : 0;
    if (dano > mejorDano || (dano === mejorDano && coste < mejorCoste)) {
      mejor = a;
      mejorDano = dano;
      mejorCoste = coste;
    }
  }
  return mejor;
}

export function createBattle(attacker: BattleSide, defender: BattleSide, _rng: Rng): BattleState {
  const stacks: BattleStack[] = [];

  for (const [side, setup] of [
    ['attacker', attacker],
    ['defender', defender],
  ] as const) {
    const filled = setup.army
      .map((stack, slot) => ({ stack, slot }))
      .filter(
        (s): s is { stack: NonNullable<(typeof s)['stack']>; slot: number } => s.stack !== null,
      );

    const rows = ROWS_BY_COUNT[filled.length] ?? ROWS_BY_COUNT[5]!;
    const baseMorale = armyMorale(setup.army) + (setup.moraleBonus ?? 0);

    filled.forEach(({ stack, slot }, index) => {
      const info = creature(stack.creature);
      const big = hexSize(info) > 1;
      // Las unidades grandes arrancan una columna hacia dentro: su cola ocupa
      // la columna del borde y se saldría del tablero.
      const col = side === 'attacker' ? (big ? 1 : 0) : big ? 9 : 10;
      const row = rows[index] ?? 4;

      stacks.push({
        id: `${side}-${slot}`,
        side,
        slot,
        creature: stack.creature,
        initialCount: stack.count,
        count: stack.count,
        topHp: info.hp,
        hex: { col, row },
        shotsLeft: info.shots ?? 0,
        retaliated: false,
        defending: false,
        waited: false,
        acted: false,
        gotMoraleBonus: false,
        morale: hasTrait(info, 'undead') ? 0 : clampMoraleLuck(baseMorale),
        luck: clampMoraleLuck(setup.luckBonus ?? 0),
        effects: [],
      });
    });
  }

  const state: BattleState = {
    round: 0,
    stacks,
    queue: [],
    activeId: null,
    heroes: { attacker: attacker.hero, defender: defender.hero },
    log: [],
    finished: null,
  };

  beginRound(state, _rng);
  return state;
}

function aplicar(
  state: GameState,
  action: AdventureAction,
  ctx: GameContext,
  alcance: Reachable | undefined,
): void {
  switch (action.type) {
    case 'end_turn':
      nextPlayer(state);
      return;

    case 'move_hero':
      moveHero(state, action.hero, action.to, ctx, alcance);
      return;

    case 'hire_hero': {
      hireHero(state, action.town);
      return;
    }

    case 'build': {
      const town = townById(state, action.town);
      const player = currentPlayer(state);
      if (town.owner !== player.id) throw new Error('ese pueblo no es tuyo');
      player.resources = buildInTown(town, action.building, player.resources);
      emit(state, {
        kind: 'built',
        town: town.id,
        building: action.building,
        actor: player.id,
        at: town.at,
      });
      return;
    }

    case 'recruit': {
      const town = townById(state, action.town);
      const player = currentPlayer(state);
      if (town.owner !== player.id) throw new Error('ese pueblo no es tuyo');

      // Va al héroe que esté en el pueblo; si no hay ninguno, a la guarnición.
      const hero = heroesOf(state, player.id).find((h) => pointKey(h.at) === pointKey(town.at));
      const destino: Army = hero?.army ?? town.garrison;
      const ampliado = addToArmy(destino, action.creature, action.count);
      if (ampliado === null) throw new Error('no quedan huecos en el ejército');

      player.resources = payRecruit(town, action.creature, action.count, player.resources);
      if (hero !== undefined) {
        hero.army = ampliado;
        hero.movePoints = Math.min(hero.movePoints, maxMovePoints(hero));
      } else {
        town.garrison = ampliado;
      }
      emit(state, {
        kind: 'recruited',
        town: town.id,
        creature: action.creature,
        count: action.count,
        actor: player.id,
        at: town.at,
      });
      return;
    }
  }
}

export function drawAdventure(ctx: CanvasRenderingContext2D, view: AdventureView): void {
  const { state, camera } = view;
  const player = state.players.find((p) => p.id === view.viewer);
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.translate(camera.offsetX, camera.offsetY);

  for (let row = 0; row <= camera.rows; row++) {
    for (let col = 0; col <= camera.cols; col++) {
      const p = { x: camera.origin.x + col, y: camera.origin.y + row };
      if (p.x >= state.map.width || p.y >= state.map.height) continue;

      const sx = col * TILE;
      const sy = row * TILE;
      const terreno = state.map.terrain[p.y * state.map.width + p.x] as TerrainKind;
      const textura = asset('terrains', terreno);
      if (textura === null) {
        ctx.fillStyle = TERRAIN_COLORS[terreno];
        ctx.fillRect(sx, sy, TILE, TILE);
      } else {
        ctx.drawImage(textura, sx, sy, TILE, TILE);
      }

      if (state.map.roads.has(pointKey(p))) {
        ctx.fillStyle = 'rgba(200,180,140,0.35)';
        ctx.fillRect(sx + TILE * 0.3, sy + TILE * 0.3, TILE * 0.4, TILE * 0.4);
      }

      ctx.strokeStyle = 'rgba(0,0,0,0.18)';
      ctx.lineWidth = 1;
      ctx.strokeRect(sx + 0.5, sy + 0.5, TILE - 1, TILE - 1);

      const explorada = view.revealAll || (player?.fog.has(pointKey(p)) ?? false);
      if (!explorada) {
        ctx.fillStyle = 'rgba(6,5,4,0.88)';
        ctx.fillRect(sx, sy, TILE, TILE);
      }
    }
  }

  // Objetos y héroes, solo donde se ve.
  for (const obj of state.map.objects) {
    if (!isVisible(view, obj.at)) continue;
    const pos = toScreen(camera, obj.at);
    if (pos === null) continue;
    drawObject(ctx, obj, pos.x, pos.y);
  }

  for (const hero of state.heroes) {
    if (!isVisible(view, hero.at)) continue;
    const pos = toScreen(camera, hero.at);
    if (pos === null) continue;
    drawHero(ctx, hero, pos.x, pos.y, hero.id === view.selectedHero);
  }

  drawPath(ctx, camera, view.hoverPath);
  ctx.restore();
}

export function settleBattle(state: GameState, _ctx: GameContext): void {
  const pending = state.pendingBattle;
  if (pending === null) throw new Error('no hay batalla pendiente');
  if (pending.battle.finished === null) throw new Error('la batalla no ha terminado');

  const { winner } = pending.battle.finished;
  const hero = heroById(state, pending.attackerHeroId);
  // La casilla, LEÍDA AQUÍ: con los dos bandos todavía en pie. Después hay
  // héroes que salen del mapa y castillos que cambian de bandera, y preguntar
  // entonces sería preguntar por alguien que ya no está. Es el mismo patrón que
  // el `const dueño = hero.owner` de más abajo, y por eso el dato no hace falta
  // guardarlo en `PendingBattle`.
  const at = battleAt(state, pending);
  const superviviente = (side: 'attacker' | 'defender'): Army => {
    const slots: (Stack | null)[] = [null, null, null, null, null];
    for (const s of pending.battle.stacks) {
      if (s.side !== side || s.count <= 0) continue;
      slots[s.slot] = { creature: s.creature, count: s.count };
    }
    return pruneArmy(slots);
  };

  restoreHeroFromBattle(hero, pending.battle.heroes.attacker, superviviente('attacker'));
  const heroeAtacanteVivo = winner === 'attacker';

  // El cierre de la batalla se registra ANTES de sus consecuencias: capturar
  // el último pueblo del rival termina la partida, y "game_over" tiene que ser
  // el último evento del registro, no quedar sepultado bajo el de la batalla.
  emit(state, {
    kind: 'battle_ended',
    winner,
    foe: pending.foe,
    actor: hero.owner,
    at,
  });
  state.pendingBattle = null;

  if (heroeAtacanteVivo) {
    ganarExperiencia(state, hero, experienceFor(pending, 'attacker'), at);
    applyVictory(state, hero, pending.foe, at);
  } else {
    // El atacante derrotado desaparece del mapa con su ejército. Su dueño se
    // lee ANTES del filtro: un instante después el héroe ya no está y el evento
    // que cuenta su muerte no tendría a quién atribuirse — que es justo por qué
    // el 10,9 % de la crónica era inatribuible.
    const dueño = hero.owner;
    state.heroes = state.heroes.filter((h) => h.id !== hero.id);
    emit(state, { kind: 'hero_defeated', hero: hero.id, actor: dueño, at });
    applyDefenderSurvivors(state, pending, superviviente('defender'), at);
  }

  checkDefeat(state);
}

function renderBattlePanel(session: Session): Html {
  const battle = session.battle;
  if (battle === null) return NADA;

  // El bando de la persona lo DERIVA la sesión del dueño de la batalla; aquí no
  // se supone. Decir «Tú» al atacante era la misma suposición que el ciclo de
  // #29 quitó del servidor, y le habría cantado «Victoria» a quien acababa de
  // perder el castillo el primer día que la persona defienda.
  const mio = session.miBando;

  if (battle.finished !== null) {
    const gane = battle.finished.winner === mio;
    return html`<h2>${gane ? 'Victoria' : 'Derrota'}</h2>
      <p>${gane ? 'El campo es tuyo.' : 'Tu héroe ha caído.'}</p>
      <h3>Parte de guerra</h3>${renderBattleLog(battle, mio)}`;
  }

  const s = activeStack(battle);
  const activo =
    s === null
      ? html`<p>Sin unidad activa.</p>`
      : html`<h2>${creature(s.creature).name}</h2>
        <div class="row"><span class="label">Bando</span><span>${s.side === mio ? 'Tú' : 'Enemigo'}</span></div>
        <div class="row"><span class="label">Efectivos</span><span>${s.count}</span></div>
        <div class="row"><span class="label">Moral / Suerte</span><span>${s.morale} / ${effectiveLuck(s)}</span></div>
        ${isShooter(creature(s.creature)) ? html`<div class="row"><span class="label">Munición</span><span>${s.shotsLeft}</span></div>` : NADA}`;

  const suTurno = s !== null && s.side === mio;
  const acciones = suTurno
    ? html`<h3>Acciones</h3>
       <div class="stack-list">
         <button data-action="battle-defend">Defender</button>
         <button data-action="battle-wait" ${s.waited ? DESHABILITADO : NADA}>Esperar</button>
       </div>
       ${renderSpells(session)}
       <p class="cost" style="margin-top:.5rem">
         Haz clic en un hexágono verde para moverte, o sobre un enemigo para atacarlo.
       </p>`
    : html`<p>Turno del enemigo…</p>`;

  // El maná del héroe, junto a la ficha de la unidad activa: es un recurso de la
  // batalla entera, no del stack, y sin verlo no se decide si lanzar.
  const heroe = session.battleHero;
  const mana =
    heroe === null
      ? NADA
      : html`<div class="row"><span class="label">Maná</span><span>${heroe.mana} / ${maxMana(heroe)}</span></div>`;

  const orden = unir(
    battle.stacks
      .filter((x) => x.count > 0)
      .map(
        (x) =>
          html`<div class="stack${x.id === battle.activeId ? '' : ' empty'}">
          <span>${x.side === mio ? '▶' : '◀'} ${creature(x.creature).name}</span>
          <span class="count">${x.count}</span>
        </div>`,
      ),
  );

  return html`${activo}
    <div class="row"><span class="label">Ronda</span><span>${battle.round}</span></div>
    ${mana}
    ${acciones}
    <h3>En el campo</h3><div class="stack-list">${orden}</div>
    <h3>Parte de guerra</h3>${renderBattleLog(battle, mio)}`;
}

export function decidir(kind: string, payload: any): unknown {
  switch (kind) {
    case 'adventure_turn': {
      const acciones: unknown[] = [];
      const town = payload.towns?.[0];
      if (town?.canBuildNow?.[0] !== undefined) {
        acciones.push({ type: 'build', town: town.id, building: town.canBuildNow[0].id });
      }
      const reclutable = town?.recruitable?.find((r: any) => r.available > 0);
      if (reclutable !== undefined) {
        acciones.push({
          type: 'recruit',
          town: town.id,
          creature: reclutable.creature,
          count: Math.min(2, reclutable.available),
        });
      }
      const hero = payload.heroes?.[0];
      if (hero !== undefined) {
        const objetivo = payload.knownMap?.objects?.find(
          (o: any) =>
            (o.kind === 'resource' && !o.taken) || (o.kind === 'mine' && o.owner === null),
        );
        acciones.push({
          type: 'move_hero',
          hero: hero.id,
          to: objetivo?.at ?? { x: hero.at.x + 1, y: hero.at.y },
        });
      }
      return { actions: acciones, reasoning: 'qa: construyo, recluto y exploro' };
    }
    case 'battle_turn': {
      const acciones = payload.legalActions as any[];
      const elegida =
        acciones.find((a) => a.type === 'shoot') ??
        acciones.find((a) => a.type === 'attack') ??
        acciones.find((a) => a.type === 'move') ??
        acciones[0];
      return { action: elegida };
    }
    case 'map_generate': {
      // El plan sale del generador procedimental y NO se dibuja a mano: su
      // conectividad ya cumple `validateMapPlan` —cada inicio llega a cada
      // pueblo—, y escribir un mapa aquí sería inventarse esa conectividad
      // además del mapa. Lo único que se cambia son los ids y los nombres, que
      // es lo que lo hace reconocible.
      //
      // La semilla es fija y distinta de la del servidor a propósito: así el
      // mapa que se juega no puede coincidir por casualidad con el que habría
      // salido sin agente.
      const want = payload?.want ?? {};
      const plan = generateMapPlan(createRng(7), {
        width: Number(want.width ?? 24),
        height: Number(want.height ?? 24),
      });
      return {
        plan: {
          ...plan,
          towns: plan.towns.map((t, i) => ({
            ...t,
            id: `${FIRMA_DEL_MAPA}${i}`,
            name: `Pueblo QA ${i}`,
          })),
        },
        reasoning: 'qa: el plan del generador, firmado para que se vea cuál se juega',
      };
    }
    default:
      // Antes esto devolvía `{}`. Un `{}` no valida contra ningún esquema, así
      // que zod lo rechazaba en el servidor… y el arnés lo contaba como turno
      // bueno, porque `heroes_respond` no da `isError` en ese caso. El circuito
      // se rompía y la verificación salía verde.
      throw new Error(
        `esta política no sabe responder a "${kind}": añádele una rama antes de emitir ese kind`,
      );
  }
}

export function totalCards(player: Player) {
  return HandKinds.map((handKind) => playerHandLen(player, handKind)).reduce(
    (sum, len) => sum + len,
    0
  );
}

export function dealCardsFor(
  playerCount: number,
  deck: Readonly<Deck>
): [Deck, Player[]] {
  let newDeck = deck.slice();
  const players = [];
  for (let i = 0; i < playerCount; i++) {
    let player;
    [newDeck, player] = dealCards(newDeck);
    players.push(player);
  }
  return [newDeck!, players];
}

export class Die extends BaseState {
	constructor(stateMachine) {
		super(stateMachine);

		stateMachine.owner.stopInteractions();
		this.entity.removeCollider();
	}

	update() {
		if (this.entity.animation.isComplete) {
			const { entityManager, stageManager } = managers.get(['entityManager', 'stageManager']);
			entityManager.destroy(this.entity.id);
			stageManager.spawnLoot(this.entity);
		}
	}
}

function firstRun(): string {
  const first = CAMPAIGN[0]!;
  const diff = DIFFICULTIES[/* the default the picker will preselect */ 'standard' as DifficultyId];
  return (
    `<h1>Deep Field</h1>` +
    `<p class="hm-pitch">A tower defense for your browser. Hold the line through ${CAMPAIGN.length} sectors, ` +
    `or race a friend on the same seed and see who survives longer.</p>` +
    `<div class="hm-actions">` +
    `<button class="hm-primary" data-act="play">Start ${first.name} →</button>` +
    `<button class="hm-ghost" data-act="race">Race a friend</button>` +
    `</div>` +
    `<div class="hm-meta">${diff === undefined ? '' : `${diff.name} difficulty · change on the next screen`}</div>`
  );
}

function renderSend(w: World): string {
  const s = w.wave;

  if (s.phase === 'spawning') {
    return (
      `<span class="btn send-btn flat">Wave ${s.index + 1} running</span>` +
      `<span class="hint">Wait for it to finish spawning</span>`
    );
  }
  if (s.phase === 'done') {
    return (
      `<span class="btn send-btn flat">No waves left</span>` +
      `<span class="hint">Clear the board to finish</span>`
    );
  }

  const bonus = Math.round(Math.max(0, s.timer) * BALANCE.rushBonusPerSecond);
  return (
    `<button class="btn send-btn primary" data-act="send">Send wave ${s.index + 1}` +
    (bonus > 0 ? ` <em>+$${bonus}</em>` : '') +
    `</button>` +
    `<span class="hint">Sending early pays the remaining timer as cash</span>`
  );
}

