function drawUpgradeCollar(g: Graphics, t: Tower, field: SectorField): void {
  const max = BALANCE.upgrade.maxTier;
  if (max <= 1) return;

  const cx = t.x * TILE_PX;
  const cy = t.y * TILE_PX;
  const r = TILE_PX * COLLAR_RADIUS;

  for (const { path, from } of COLLAR_SECTORS) {
    const tier = t.tiers[path];
    if (tier <= 1) continue;

    // Tier 2 fills half the sector, tier 3 all of it — "how far along this
    // path", not "how many tiers", which is what the player is choosing.
    const fill = (tier - 1) / (max - 1);
    const a0 = (from * Math.PI) / 180;
    const a1 = a0 + (COLLAR_SPAN * fill * Math.PI) / 180;

    // Laid down twice: a dark backing, then the arc. The collar crosses both the
    // starfield and the station's own halo, and a single stroke that reads on
    // one washes out on the other.
    strokeArc(g, cx, cy, r, a0, a1, { width: 5, color: field.bg, alpha: 0.75 });
    strokeArc(g, cx, cy, r, a0, a1, { width: 3, color: THEME.towers[t.defId], alpha: 1 });
  }
}

function buildRouteLine(map: MapDef, field: SectorField): Graphics {
  const g = new Graphics();
  // One normaliser for the board, matching `routeDistance` — see the argument
  // there for why the ramp is measured back from the goal rather than forward
  // from a spawn, and why a short lane starting part-lit is the truth.
  const longest = Math.max(...map.routes.map((r) => r.length));

  for (const route of map.routes) {
    const wp = route.waypoints;
    let travelled = 0;

    for (let i = 1; i < wp.length; i++) {
      const a = wp[i - 1]!;
      const b = wp[i]!;
      const steps = Math.abs(b.x - a.x) + Math.abs(b.y - a.y);

      // The midpoint's distance from the goal sets the segment's colour, so the
      // ramp follows the road rather than the screen.
      const t = longest > 0 ? 1 - (route.length - travelled - steps / 2) / longest : 0;
      travelled += steps;

      g.moveTo(a.x * TILE_PX, a.y * TILE_PX)
        .lineTo(b.x * TILE_PX, b.y * TILE_PX)
        .stroke({
          width: 2,
          cap: 'round',
          join: 'round',
          color: mixColor(field.lineNear, field.lineFar, t),
          alpha: field.lineNearAlpha + (field.lineFarAlpha - field.lineNearAlpha) * t,
        });
    }
  }

  return g;
}

export function renderSlots(w: World, ui: UiState): string {
  return TOWER_IDS.map((id) => {
    const def = TOWERS[id];

    // Locked says one thing: when. No cost, no shortfall, nothing to weigh —
    // it is not a decision yet.
    //
    // Under eras "when" is a *purchase* rather than a moment, so the slot names
    // the rung instead of the wave. Both are the same sentence — this is what
    // you do not have yet, and here is the thing that will give it to you.
    if (!isUnlocked(w, id)) {
      const gate = w.rules.eras ? `Era ${ROMAN[def.era] ?? def.era}` : `Wave ${def.unlockWave + 1}`;
      return (
        `<div class="slot locked" aria-label="${def.name}, unlocks at ${gate}">` +
        `${stationIcon(id, 40)}<span class="wave">${gate}</span></div>`
      );
    }

    const short = def.cost - w.money;
    const poor = short > 0;
    const cls = ['slot', `t-${id}`, ui.selected === id ? 'armed' : '', poor ? 'poor' : '']
      .filter(Boolean)
      .join(' ');

    return (
      `<button class="${cls}" data-act="arm" data-id="${id}" title="${def.blurb}">` +
      `<kbd>${def.hotkey}</kbd>` +
      `<span class="corner">${def.cost}</span>` +
      stationIcon(id, 40) +
      // Naming the gap turns "no" into "not yet, and by this much" — which is
      // the difference between a dead control and a plan.
      (poor ? `<span class="short">short ${short}</span>` : '') +
      `<span class="name">${def.name}</span></button>`
    );
  }).join('');
}

