export class CreatureRepository {
  abilities: Ability[] = [];
  creatureTemplates: CreatureTemplate[] = [];
  nameToTypesMap: Map<CreatureType, string> = new Map<CreatureType, string>([
    [CreatureType.PEASANT, "peasant"],
    [CreatureType.PEASANT_ARCHER, "peasant-archer"],
    [CreatureType.SWORDSMAN, "swordsman"],
    [CreatureType.SPEARMAN, "spearman"],
    [CreatureType.CROSSBOWMAN, "crossbowman"],
    [CreatureType.BARBARIAN, "barbarian"]
  ]);

  constructor() { }

  setAbilities(abilities: Ability[]) {
    this.abilities = abilities;
  }

  setCreatureTemplates(templates: CreatureTemplate[]) {
    this.creatureTemplates = templates;
  }

  createCreature(creatureType: CreatureType): Creature {

    // get the creature type name based on the creature type
    const creatureTypeName = this.nameToTypesMap.get(creatureType);

    // find the template by the creature name
    const creatureTemplate = this.creatureTemplates.find(template => template.name === creatureTypeName);
    if (!creatureTemplate) {
      throw new Error(`Could not find creature template for creature type ${creatureType}`);
    }

    let result = new Creature(creatureType, { ...creatureTemplate.stats }, []);
    result.stats.remaining_ammo = result.stats.ammo;
    result.stats.remaining_attacks = result.stats.num_attacks;
    result.stats.remaining_counterattacks = result.stats.num_counterattacks;
    result.stats.remaining_health = result.stats.health;
    result.stats.remaining_movement = result.stats.num_moves;

    result.abilities = creatureTemplate.ability_ids.map(abilityId => {
      const ability = this.abilities.find(ability => ability.id === abilityId);
      if (!ability) {
        return null;
      }
      return ability;
    }).filter(ability => ability !== null) as Ability[];

    return result;
  }
}

export function calcTotalCost(levels: TowerConfig[], targetLevel: number): number {
  let total = levels[0].cost;
  for (let i = 0; i < targetLevel; i++) {
    total += levels[i].upgradeCost ?? 0;
  }
  return total;
}

export function calcProgressionCurve(
  configs: LevelConfig[],
  difficulty: Difficulty = Difficulty.Normal
): ProgressionPoint[] {
  const points: ProgressionPoint[] = [];
  let prevDPS = 0;
  let prevBudget = 0;

  for (const config of configs) {
    const via = assessViability(config, difficulty);
    const req = recommendTowers(config, difficulty);
    const dpsNeeded = via.peakWaveDPSRequired;

    points.push({
      level: config.level,
      difficulty,
      dpsNeeded,
      dpsGrowth: prevDPS > 0 ? Math.round((dpsNeeded / prevDPS) * 100) / 100 : 1,
      budget: via.estimatedBudget,
      budgetGrowth: prevBudget > 0 ? Math.round((via.estimatedBudget / prevBudget) * 100) / 100 : 1,
      surplusRatio: via.goldSurplusRatio,
      minTowerCount: req.minTowerCount,
      requirements: req,
    });

    prevDPS = dpsNeeded;
    prevBudget = via.estimatedBudget;
  }

  return points;
}

export function analyzeTowerDPS(
  type: TowerType,
  level: number = 0,
  avgTargets: number = 1
): TowerDPS {
  const levels = TOWER_LEVELS[type];
  const config = levels[Math.min(level, levels.length - 1)];
  const totalCost = calcTotalCost(levels, level);
  const rawDPS = calcRawDPS(config);
  const effectiveDPS = calcEffectiveDPS(config, avgTargets);

  const abilities: string[] = [];
  if (config.slowFactor) abilities.push(`${Math.round((1 - config.slowFactor) * 100)}% slow ${config.slowDuration}s`);
  if (config.chainCount) abilities.push(`chain ${config.chainCount} (${Math.round((config.chainDamageFalloff ?? 0) * 100)}% per bounce)`);
  if (config.poisonMaxStacks) abilities.push(`poison ${config.poisonDamage}/tick ×${config.poisonMaxStacks} stacks`);
  if (config.isPulse) abilities.push("AoE pulse");
  if (config.splashRadius) abilities.push(`splash r=${config.splashRadius}`);
  if (config.canTargetFlying === false) abilities.push("no flying");

  return {
    type,
    name: config.name,
    level,
    rawDPS,
    effectiveDPS,
    totalCost,
    dpsPerGold: effectiveDPS / totalCost,
    range: config.range,
    abilities,
  };
}

export class WavePreview extends UIComponent {
  private waves: WaveConfig[];
  private currentWave = 0;
  private labelEl: HTMLSpanElement;
  private entriesEl: HTMLDivElement;

  constructor(waves: WaveConfig[]) {
    super("div");
    this.waves = waves;

    this.root.className =
      "hidden";

    this.labelEl = document.createElement("span");
    this.labelEl.className = "text-game-gray-light font-semibold whitespace-nowrap text-xs";

    this.entriesEl = document.createElement("div");
    this.entriesEl.className = "flex gap-1 flex-wrap";

    this.root.append(this.labelEl, this.entriesEl);
    this.renderWave();
  }

  /** Call when a wave completes to advance the preview. */
  setWave(completedWave: number): void {
    this.currentWave = completedWave;
    this.renderWave();
  }

  private renderWave(): void {
    this.entriesEl.innerHTML = "";

    if (this.currentWave >= this.waves.length) {
      this.labelEl.textContent = "Final wave!";
      return;
    }

    this.labelEl.textContent = `Next:`;
    const wave = this.waves[this.currentWave];

    for (const entry of wave.entries) {
      const badge = document.createElement("span");
      const color = entry.enemyConfig.color ?? 0xe74c3c;
      const hexColor = `#${color.toString(16).padStart(6, "0")}`;
      const shape = shapeLabel(entry.enemyConfig.bodyType);
      const tags: string[] = [];
      if (entry.enemyConfig.isFlying) tags.push("fly");
      if (entry.enemyConfig.isStealth) tags.push("stealth");
      if (entry.enemyConfig.healRadius) tags.push("heal");
      if (entry.enemyConfig.splitOnDeath) tags.push("split");

      badge.textContent = `${shape}${entry.count}${tags.length ? " " + tags.join(",") : ""}`;
      badge.className = "bg-white/8 px-1.5 py-0.5 rounded text-xs font-semibold whitespace-nowrap";
      badge.style.color = hexColor;
      this.entriesEl.appendChild(badge);
    }
  }
}

export class WaypointMovement implements EnemyMovementStrategy {
  private waypoints: WorldPosition[];
  private waypointIndex = 0;

  constructor(waypoints: WorldPosition[]) {
    this.waypoints = waypoints;
    this.waypointIndex = waypoints.length > 0 ? 1 : 0;
  }

  update(delta: number, state: MovementState): MovementResult {
    if (this.waypointIndex >= this.waypoints.length) {
      return { reachedGoal: true };
    }

    const effectiveSpeed = state.speed * state.slowFactor;
    let remaining = effectiveSpeed * delta;

    while (remaining > 0 && this.waypointIndex < this.waypoints.length) {
      const target = this.waypoints[this.waypointIndex];
      const dx = target.x - state.x;
      const dz = target.z - state.z;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dist <= remaining) {
        state.x = target.x;
        state.z = target.z;
        this.waypointIndex++;
        remaining -= dist;
      } else {
        state.x += (dx / dist) * remaining;
        state.z += (dz / dist) * remaining;
        remaining = 0;
      }
    }

    return { reachedGoal: this.waypointIndex >= this.waypoints.length };
  }

  getProgress(currentX: number, currentZ: number): number {
    if (this.waypointIndex >= this.waypoints.length) return this.waypoints.length;
    const target = this.waypoints[this.waypointIndex];
    const dx = target.x - currentX;
    const dz = target.z - currentZ;
    const distToNext = Math.sqrt(dx * dx + dz * dz);
    return this.waypointIndex + (1 - Math.min(distToNext, 1));
  }

  getWaypointIndex(): number {
    return this.waypointIndex;
  }

  getWaypoints(): WorldPosition[] {
    return this.waypoints;
  }

  setPositionAndProgress(_x: number, _z: number, wpIndex: number): void {
    // Position is set externally on the group; we just track waypoint index
    this.waypointIndex = Math.min(wpIndex, this.waypoints.length);
  }

  reset(waypoints: WorldPosition[]): void {
    this.waypoints = waypoints;
    this.waypointIndex = waypoints.length > 0 ? 1 : 0;
  }
}

export function generateEndlessWave(waveNumber: number): WaveConfig {
  const hpScale = calcEndlessHPScale(waveNumber);
  const rewardScale = calcEndlessRewardScale(waveNumber);
  const entries: WaveConfig["entries"] = [];

  // Base count grows with wave, capped for performance
  const baseCount = Math.min(MAX_BASIC_COUNT, 4 + Math.floor(waveNumber * 1.2));

  // Always have basic enemies
  entries.push({
    count: baseCount,
    spawnInterval: Math.max(0.25, 0.8 - waveNumber * 0.02),
    enemyConfig: {
      ...scaleEnemy(BASIC_ENEMY, hpScale, rewardScale),
      speed: BASIC_ENEMY.speed * (1 + waveNumber * 0.01),
    },
  });

  // Fast runners from wave 2+
  if (waveNumber >= 2) {
    entries.push({
      count: Math.min(MAX_BASIC_COUNT, Math.floor(baseCount * 0.5)),
      spawnInterval: 0.5,
      enemyConfig: {
        ...scaleEnemy(FAST_RUNNER, hpScale, rewardScale),
        speed: FAST_RUNNER.speed * (1 + waveNumber * 0.01),
      },
    });
  }

  // Tanks from wave 4+
  if (waveNumber >= 4 && waveNumber % 2 === 0) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, Math.floor(waveNumber / 3)),
      spawnInterval: 1.2,
      enemyConfig: scaleEnemy(TANK_ENEMY, hpScale, rewardScale),
    });
  }

  // Shielded from wave 5+
  if (waveNumber >= 5 && waveNumber % 3 === 0) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, Math.floor(waveNumber / 4)),
      spawnInterval: 1.0,
      enemyConfig: scaleEnemy(SHIELDED_ENEMY, hpScale, rewardScale),
    });
  }

  // Flying from wave 6+
  if (waveNumber >= 6 && waveNumber % 2 === 1) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, Math.max(2, Math.floor(waveNumber / 4))),
      spawnInterval: 0.8,
      enemyConfig: scaleEnemy(FLYING_ENEMY, hpScale, rewardScale),
    });
  }

  // Healers from wave 8+
  if (waveNumber >= 8 && waveNumber % 4 === 0) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, Math.max(1, Math.floor(waveNumber / 6))),
      spawnInterval: 1.5,
      enemyConfig: scaleEnemy(HEALER_ENEMY, hpScale, rewardScale),
    });
  }

  // Splitters from wave 10+
  if (waveNumber >= 10 && waveNumber % 5 === 0) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, Math.max(1, Math.floor(waveNumber / 8))),
      spawnInterval: 1.5,
      enemyConfig: scaleEnemy(SPLITTER_ENEMY, hpScale, rewardScale),
    });
  }

  // Stealth from wave 7+
  if (waveNumber >= 7 && waveNumber % 3 === 1) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, Math.max(2, Math.floor(waveNumber / 5))),
      spawnInterval: 0.8,
      enemyConfig: scaleEnemy(STEALTH_ENEMY, hpScale, rewardScale),
    });
  }

  // Boss every 10 waves
  if (waveNumber >= 10 && waveNumber % 10 === 0) {
    entries.push({
      count: Math.min(MAX_SPECIAL_COUNT, 1 + Math.floor(waveNumber / 20)),
      spawnInterval: 2.0,
      enemyConfig: scaleEnemy(BOSS_ENEMY, hpScale, rewardScale, 1.5),
    });
  }

  return { entries };
}

export function aggressive(state: GameState, id: LeaderId = 'player1'): Order[] {
  const me = state.leaders[id];
  if (!me || !me.alive) return [];
  const orders: Order[] = [];
  const tryAdd = adder(state, id, me.ap, orders);
  const others = aliveOthers(state, id);
  if (others.length === 0) return orders;

  if (state.round === 1) tryAdd({ kind: 'build-factory' });

  const target = others.reduce((best, t) =>
    state.leaders[t].population > state.leaders[best].population ? t : best,
  );

  let progressed = true;
  while (progressed) {
    progressed = false;
    if (tryAdd({ kind: 'build-missile' })) progressed = true;
    if (tryAdd({ kind: 'build-warhead', yield: 'small' })) progressed = true;
    if (tryAdd({ kind: 'launch', target, delivery: 'missile', warhead: 'small', targetType: 'people' })) {
      progressed = true;
    }
  }
  return orders;
}

export function bestTargetByLookahead(
  state: GameState,
  viewer: LeaderId,
  baseline: Order[],
  candidates: readonly LeaderId[],
  launch: LookaheadLaunchSpec,
  opponentPlanner: (state: GameState, leaderId: LeaderId) => Order[],
): LeaderId | null {
  if (candidates.length === 0) return null;

  let best: LeaderId | null = null;
  let bestScore = -Infinity;

  for (const target of candidates) {
    const selfOrders: Order[] = [
      ...baseline,
      { kind: 'launch', target, ...launch },
    ];
    const ordersByLeader: Partial<Record<LeaderId, Order[]>> = {
      [viewer]: selfOrders,
    };
    for (const id of state.cast) {
      if (id === viewer) continue;
      const opp = state.leaders[id];
      if (!opp || !opp.alive) continue;
      if (isHuman(id)) {
        // Project the human by their most recent non-empty round within a
        // sliding window (Approach B — see recentHumanOrders). A recent pass no
        // longer reads as passivity. simulateOneRound re-validates and drops
        // orders the human can no longer afford (e.g. a launch from an earlier
        // round when their stockpile is now empty).
        ordersByLeader[id] = recentHumanOrders(state.orderHistory, id);
        continue;
      }
      ordersByLeader[id] = opponentPlanner(state, id);
    }
    const projected = simulateOneRound(state, ordersByLeader);
    const score = scoreState(projected, viewer);
    if (score > bestScore) {
      bestScore = score;
      best = target;
    }
  }

  return best;
}

function respondToAttackers(
  state: GameState,
  id: LeaderId,
  tryAdd: Adder,
  maxRetal: number,
): boolean {
  const me = state.leaders[id];
  const others = aliveOthers(state, id);
  const attackers = others
    .filter((t) => (me.grudge[t] ?? 0) > 0)
    .sort((a, b) => (me.grudge[b] ?? 0) - (me.grudge[a] ?? 0));
  if (attackers.length === 0) return false;

  // Defend first: deploy whatever interceptors are in stock.
  tryAdd({ kind: 'deploy-defence', type: 'shield' });
  tryAdd({ kind: 'deploy-defence', type: 'aa' });

  const primary = attackers[0];
  const atk = state.leaders[primary];
  // "Reasonable attack": worth chasing elimination if the attacker is
  // finishable or not far stronger than us. Otherwise a single warning shot.
  const reasonable = atk.population <= 12 || atk.population <= me.population * 1.5;
  const toFinish = Math.ceil(atk.population / 2); // small warhead ≈ 2 pop damage
  const want = reasonable ? Math.min(toFinish, maxRetal) : 1;

  let fired = 0;
  let guard = 0;
  while (fired < want && guard < 12) {
    guard++;
    const launch: Order = {
      kind: 'launch', target: primary, delivery: 'missile', warhead: 'small', targetType: 'people',
    };
    if (tryAdd(launch)) {
      fired++;
      continue;
    }
    // Out of ammo — build a missile + warhead, then try again next iteration.
    const b1 = tryAdd({ kind: 'build-missile' });
    const b2 = tryAdd({ kind: 'build-warhead', yield: 'small' });
    if (!b1 && !b2) break; // no AP left to arm
  }
  return true;
}

export function planCarnage(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];

  let budget = me.ap;

  const others = state.cast.filter((t) => t !== leaderId && state.leaders[t]?.alive);
  const attackers = others.filter((t) => wasAttackedBy(state, leaderId, t));

  function combinedScore(target: LeaderId): number {
    const base = threatScore(state, leaderId, target);
    const escalated =
      (me.recentAggressionFrom[target] ?? 0) > 0
        ? base * AI_SCORING_WEIGHTS.carnageEscalationMultiplier
        : base;
    return escalated + opportunismScore(state, target);
  }

  const rankedTargets = [...others].sort((a, b) => combinedScore(b) - combinedScore(a));

  // Reserve 1 AP per attacker for propaganda (capped so it never starves offence).
  const propagandaReserve = Math.min(attackers.length, Math.max(0, budget - 2));
  const offenceBudget = budget - propagandaReserve;

  // Launch first (moderate cap), then build with the remainder.
  const salvo = launchSalvo(state, leaderId, {
    budget: offenceBudget,
    rankedTargets,
    maxLaunches: CARNAGE_MAX_LAUNCHES,
  });
  const build = buildToward(
    state, leaderId, CARNAGE_BUILD_PLAN, offenceBudget - salvo.apSpent,
  );
  budget -= salvo.apSpent + build.apSpent;

  const orders: Order[] = [...build.orders, ...salvo.orders];

  // Propaganda only at leaders who attacked Carnage.
  for (const attacker of attackers) {
    if (budget < PROPAGANDA_COST) break;
    const prop: Order = { kind: 'propaganda', target: attacker };
    if (validateOrder(state, leaderId, prop).ok) {
      orders.push(prop);
      budget -= apCostOf(prop);
    }
  }

  return orders;
}

export function planNetanyahoo(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];

  let budget = me.ap;

  const others = state.cast.filter((t) => t !== leaderId && state.leaders[t]?.alive);
  const chumpAlive = state.cast.includes('chump') && state.leaders['chump']?.alive === true;
  const chumpProvoked = wasAttackedBy(state, leaderId, 'chump');

  // Launch candidates: exclude Chump unless he has attacked first — OR unless
  // Chump is the only remaining opponent (deadlock prevention: Netanyahoo must
  // be able to finish the game even if Chump never fires first).
  const preferredCandidates = others.filter((t) => t !== 'chump' || chumpProvoked);
  const launchCandidates = preferredCandidates.length > 0 ? preferredCandidates : others;
  // Rank by threat, highest first.
  const rankedTargets = [...launchCandidates].sort(
    (a, b) => threatScore(state, leaderId, b) - threatScore(state, leaderId, a),
  );

  // Reserve 1 AP for propaganda at Chump.
  const propagandaReserve = chumpAlive && budget >= PROPAGANDA_COST ? PROPAGANDA_COST : 0;
  const offenceBudget = budget - propagandaReserve;

  // Launch first — salvo self-limits to ammo on hand; warmonger has no cap.
  const salvo = launchSalvo(state, leaderId, { budget: offenceBudget, rankedTargets });
  // Build with whatever the salvo left unspent.
  const build = buildToward(
    state, leaderId, NETANYAHOO_BUILD_PLAN, offenceBudget - salvo.apSpent,
  );
  budget -= salvo.apSpent + build.apSpent;

  // Builds must precede launches in the submitted array.
  const orders: Order[] = [...build.orders, ...salvo.orders];

  // Propaganda exclusively at Chump.
  if (chumpAlive && budget >= PROPAGANDA_COST) {
    const prop: Order = { kind: 'propaganda', target: 'chump' };
    if (validateOrder(state, leaderId, prop).ok) {
      orders.push(prop);
      budget -= apCostOf(prop);
    }
  }

  return orders;
}

export function uiReducer(state: UiState, action: UiAction): UiState {
  switch (action.type) {
    case 'START_GAME': {
      const game = initialState(action.opts);
      const initialPopulations: Partial<Record<LeaderId, number>> = {};
      for (const id of game.cast) initialPopulations[id] = game.leaders[id].population;
      const firstHuman = game.cast.find(isHuman);
      return {
        screen: 'planning',
        game,
        events: [],
        prevPopulations: {},
        initialPopulations,
        lastNewGameOpts: action.opts,
        activeHumanTurn: firstHuman,
        pendingHumanOrders: {},
      };
    }
    case 'PLAYER_SUBMIT': {
      if (!state.game) return state;
      const pendingHumanOrders = { ...state.pendingHumanOrders, [action.leaderId]: action.orders };
      const next = nextHumanAfter(state.game.cast, action.leaderId);
      if (next) {
        return { ...state, screen: 'hotseat', activeHumanTurn: next, pendingHumanOrders };
      }
      // All humans done — drain buffer into engine SUBMIT_ORDERS per human, then advance.
      let game = state.game;
      for (const [leaderId, orders] of Object.entries(pendingHumanOrders) as [LeaderId, Order[]][]) {
        game = reduce(game, { type: 'SUBMIT_ORDERS', leaderId, orders });
      }
      return {
        ...state,
        screen: 'aiConferring',
        game,
        activeHumanTurn: undefined,
        pendingHumanOrders: {},
      };
    }
    case 'BEGIN_PLANNING': {
      return { ...state, screen: 'planning', activeHumanTurn: action.leaderId };
    }
    case 'AI_RESOLVE': {
      if (!state.game) return state;
      const prevPopulations: Partial<Record<LeaderId, number>> = {};
      for (const id of state.game.cast) prevPopulations[id] = state.game.leaders[id].population;
      let game = state.game;
      for (const id of game.cast) {
        if (isHuman(id)) continue;
        if (!game.leaders[id].alive) continue;
        const orders = planAi(game, id);
        game = reduce(game, { type: 'SUBMIT_ORDERS', leaderId: id, orders });
      }
      const result = resolveRound(game);
      return {
        ...state,
        screen: 'action',
        game: result.state,
        events: result.events,
        prevPopulations,
      };
    }
    case 'ACTION_DONE': {
      if (!state.game) return state;
      const next: ScreenName = state.game.outcome ? 'winners' : 'roundSummary';
      return { ...state, screen: next };
    }
    case 'NEXT_ROUND': {
      if (!state.game) return state;
      if (state.game.outcome) return { ...state, screen: 'winners' };
      const firstHuman = state.game.cast.find(isHuman);
      return { ...state, screen: 'planning', activeHumanTurn: firstHuman };
    }
    case 'BACK_TO_SETUP':
      return initialUiState;
  }
}

