export abstract class Memory {
  memorizedCards: MemorizedCard[];
  memorizedTricks: MemorizedTrick[];

  constructor() {
    this.memorizedCards = [];
    this.memorizedTricks = [];
  }

  isHighestCardLeft(card: Card, hand?: Hand): boolean {
    let allKnownCards = [
      ...this.memorizedCards.map((mcard) => mcard.playedCard.card),
      ...(hand?.cards || []),
    ];
    let leftOverCards = cardOrder.filter((x) => !allKnownCards.some((y) => x.equals(y)));
    return leftOverCards.length > 0 && card.compareTo(leftOverCards[0]) <= 0;
  }

  clearMemory() {
    this.memorizedCards = [];
  }

  abstract memorize(playedCard: PlayedCard, trickId?: string): void;

  memorizeMany(playedCards: PlayedCard[], trickId?: string): void {
    playedCards.forEach((playedCard) => this.memorize(playedCard, trickId));
  }

  memorizeTrick(trickId: string, baseCard: Card, winner: Player): void {
    this.memorizedTricks.push({ trickId, baseCard, winner });
  }

  hasSuitBeenStartedBefore(suit: Suit): boolean {
    return (
      this.memorizedTricks.filter(
        (memTrick) => memTrick.baseCard.suit === suit && !memTrick.baseCard.isTrump(),
      ).length > 0
    );
  }

  hasSuitBeenThrown(suit: Suit): boolean {
    return this.hasSuitBeenPlayedBefore(suit) && !this.hasSuitBeenStartedBefore(suit);
  }

  hasSuitBeenThrownByPlayer(suit: Suit, player: Player): boolean {
    return (
      this.hasSuitBeenThrown(suit) &&
      this.getPlayersBySuitPlayed(suit)
        .map((p) => p.id)
        .includes(player.id)
    );
  }

  hasSuitBeenPlayedBefore(suit: Suit, trickId?: string): boolean {
    return this.getPlayersBySuitPlayed(suit, trickId).length > 0;
  }

  getPlayersBySuitPlayed(suit: Suit, trickId?: string): Player[] {
    return this.memorizedCards
      .filter(
        (memCards) =>
          memCards.playedCard.card.suit === suit &&
          !memCards.playedCard.card.isTrump() &&
          (memCards.trickId !== trickId || !trickId),
      )
      .map((memCards) => memCards.playedCard.player);
  }

  pointsForPlayer(player: Player): number {
    let points = 0;
    this.memorizedTricks.forEach((trick) => {
      if (trick.winner.id === player.id) {
        points += this.memorizedCards
          .filter((card) => card.trickId === trick.trickId)
          .reduce((accu, memCard) => accu + memCard.playedCard.card.value, 0);
      }
    });
    return points;
  }

  pointsLeftInSuit(suit: string): number {
    return (
      cardOrder
        .filter((card) => card.suit === suit && !card.isTrump())
        .reduce((accu, card) => accu + card.value, 0) -
      this.memorizedCards
        .filter(
          (element) => element.playedCard.card.suit === suit && !element.playedCard.card.isTrump(),
        )
        .reduce((accu, element) => accu + element.playedCard.card.value, 0)
    );
  }
}

export default class Laser extends BaseBullet {
  type: BULLET_TYPE;
  id: number;
  x: number;
  y: number;
  ctx: CanvasRenderingContext2D;
  parent: LaserTower;
  target: Enemy;
  damage: number;
  width: number;
  vx: number;
  vy: number;
  angle: number;
  hue: number;

  constructor({
    ctx,
    x,
    y,
    parent,
    target,
    damage,
    id,
  }: Omit<
    IBulletOption & {
      parent: LaserTower;
    },
    'range'
  >) {
    super({ ctx, x, y, parent, damage, id });
    this.type = BULLETS.LASER;
    this.target = target;
    this.width = 5;
    this.vx = 0;
    this.vy = 0;
    this.angle = 0;
    this.hue = parent.hue;
  }

  step() {
    const parent = this.parent;
    this.x = parent.x + parent.bulletStartPosVec[0];
    this.y = parent.y + parent.bulletStartPosVec[1];
  }

  draw(ctx: CanvasRenderingContext2D) {
    this.step();

    // 绘图开始
    ctx.save();
    ctx.strokeStyle = 'hsl(' + this.hue + ', 100%, 80%)';
    ctx.beginPath();
    ctx.moveTo(this.x, this.y);
    ctx.lineTo(this.target.x, this.target.y);
    ctx.stroke();
    ctx.closePath();
    ctx.restore();
  }
}

export function paranoid(score: number, context: GameContext): number {
  const { state, currentNationId } = context;
  const neighborIds = getNeighborNationIds(context);

  const ownStrength = state.armies
    .filter((a) => a.ownerId === currentNationId)
    .reduce((sum, a) => sum + a.strength, 0);

  for (const neighborId of neighborIds) {
    const neighborStrength = state.armies
      .filter((a) => a.ownerId === neighborId)
      .reduce((sum, a) => sum + a.strength, 0);

    // Neighbor has 50%+ more military strength
    if (neighborStrength > ownStrength * 1.5) {
      return score * 1.4;
    }
  }

  return score;
}

export function opportunist(score: number, context: GameContext): number {
  const { state, currentNationId } = context;
  const neighborIds = getNeighborNationIds(context);

  for (const neighborId of neighborIds) {
    const neighbor = state.nations.find((n) => n.id === neighborId);
    if (!neighbor) continue;

    // Neighbor at war with someone other than us
    const atWarWithThirdParty = state.wars.some(
      (w) =>
        (w.aggressorId === neighborId || w.defenderId === neighborId) &&
        w.aggressorId !== currentNationId &&
        w.defenderId !== currentNationId
    );

    // Neighbor has low manpower (< 15)
    const isWeak = neighbor.resources.manpower < 15;

    if (atWarWithThirdParty || isWeak) {
      return score * 1.5;
    }
  }

  return score;
}

function getNeighborNationIds(nationId: string, state: GameState): string[] {
  const ownedIds = new Set(
    state.provinces.filter((p) => p.ownerId === nationId).map((p) => p.id)
  );
  const neighborIds = new Set<string>();
  for (const edge of state.edges) {
    if (ownedIds.has(edge.sourceId)) {
      const target = state.provinces.find((p) => p.id === edge.targetId);
      if (target?.ownerId && target.ownerId !== nationId && target.ownerId !== 'rebel') {
        neighborIds.add(target.ownerId);
      }
    }
    if (ownedIds.has(edge.targetId)) {
      const source = state.provinces.find((p) => p.id === edge.sourceId);
      if (source?.ownerId && source.ownerId !== nationId && source.ownerId !== 'rebel') {
        neighborIds.add(source.ownerId);
      }
    }
  }
  return [...neighborIds];
}

