export function generateNpcOrders(nationId: string, state: GameState): Order[] {
  const nation = state.nations.find((n) => n.id === nationId);
  if (!nation || nation.eliminatedOnTurn !== undefined) return [];

  const context: GameContext = {
    state,
    currentNationId: nationId,
    turn: state.turn,
  };

  const budget = computeActionBudget(nationId, state);

  // Generate all candidate actions
  const diplomaticCandidates = generateDiplomaticCandidates(nation, context);
  const militaryCandidates = generateMilitaryCandidates(nation, context);
  const constructionCandidates = generateConstructionCandidates(nation, context);
  const wildcardCandidates = generateWildcardCandidates(nation, context);

  // Apply modifiers and agenda multiplier to each candidate
  const allCandidates = [
    ...diplomaticCandidates,
    ...militaryCandidates,
    ...constructionCandidates,
    ...wildcardCandidates,
  ].map((candidate) => {
    const isBetrayal =
      candidate.order.type === 'declare_war' ||
      candidate.order.type === 'break_agreement';
    let isNaval = candidate.order.type === 'blockade';
    if (candidate.order.type === 'move_army') {
      const moveOrder = candidate.order;
      const matchedArmy = state.armies.find((a) => a.id === moveOrder.armyId);
      isNaval = matchedArmy?.type === 'Naval' || false;
    }

    let score = applyModifiers(
      candidate.score,
      context,
      nation,
      candidate.category,
      isBetrayal,
      isNaval
    );

    // Apply agenda multiplier
    score *= getAgendaMultiplier(candidate.order, nation, state);

    return { ...candidate, score };
  });

  return selectOrders(allCandidates, budget, nation);
}

export function actionFromDict(data: ActionDict): Action {
  switch (data.type) {
    case 'stand':
      return Stand();
    case 'end_turn':
      return EndTurn();
    case 'play':
      if (data.hand_index == null) throw new Error('play action requires hand_index');
      return PlayHandCard(data.hand_index, data.option_index ?? 0);
    default:
      throw new Error(`unknown action ${JSON.stringify(data)}`);
  }
}

export function chooseBotAction(game: PazaakGame, player: number): Action {
  const me = game.players[player];
  const opp = game.players[1 - player];
  const total = me.total;

  const [bestPlay, bestTotal] = bestHandPlay(game, player);

  if (total > WINNING_TOTAL) {

    if (bestPlay !== null && bestTotal <= WINNING_TOTAL) {
      return bestPlay;
    }
    return Stand();
  }

  if (!me.playedThisTurn && bestPlay !== null && bestTotal === WINNING_TOTAL) {
    return bestPlay;
  }

  if (total === WINNING_TOTAL) {
    return Stand();
  }


  if (opp.standing && total >= opp.total && total <= WINNING_TOTAL) {
    return Stand();
  }

  if (total >= STAND_THRESHOLD && !(opp.standing && opp.total > total)) {
    return Stand();
  }

  return EndTurn();
}

export function hexDistance(a: Hex, b: Hex): number {
  const ca = toCube(a);
  const cb = toCube(b);
  return Math.max(Math.abs(ca.q - cb.q), Math.abs(ca.r - cb.r), Math.abs(ca.s - cb.s));
}

