export class CollisionManager {
	update() {
		const entityManager = managers.get('entityManager');

		this.handleEnemyCollisions(
			entityManager.livingEnemies,
			entityManager.livingProjectiles,
			entityManager.throne
		);

		this.handleProjectileCollisions(entityManager.livingProjectiles);

		this.handleLootCollisions(entityManager.livingLoot, entityManager.throne);
	}

	handleEnemyCollisions(enemies: Entity[], projectiles: Entity[], throne: Entity): void {
		for (const enemy of enemies) {
			for (const projectile of projectiles) {
				if (this.checkCollision(projectile, enemy)) {
					projectile.onCollide(enemy);
					enemy.onCollide(projectile);
				}
			}

			if (this.checkCollision(enemy, throne)) {
				enemy.onCollide(throne);
				throne.onCollide(enemy);
			}
		}
	}

	handleProjectileCollisions(projectiles: Entity[]): void {
		for (const projectile of projectiles) {
			if (!this.checkScreenBounds(projectile)) {
				projectile.onCollide('OUT_OF_BOUNDS');
				continue;
			}
		}
	}

	handleLootCollisions(lootEntities, throne): void {
		lootEntities.forEach((loot) => {
			if (this.checkCollision(loot, throne)) {
				loot.onCollide(throne);
				throne.onCollide(loot);
			}
		});
	}

	checkCollision(entity1: Entity, entity2: Entity): boolean {
		return checkRectCollision(entity1.boundingBox, entity2.boundingBox);
	}

	filterEnemiesByBounds = (bounds) => {
		const entityManager = managers.get('entityManager');

		return entityManager.livingEnemies.filter((entity) =>
			checkRectCollision(entity.boundingBox, bounds)
		);
	};

	checkBounds(entity: Entity, boundsRect: Rect2D): boolean {
		return checkRectCollision(entity.boundingBox, boundsRect);
	}

	checkScreenBounds(entity: Entity): boolean {
		return checkRectCollision(entity.boundingBox, screen.screenBounds);
	}

	checkGameBounds(entity: Entity): boolean {
		return checkRectCollision(entity.boundingBox, screen.gameBoundingBox);
	}
}

export class TowerYellowCreator {
  static #instance: TowerYellowCreator | null = null

  #images: Image[]
  #player: Player
  constructor(images: Image[], player: Player) {
    if (TowerYellowCreator.#instance !== null) {
      throw new Error(
        'TowerYellowCreator is a singleton class, use getInstance to get the instance',
      )
    }
    this.#images = images
    this.#player = player

    // assign the singleton instance
    TowerYellowCreator.#instance = this
  }

  static getInstance(images: Image[], player: Player) {
    if (TowerYellowCreator.#instance === null) {
      TowerYellowCreator.#instance = new TowerYellowCreator(images, player)
    }
    return TowerYellowCreator.#instance
  }

  create(position: Position, tileOrange: TileOrange) {
    return new TowerYellow(
      {
        x: position.x - TOWER_CREATION_OFFSET.X,
        y: position.y - TOWER_CREATION_OFFSET.Y,
      },
      tileOrange,
      this.#player,
      this.#images,
    )
  }
}

export class Player {
  static #instance: Player | null = null

  #lives: number = 7
  #score: number = 0
  #wave: number = 1
  constructor() {
    if (Player.#instance !== null) {
      throw new Error(
        'Player is a singleton class. Use getInstance to get the instance of the Player',
      )
    }

    // assign the singleton instance
    Player.#instance = this
  }

  static getInstance() {
    if (Player.#instance === null) {
      Player.#instance = new Player()
    }
    return Player.#instance
  }

  get lives() {
    return this.#lives
  }

  get wave() {
    return this.#wave
  }

  get score() {
    return this.#score
  }

  set score(value) {
    this.#score = value
  }

  increaseWave() {
    this.#wave++
  }

  increaseScore(score: number) {
    this.#score += score
  }

  getPrintScore(): string {
    return String(this.#score).padStart(10, '0')
  }

  increaseLives(increment: number) {
    this.#lives += increment
  }

  decreaseLives() {
    this.#lives--
  }
}

export class MagicFireball extends Magic {
  #pathMovement: PathMovement
  #magicFireballCollisionChecker: MagicFireballCollisionChecker
  #img: Image
  constructor(
    img: Image,
    pathMovement: PathMovement,
    magicFireballCollisionChecker: MagicFireballCollisionChecker,
  ) {
    super(pathMovement.position)
    this.#img = img
    this.#pathMovement = pathMovement
    this.#magicFireballCollisionChecker = magicFireballCollisionChecker
  }

  addDamage(enemy: Enemy) {
    enemy.addDamage(MAGIC_FIREBALL_DAMAGE)
  }

  draw() {
    P5.p5.image(this.#img, this.position.x, this.position.y)
  }

  updatePosition() {
    this.position = this.#pathMovement.position
  }

  updateStatus() {
    if (this.#pathMovement.isAlive) {
      this.status = MAGIC_STATUS.ALIVE
      return
    }
    this.status = MAGIC_STATUS.DEAD
  }

  update(enemyInstancesManager: EnemyInstancesManager) {
    this.#pathMovement.update()
    this.updatePosition()
    this.updateStatus()
    this.#magicFireballCollisionChecker.check(
      this,
      enemyInstancesManager.getAll(),
    )
  }
}

