  public showGrid: boolean = true;
  public showHealthbars: boolean = true;
  public showStats: boolean = true;
}

export class TurnChangeCollection {
  private damageValues: TurnChangeDisplay[] = [];

  private uiSheet?: Spritesheet;

  public setUISheet(uiSheet: Spritesheet) {
    this.uiSheet = uiSheet;

  }

  public addTurnChange(message: string, view: Container, coords: Coords, texture?: Texture) {
    const damageValueDisplay = new TurnChangeDisplay(message, view, TurnChangeDisplay.DEFAULT_DURATION_IN_MILLIS, coords, this.uiSheet, texture);
    this.damageValues.push(damageValueDisplay);
  }

  public addEndOfBattle(message: string, view: Container, coords: Coords, texture?: Texture) {
    const damageValueDisplay = new TurnChangeDisplay(message, view, TurnChangeDisplay.END_OF_BATTLE_DURATION_IN_MILLIS, coords, this.uiSheet, texture);
    this.damageValues.push(damageValueDisplay);
  }

  public update(delta: number) {
    this.damageValues.forEach(damageValueDisplay => damageValueDisplay.update(delta));
    // remove all entries with remainingDuration <= 0
    this.damageValues = this.damageValues.filter(item => item.remainingDurationInMillis > 0);
  }
}

export class TurnChangeDisplay {

  static DEFAULT_FONT_STYLE: TextOptions = { style: { fill: { color: '#dddd77', alpha: 1 }, fontSize: 42, align: 'left' } };
  static DEFAULT_DURATION_IN_MILLIS: number = 750;
  static END_OF_BATTLE_DURATION_IN_MILLIS: number = 5000;

  private turnChangeText = new Text({ ...TurnChangeDisplay.DEFAULT_FONT_STYLE, text: this.message });
  private alpha: number = 1;
  private startingDurationInMillis: number = TurnChangeDisplay.DEFAULT_DURATION_IN_MILLIS;
  private bannerSprite?: Sprite = undefined;

  private window = new Container();

  public constructor(
    private message: string,
    private view: Container,
    public remainingDurationInMillis: number,
    coords: Coords,
    private uiSheet?: Spritesheet,
    private texture?: Texture
  ) {
    if (!this.uiSheet) {
      throw new Error('uiSheet is required');
    }

    this.startingDurationInMillis = remainingDurationInMillis;

    const windowBg = new NineSliceSprite({
      texture: this.uiSheet.textures['panel.png'],
      leftWidth: 15,
      topHeight: 15,
      rightWidth: 15,
      bottomHeight: 15,
    });
    windowBg.width = 400;
    windowBg.height = 120;
    this.window.addChild(windowBg);

    const bannerBg = new NineSliceSprite({
      texture: this.uiSheet.textures['progress_bg.png'],
      leftWidth: 5,
      topHeight: 5,
      rightWidth: 5,
      bottomHeight: 5
    });
    bannerBg.width = 128 + 10;
    bannerBg.height = 128 + 10;
    bannerBg.position = { x: (400 - 128) / 2 - 5, y: 80 - 5 };
    this.window.addChild(bannerBg);

    this.window.position = coords;

    if (this.texture) {
      this.bannerSprite = new Sprite(this.texture);
      this.bannerSprite.position = { x: (400 - 128) / 2, y: 80 };
      this.bannerSprite.width = 128;
      this.bannerSprite.height = 128;
      this.window.addChild(this.bannerSprite);
    }

    this.turnChangeText.position = { x: 20, y: 20 };
    this.turnChangeText.text = "" + message.toString();
    this.window.addChild(this.turnChangeText);
    this.view.addChild(this.window);
  }

  public update(delta: number) {
    if (delta == 0 || this.startingDurationInMillis == 0) {
      return;
    }

    if (this.remainingDurationInMillis < 0.5 * this.startingDurationInMillis) {
      this.alpha = this.remainingDurationInMillis * 2 / this.startingDurationInMillis;
      this.window.alpha = this.alpha;
    }

    this.remainingDurationInMillis -= delta;

    if (this.remainingDurationInMillis <= 0) {
      this.view.removeChild(this.window);
      this.window.destroy({ children: true });
    }
  }
}

function scaleEnemy(
  base: EnemyConfig,
  hpScale: number,
  rewardScale: number,
  extraHpMultiplier = 1,
): EnemyConfig {
  return {
    ...base,
    hp: Math.round(base.hp * hpScale * extraHpMultiplier),
    reward: Math.max(1, Math.round(base.reward * rewardScale)),
  };
}

function applyDifficultyToWave(wave: WaveConfig, difficulty: Difficulty): WaveConfig {
  const mods = DIFFICULTY_MODS[difficulty];
  return {
    entries: wave.entries.map((entry) => ({
      ...entry,
      enemyConfig: {
        ...entry.enemyConfig,
        hp: Math.round(entry.enemyConfig.hp * mods.enemyHpMult),
        speed: entry.enemyConfig.speed * mods.enemySpeedMult,
        reward: Math.round(entry.enemyConfig.reward * mods.goldMult),
        ...(entry.enemyConfig.splitConfig
          ? {
              splitConfig: {
                ...entry.enemyConfig.splitConfig,
                hp: Math.round(entry.enemyConfig.splitConfig.hp * mods.enemyHpMult),
                speed: entry.enemyConfig.splitConfig.speed * mods.enemySpeedMult,
                reward: Math.round(entry.enemyConfig.splitConfig.reward * mods.goldMult),
              },
            }
          : {}),
      },
    })),
  };
}

export function calcEffectiveDPS(
  config: TowerConfig,
  avgTargets: number = 1
): number {
  const raw = calcRawDPS(config);

  // Chain lightning: primary + each chain bounce with damage falloff
  if (config.chainCount && config.chainDamageFalloff) {
    let total = raw;
    let chainDmg = raw;
    for (let i = 0; i < config.chainCount; i++) {
      chainDmg *= config.chainDamageFalloff;
      total += chainDmg;
    }
    return total;
  }

  // Poison: direct DPS + (poisonDamage / tickRate) × maxStacks
  if (
    config.poisonDamage &&
    config.poisonTickRate &&
    config.poisonMaxStacks
  ) {
    const dotDPS =
      (config.poisonDamage / config.poisonTickRate) * config.poisonMaxStacks;
    return raw + dotDPS;
  }

  // Tesla pulse: hits ALL enemies in range
  if (config.isPulse) {
    return raw * avgTargets;
  }

  // Cannon splash: hits multiple enemies in splash radius
  if (config.splashRadius) {
    return raw * avgTargets;
  }

  return raw;
}

export class StartWaveButton extends UIComponent {
  private onClick: () => void;
  private countdown = new CountdownTimer();
  private mainBtn: HTMLButtonElement;
  private autoBtn: HTMLButtonElement;
  private _autoStart = false;
  private _ready = false;

  constructor(onClick: () => void) {
    super("div");
    this.onClick = onClick;

    this.root.className = "start-wave-container";

    this.mainBtn = document.createElement("button");
    this.mainBtn.className = "start-wave-main";
    this.mainBtn.textContent = "Start Wave";
    this.mainBtn.addEventListener("click", this.handleClick);

    this.autoBtn = document.createElement("button");
    this.autoBtn.className = "start-wave-auto";
    this.autoBtn.textContent = "Auto";
    this.autoBtn.dataset.active = "false";
    this.autoBtn.addEventListener("click", this.handleAutoClick);

    this.root.append(this.mainBtn, this.autoBtn);
  }

  get autoStart(): boolean {
    return this._autoStart;
  }

  toggleAutoStart(): void {
    this._autoStart = !this._autoStart;
    this.autoBtn.dataset.active = String(this._autoStart);

    if (this._ready) {
      if (this._autoStart) {
        this.startAutoCountdown();
      } else {
        this.countdown.clear();
        this.mainBtn.textContent = "Start Wave";
      }
    }
  }

  setWaveInProgress(): void {
    this._ready = false;
    this.countdown.clear();
    this.mainBtn.disabled = true;
    this.mainBtn.textContent = "Wave in progress...";
  }

  setReady(): void {
    this._ready = true;
    this.countdown.clear();
    this.mainBtn.disabled = false;

    if (this._autoStart) {
      this.startAutoCountdown();
    } else {
      this.mainBtn.textContent = "Start Wave";
    }
  }

  setGameOver(): void {
    this._ready = false;
    this.countdown.clear();
    this.mainBtn.disabled = true;
  }

  private startAutoCountdown(): void {
    this.countdown.start(
      AUTO_START_DELAY,
      (remaining) => { this.mainBtn.textContent = `Next Wave (${remaining}s)`; },
      () => { this.handleClick(); },
    );
  }

  private handleClick = (): void => {
    this.countdown.clear();
    this._ready = false;
    this.onClick();
    this.setWaveInProgress();
  };

  private handleAutoClick = (): void => {
    this.toggleAutoStart();
  };

  dispose(): void {
    this.countdown.clear();
    this.mainBtn.removeEventListener("click", this.handleClick);
    this.autoBtn.removeEventListener("click", this.handleAutoClick);
    super.dispose();
  }
}

export function defenceVisibilityScore(state: GameState, target: LeaderId): number {
  const t = state.leaders[target];
  if (!t) return 0;
  return t.stockpile.shields + t.stockpile.aa;
}

export function opportunismScore(state: GameState, target: LeaderId): number {
  const t = state.leaders[target];
  if (!t || !t.alive) return 0;
  const w = AI_SCORING_WEIGHTS.opportunism;
  let score = 0;
  if (t.population < 10) score += w.perPopBelow10M * (10 - t.population);
  if (t.factories < 3) score += w.perFactoryBelow3 * (3 - t.factories);
  score += w.perDefenceShield * t.stockpile.shields;
  score += w.perDefenceAa * t.stockpile.aa;
  return score;
}

export function threatScore(state: GameState, viewer: LeaderId, target: LeaderId): number {
  if (viewer === target) return 0;
  const t = state.leaders[target];
  if (!t || !t.alive) return 0;
  const w = AI_SCORING_WEIGHTS.threat;
  const arsenal =
    t.stockpile.missiles * w.perMissile +
    t.stockpile.bombers * w.perBomber +
    t.stockpile.warheadsSmall * w.perWarheadSmall +
    t.stockpile.warheadsMedium * w.perWarheadMedium +
    t.stockpile.warheadsLarge * w.perWarheadLarge;
  const aggression = (state.leaders[viewer].recentAggressionFrom[target] ?? 0) * w.perRecentAggression;
  return arsenal + aggression;
}

export function turtle(state: GameState, id: LeaderId = 'player1'): Order[] {
  const me = state.leaders[id];
  if (!me || !me.alive) return [];
  const orders: Order[] = [];
  const tryAdd = adder(state, id, me.ap, orders);
  const others = aliveOthers(state, id);
  const threatened = others.some((t) => (me.grudge[t] ?? 0) > 0);

  if (state.round <= 3) tryAdd({ kind: 'build-factory' });
  tryAdd({ kind: 'build-defence', type: 'shield' });
  if (me.stockpile.shields >= 1 || threatened) tryAdd({ kind: 'deploy-defence', type: 'shield' });
  tryAdd({ kind: 'build-defence', type: 'aa' });
  if (me.stockpile.aa >= 1) tryAdd({ kind: 'deploy-defence', type: 'aa' });
  return orders;
}

export function applyWooing(
  state: GameState,
  ordersByLeader: Partial<Record<LeaderId, Order[]>>,
): WooingResult {
  const next: GameState = structuredClone(state);
  const events: ResolutionEvent[] = [];
  const senders = Object.keys(ordersByLeader).sort() as LeaderId[];
  for (const id of senders) {
    const orders = ordersByLeader[id] ?? [];
    for (const o of orders) {
      if (o.kind !== 'woo') continue;
      const me = next.leaders[id];
      const target = next.leaders[o.target];
      if (!me || !me.alive || !target || !target.alive) continue;
      const current = target.favourability[id] ?? 0;
      const points = ACTION_COSTS.woo;
      target.favourability[id] = current + points;
      events.push({ kind: 'WooApplied', from: id, to: o.target, points });
    }
  }
  return { state: next, events };
}

export function deriveBoxScore(
  events: ResolutionEvent[],
  leaders: GameState['leaders'],
): BoxScoreRow[] {
  const rows: BoxScoreRow[] = [];
  for (const e of events) {
    if (e.kind === 'ImpactPeople') {
      rows.push({
        a: shortName(leaders[e.from].name),
        b: shortName(leaders[e.target].name),
        score: `−${e.deaths}M`,
        tone: 'harm',
      });
    } else if (e.kind === 'ImpactInfrastructure') {
      rows.push({
        a: shortName(leaders[e.from].name),
        b: shortName(leaders[e.target].name),
        score: `−${e.factoriesDestroyed} fac`,
        tone: 'harm',
      });
    } else if (e.kind === 'MissileIntercepted') {
      rows.push({
        a: shortName(leaders[e.from].name),
        b: shortName(leaders[e.to].name),
        score: 'INTERCEPT',
        tone: 'good',
      });
    }
  }
  return rows;
}

export function reduce(state: GameState, action: Action): GameState {
  switch (action.type) {
    case 'NEW_GAME':
      return initialState({
        cast: action.cast,
        difficulty: action.difficulty,
        seed: action.seed,
        config: action.config,
      });

    case 'SUBMIT_ORDERS': {
      const me = state.leaders[action.leaderId];
      if (!me || !me.alive) return state;

      const v = validateOrderSequence(state, action.leaderId, action.orders);
      if (!v.ok) return state;

      const cost = totalApCost(action.orders);
      if (cost > me.ap) return state;

      const next = structuredClone(state);
      next.leaders[action.leaderId].ap = me.ap - cost;
      next.pendingOrders[action.leaderId] = {
        leaderId: action.leaderId,
        orders: action.orders,
        apSpent: cost,
      };
      return next;
    }

    case 'RESOLVE_ROUND':
      return resolveRound(state).state;

    case 'LOAD_STATE':
      return action.state;
  }
}

export function scriptedOrders(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];
  const target = state.cast.find((id) => id !== leaderId && state.leaders[id].alive);
  const patterns: Order[][] = [
    [{ kind: 'build-missile' }, { kind: 'build-warhead', yield: 'small' }],
    [{ kind: 'build-factory' }],
    [{ kind: 'build-defence', type: 'shield' }],
    target
      ? [
          {
            kind: 'launch',
            target,
            delivery: 'missile',
            warhead: 'small',
            targetType: 'people',
          },
        ]
      : [],
    target
      ? [{ kind: 'propaganda', target }]
      : [],
    target
      ? [{ kind: 'woo', target }]
      : [],
  ];

  const idx = (state.round + leaderHash(leaderId)) % patterns.length;
  const candidate = patterns[idx];
  // Drop orders that fail validation in the current state, and trim to AP.
  const filtered: Order[] = [];
  for (const o of candidate) {
    if (!validateOrder(state, leaderId, o).ok) continue;
    if (totalApCost([...filtered, o]) > me.ap) break;
    filtered.push(o);
  }
  return filtered;
}

export function initialState(opts: NewGameOpts): GameState {
  const leaders = {} as Record<LeaderId, Leader>;
  for (const id of opts.cast) {
    const profile = LEADER_PROFILES[id];
    const startPop = opts.config?.startPopOverride?.[id] ?? profile.startPop;
    const playerOverride = opts.config?.playerProfiles?.[id];
    leaders[id] = {
      id,
      name: playerOverride?.name ?? profile.name,
      country: playerOverride?.country ?? profile.country,
      population: startPop,
      factories: profile.startFactories,
      stockpile: {
        missiles: 0,
        bombers: 0,
        warheadsSmall: 0,
        warheadsMedium: 0,
        warheadsLarge: 0,
        shields: 0,
        aa: 0,
      },
      ap: profile.startAp,
      apBanked: 0,
      alive: true,
      favourability: {},
      grudge: {},
      recentAggressionFrom: {},
      deployedShields: 0,
      deployedAA: 0,
      bonusRule: profile.bonusRule,
    };
  }
  const seedState = seedFromString(opts.seed);
  const mh = shuffleMastheads(seedState);

  return {
    round: 1,
    cast: [...opts.cast],
    difficulty: opts.difficulty,
    seed: opts.seed,
    rngState: mh.rngState,
    leaders,
    pendingOrders: {},
    orderHistory: [],
    mastheadOrder: mh.order,
    log: [],
    outcome: null,
    config: {
      fastPlay: false,
      ...opts.config,
    },
  };
}

export function launchSalvo(
  state: GameState,
  leaderId: LeaderId,
  opts: LaunchSalvoOpts,
): SalvoResult {
  const me = state.leaders[leaderId];
  const orders: Order[] = [];
  if (!me || opts.rankedTargets.length === 0) return { orders, apSpent: 0 };

  let remaining = opts.budget;
  let bombers = me.stockpile.bombers;
  let missiles = me.stockpile.missiles;
  const warheads: Record<Yield, number> = {
    large: me.stockpile.warheadsLarge,
    medium: me.stockpile.warheadsMedium,
    small: me.stockpile.warheadsSmall,
  };
  const targetTypeFor = opts.targetTypeFor ?? ((): 'people' => 'people');

  let launched = 0;
  while (true) {
    if (opts.maxLaunches !== undefined && launched >= opts.maxLaunches) break;
    if (remaining < ACTION_COSTS.launch) break;
    if (bombers + missiles < 1) break;
    const y = YIELD_ORDER.find((yy) => warheads[yy] > 0);
    if (y === undefined) break;

    const delivery: 'bomber' | 'missile' = bombers >= 1 ? 'bomber' : 'missile';
    const target = opts.spread
      ? opts.rankedTargets[launched % opts.rankedTargets.length]
      : opts.rankedTargets[0];
    const launch: Order = {
      kind: 'launch',
      target,
      delivery,
      warhead: y,
      targetType: targetTypeFor(target),
    };
    if (!validateOrder(state, leaderId, launch).ok) break;

    orders.push(launch);
    remaining -= ACTION_COSTS.launch;
    warheads[y] -= 1;
    if (delivery === 'bomber') bombers -= 1;
    else missiles -= 1;
    launched += 1;
  }
  return { orders, apSpent: opts.budget - remaining };
}

export function planMileighHem(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];

  const others = state.cast.filter((t) => t !== leaderId && state.leaders[t]?.alive);
  const attackers = others.filter((t) => wasAttackedBy(state, leaderId, t));

  const totalAp = me.apBanked + me.ap;
  const activated = totalAp >= AI_SCORING_WEIGHTS.mileighActivationApThreshold;

  if (activated) {
    // All-out mode: spread salvo first, then build with the remainder.
    const rankedTargets = attackers.length > 0 ? attackers : others;
    const salvo = launchSalvo(state, leaderId, {
      budget: me.ap,
      rankedTargets,
      spread: true,
    });
    const build = buildToward(state, leaderId, MILEIGH_BUILD_PLAN, me.ap - salvo.apSpent);
    return [...build.orders, ...salvo.orders];
  }

  // --- Diplomatic mode (unchanged from P4b) ---
  const orders: Order[] = [];
  let budget = me.ap;
  const WOO_COST = 1;
  const PROPAGANDA_COST = 1;

  const wooPool = attackers.length > 0 ? attackers : others;
  let wooCount = 0;
  for (const t of wooPool) {
    if (wooCount >= 2) break;
    if (budget < WOO_COST) break;
    const woo: Order = { kind: 'woo', target: t };
    if (validateOrder(state, leaderId, woo).ok) {
      orders.push(woo);
      budget -= apCostOf(woo);
      wooCount++;
    }
  }

  let propCount = 0;
  for (const t of attackers) {
    if (propCount >= 2) break;
    if (budget < PROPAGANDA_COST) break;
    const prop: Order = { kind: 'propaganda', target: t };
    if (validateOrder(state, leaderId, prop).ok) {
      orders.push(prop);
      budget -= apCostOf(prop);
      propCount++;
    }
  }

  return orders;
}

function applyRandomization(
  state: GameState,
  leaderId: LeaderId,
  orders: Order[],
  pct: number,
  diff: Difficulty,
): Order[] {
  let rngState = state.rngState;
  const me = state.leaders[leaderId];
  let remainingBudget = me.ap;
  const candidates = randomizationCandidates(diff);

  const out: Order[] = [];
  for (const o of orders) {
    const roll = nextRandom(rngState);
    rngState = roll.state;
    const cost = apCostOf(o);

    if (roll.value < pct) {
      // Replace with a random affordable, valid alternative.
      const affordable = candidates.filter((c) =>
        apCostOf(c) <= remainingBudget && validateOrder(state, leaderId, c).ok,
      );
      if (affordable.length === 0) {
        // Drop the order.
        remainingBudget -= 0;
        continue;
      }
      const pick = nextRandom(rngState);
      rngState = pick.state;
      const replacement = affordable[Math.floor(pick.value * affordable.length)];
      out.push(replacement);
      remainingBudget -= apCostOf(replacement);
    } else {
      if (cost <= remainingBudget) {
        out.push(o);
        remainingBudget -= cost;
      }
      // else: drop — a more expensive replacement upstream consumed budget that
      // this pass-through would have used. Better to drop this order than to
      // silently lose the entire turn at the reducer.
    }
  }

  // Note: this advances `state.rngState` in a "shadow" — the caller dispatches
  // the orders via the reducer and mutates state.rngState there. We don't write
  // back here. Difficulty randomization seeds itself from the read-only rngState,
  // which means two consecutive planAi calls on the same state produce the SAME
  // randomized output. This is intentional for replay determinism: the AI's
  // "random" decisions are bound to the round's seed.
  return out;
}

export function deriveStories(
  game: GameState,
  events: ResolutionEvent[],
  prevPopulations: Partial<Record<LeaderId, number>>,
): NewsStory[] {
  const living = game.cast.filter((id) => game.leaders[id].alive);
  if (living.length === 0) return [];

  let leadId = living[0];
  let leadLoss = 0;
  for (const id of living) {
    const prev = prevPopulations[id];
    const loss = prev === undefined ? 0 : Math.max(0, prev - game.leaders[id].population);
    if (loss > leadLoss) {
      leadLoss = loss;
      leadId = id;
    }
  }

  const ordered = [leadId, ...living.filter((id) => id !== leadId)];
  return ordered.map((id) => {
    const leader = game.leaders[id];
    const prev = prevPopulations[id];
    const cur = leader.population;
    const facts = collectFacts(id, events, cur, prev);
    const reaction = events.find(
      (e): e is Extract<ResolutionEvent, { kind: 'PostRoundReaction' }> =>
        e.kind === 'PostRoundReaction' && e.leaderId === id,
    );

    const delta: NewsStory['delta'] =
      prev !== undefined && prev !== cur
        ? { text: `${prev}M → ${cur}M`, kind: cur < prev ? 'harm' : 'gain' }
        : { text: `${cur}M`, kind: 'neutral' };

    const badges: StoryBadge[] = [];
    if (facts.popDelta < 0) badges.push({ kind: 'harm', text: `−${-facts.popDelta}M citizens` });
    if (facts.popDelta > 0) badges.push({ kind: 'gain', text: `+${facts.popDelta}M citizens` });
    if (facts.factoriesLost > 0) badges.push({ kind: 'harm', text: `−${facts.factoriesLost} factories` });
    if (facts.factoryBuilt) badges.push({ kind: 'gain', text: '+1 factory' });
    if (leader.apBanked > 0) badges.push({ kind: 'neutral', text: `banked ${leader.apBanked} AP` });

    return {
      id,
      lead: id === leadId,
      kicker: AI_KICKERS[id] ?? stripFlag(leader.country).toUpperCase(),
      headline: storyHeadline(leader.name, facts),
      bylineCountry: stripFlag(leader.country),
      delta,
      body: storyBody(facts, game.leaders),
      pullquote: reaction?.quote,
      badges,
    };
  });
}

export function analyseOrderSequence(
  state: GameState,
  leaderId: LeaderId,
  orders: Order[],
): SoftWarning[] {
  const warnings: SoftWarning[] = [];
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return warnings;

  // Project stockpile + queued builds across the sequence.
  let missiles = me.stockpile.missiles;
  let bombers = me.stockpile.bombers;
  let warheads = me.stockpile.warheadsSmall + me.stockpile.warheadsMedium + me.stockpile.warheadsLarge;

  // Pre-scan: count delivery+warhead builds in the queue so each order can
  // ask "is there any delivery/warhead in this sequence (already owned + queued)?"
  let queuedDeliveries = 0;
  let queuedWarheads = 0;
  for (const o of orders) {
    if (o.kind === 'build-missile' || o.kind === 'build-bomber') queuedDeliveries++;
    if (o.kind === 'build-warhead') queuedWarheads++;
  }
  const ownedOrQueuedDeliveries = missiles + bombers + queuedDeliveries;
  const ownedOrQueuedWarheads = warheads + queuedWarheads;

  for (let i = 0; i < orders.length; i++) {
    const o = orders[i];

    if (o.kind === 'build-warhead') {
      if (ownedOrQueuedDeliveries === 0) {
        warnings.push({ kind: 'warhead-no-delivery', orderIndex: i });
      }
    }

    if (o.kind === 'build-missile' || o.kind === 'build-bomber') {
      if (ownedOrQueuedWarheads === 0) {
        warnings.push({ kind: 'delivery-no-warhead', orderIndex: i });
      }
    }

    if (o.kind === 'woo') {
      const target = state.leaders[o.target];
      if (!target) continue;
      const aggression = target.recentAggressionFrom[leaderId] ?? 0;
      const fav = target.favourability[leaderId] ?? 0;
      if (aggression === 0 && fav >= 0) {
        warnings.push({ kind: 'woo-non-attacker', orderIndex: i, target: o.target });
      }
    }

    // Project launch consumption (mirrors validateOrderSequence; cheap copy).
    if (o.kind === 'launch') {
      if (o.delivery === 'missile' && missiles > 0) missiles -= 1;
      else if (o.delivery === 'bomber' && bombers > 0) bombers -= 1;
      if (warheads > 0) warheads -= 1;
    }
  }

  return warnings;
}

export function planChump(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];

  let budget = me.ap;

  const others = state.cast.filter((t) => t !== leaderId && state.leaders[t]?.alive);

  // Eligible launch targets: not protected by Chump's own favourability toward
  // them (a leader who wooed Chump raises me.favourability[t] > 0).
  const eligible = others.filter((t) => (me.favourability[t] ?? 0) <= 0);
  // Weak targets: low defence OR otherwise vulnerable. Ranked weakest-first.
  const weakTargets = eligible
    .filter((t) => opportunismScore(state, t) > 0 || defenceVisibilityScore(state, t) === 0)
    .sort((a, b) => opportunismScore(state, b) - opportunismScore(state, a));

  // Infra targeting when the target still has factories to lose.
  const targetTypeFor = (t: LeaderId): 'people' | 'infra' =>
    state.leaders[t].factories > 2 ? 'infra' : 'people';

  // Reserve 1 AP for propaganda.
  const propagandaReserve = others.length > 0 && budget >= 1 ? PROPAGANDA_COST : 0;
  const offenceBudget = budget - propagandaReserve;

  // Launch first (low cap), then build with the remainder.
  const salvo = launchSalvo(state, leaderId, {
    budget: offenceBudget,
    rankedTargets: weakTargets,
    maxLaunches: CHUMP_MAX_LAUNCHES,
    targetTypeFor,
  });
  const build = buildToward(
    state, leaderId, CHUMP_BUILD_PLAN, offenceBudget - salvo.apSpent,
  );
  budget -= salvo.apSpent + build.apSpent;

  const orders: Order[] = [...build.orders, ...salvo.orders];

  // Deploy a shield if one is in stock and AP allows.
  if (me.stockpile.shields >= 1 && budget >= DEPLOY_COST) {
    const deploy: Order = { kind: 'deploy-defence', type: 'shield' };
    if (validateOrder(state, leaderId, deploy).ok) {
      orders.push(deploy);
      budget -= DEPLOY_COST;
    }
  }

  // Propaganda — broadcast to the first available target.
  if (budget >= PROPAGANDA_COST && others.length > 0) {
    const prop: Order = { kind: 'propaganda', target: others[0] };
    if (validateOrder(state, leaderId, prop).ok) {
      orders.push(prop);
      budget -= apCostOf(prop);
    }
  }

  return orders;
}

export function planAi(state: GameState, leaderId: LeaderId, difficulty?: Difficulty): Order[] {
  const me = state.leaders[leaderId];
  // Alive-check first by design: dead leaders (AI or human) return [] — same shape,
  // same caller contract. The human throw below catches misroutes for ALIVE humans
  // (Phase 3 UI-orchestrator bug), not eliminated humans whose lifecycle handling
  // should mirror eliminated AI. Reordering would create asymmetric semantics
  // (dead AI = []; dead human = throw) for no benefit.
  if (!me || !me.alive) return [];
  if (isHuman(leaderId)) {
    throw new Error(
      `planAi() called for human leader '${leaderId}'. ` +
      `Human leaders submit orders via SUBMIT_ORDERS, not via the AI planner.`,
    );
  }
  const diff = difficulty ?? state.difficulty;

  // Get the per-leader baseline orders (personality-specific, difficulty-agnostic).
  let orders = dispatch(state, leaderId);

  // Hard mode: replace the target of any launch order with the lookahead-optimal target.
  // dispatch is used as the opponent planner so opponents never recurse into Hard.
  if (diff === 'hard') {
    const launchIndex = orders.findIndex((o) => o.kind === 'launch');
    if (launchIndex !== -1) {
      const launch = orders[launchIndex];
      if (launch.kind === 'launch') {
        const others = state.cast.filter((id) => id !== leaderId && state.leaders[id]?.alive);
        if (others.length > 0) {
          const baseline = orders.filter((_, i) => i !== launchIndex);
          const bestTarget = bestTargetByLookahead(
            state,
            leaderId,
            baseline,
            others,
            { delivery: launch.delivery, warhead: launch.warhead, targetType: launch.targetType },
            dispatch,
          );
          if (bestTarget !== null) {
            orders = [
              ...baseline.slice(0, launchIndex),
              { ...launch, target: bestTarget },
              ...baseline.slice(launchIndex),
            ];
          }
        }
      }
    }
  }

  // Easy / Normal randomization: replace each order with probability difficulty-pct.
  if (DIFFICULTY_RANDOM_PCT[diff] > 0) {
    orders = applyRandomization(state, leaderId, orders, DIFFICULTY_RANDOM_PCT[diff], diff);
  }

  return orders;
}

export function planBurnem(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];

  let budget = me.ap;
  const others = state.cast.filter((t) => t !== leaderId && state.leaders[t]?.alive);

  // --- Provocation: any surviving leader who ever landed a hit (grudge persists). ---
  const provokers = others.filter((t) => (me.grudge[t] ?? 0) > 0);
  let target: LeaderId | undefined;
  if (provokers.length > 0) {
    target = provokers.reduce((best, t) =>
      (me.grudge[t] ?? 0) > (me.grudge[best] ?? 0) ? t : best,
    );
  } else if (Object.values(me.grudge).some((g) => (g ?? 0) > 0)) {
    // Provoker(s) dead: stay provoked, redirect to the strongest survivor.
    target = pickStrongestRival(state, leaderId, others);
  } else if (state.round >= BURNEM_PATIENCE_ROUND || others.length === 1) {
    // Patience fallback — deadlock guard.
    target = pickStrongestRival(state, leaderId, others);
  }

  const orders: Order[] = [];

  if (target !== undefined) {
    // --- Provoked: handbrake off. ---
    const build = buildToward(state, leaderId, PROVOKED_BUILD_PLAN, budget);
    const salvo = launchSalvo(state, leaderId, {
      budget: budget - build.apSpent,
      rankedTargets: [target],
      maxLaunches: BURNEM_MAX_LAUNCHES,
    });
    budget -= build.apSpent + salvo.apSpent;
    // Producers precede consumers in the emitted batch.
    orders.push(...build.orders, ...salvo.orders);
  } else {
    // --- Placid: friendliest man in the apocalypse. ---
    const wooTarget = others.length > 0
      ? others.reduce((best, t) =>
          (me.favourability[t] ?? 0) < (me.favourability[best] ?? 0) ? t : best,
        )
      : undefined;
    if (wooTarget !== undefined) {
      const woo: Order = { kind: 'woo', target: wooTarget };
      if (budget >= apCostOf(woo) && validateOrder(state, leaderId, woo).ok) {
        orders.push(woo);
        budget -= apCostOf(woo);
      }
    }
    const build = buildToward(state, leaderId, PLACID_BUILD_PLAN, budget);
    budget -= build.apSpent;
    orders.push(...build.orders);
    if (me.stockpile.shields >= 1 && budget >= DEPLOY_COST) {
      const deploy: Order = { kind: 'deploy-defence', type: 'shield' };
      if (validateOrder(state, leaderId, deploy).ok) {
        orders.push(deploy);
        budget -= DEPLOY_COST;
      }
    }
    // Remaining AP banks implicitly.
  }

  return orders;
}

export abstract class Player {
    private static _STARTING_BIT = 0b1 | 0;
    private static _CURRENT_GROUP = Player._STARTING_BIT;

    public readonly mask: number;
    public active: boolean = false;
    constructor(public name: string, public board: Board) {
        this.mask = Player._CURRENT_GROUP = (Player._CURRENT_GROUP << 1) | 0;
    }

    async turnStart(): Promise<void> {
        this.active = true;
        const units = this.board.getUnits()
            .filter(u => u.player === this);
        units.forEach(u => u.reset());
    }

    hasLost() {
        const units = this.board.getUnits()
            .filter(u => u.player === this);

        return units.length === 0;
    }

    hasWon() {
        const units = this.board.getUnits()
            .filter(u => u.player !== this)
        return units.length === 0;
    }

    async turnEnd(): Promise<void> {
        this.active = false;
    }

    /**
     * 
     * @returns true if done with turn, false if more moves to make
     */
    abstract makeMove(): Promise<boolean>;
}

export function aHandWith(numberOfCards: number, ...cards: Card[]) {
  let cardsOnHand = cards;

  cardsOnHand.push(...sampleSize(cardOrder, numberOfCards - cards.length));

  return new Hand(cardsOnHand);
}

export function aHandWithout(numberOfCards: number, excludedCard: Card) {
  let cards = sampleSize(
    cardOrder.filter(
      (card) =>
        !(card.suit === excludedCard.suit && card.rank === excludedCard.rank)
    ),
    numberOfCards
  );
  return new Hand(cards);
}

export class goodyAnnouncement implements announcementRules {
  announcementToMake(possibleAnnouncements: Set<Announcement>, hand: Hand): Announcement | null {
    if (
      [...possibleAnnouncements].includes(Announcement.Kontra) ||
      [...possibleAnnouncements].includes(Announcement.Re)
    ) {
      let counter = 0;
      if (hand.getBlankAces().length > 0) counter++;
      if (hand.trumps().length >= 7) counter++;
      if (hand.cards.filter((c) => c.is(ten.of(Suit.Hearts))).length === 2) counter++;
      counter += hand.getMissingSuites().length;
      return counter > 2 ? [...possibleAnnouncements][0] : null;
    }
    return null;
  }
}

export class Scorecard {
  players: Player[];
  scoreLines: Scoreline[];

  constructor(players: Player[]) {
    this.players = players;
    this.scoreLines = [];
  }

  addScore(score: Score) {
    const newTotalPoints: { [playerId: string]: number } = {};
    const winningPlayers = score.winner()?.players;
    const winnerPoints = score.totalPoints(score.winningPartyName()!);
    const loserPoints = score.totalPoints(score.losingPartyName()!);

    this.players.forEach((p) => {
      newTotalPoints[p.id] = winningPlayers?.includes(p)
        ? this.totalPointsFor(p) + winnerPoints
        : this.totalPointsFor(p) + loserPoints;
    });

    const scoreline = new Scoreline(newTotalPoints, winningPlayers!, winnerPoints);
    this.scoreLines.push(scoreline);
  }

  totalPointsFor(player: Player) {
    const lineCount = this.scoreLines.length;
    if (lineCount === 0) {
      return 0;
    }
    return this.scoreLines[lineCount - 1].totalPoints[player.id];
  }
}

export default class Wave {
  enemyInitCnt: EnemyInitCnt;
  enemyCnt: EnemyCnt;
  enemyCfg: { [propName: string]: EnemyCfgItem };

  constructor(opt: any = {}) {
    this.enemyInitCnt = opt.enemyInitCnt || {
      a: 10,
      b: 5,
      c: 10,
    };

    this.enemyCnt = {};
    Object.keys(this.enemyInitCnt).forEach((key) => {
      this.enemyCnt[key] = this.enemyInitCnt[key];
    });

    this.enemyCfg = {
      a: {
        radius: 10,
        speed: 1,
        color: '#FFDDA0',
        health: 20,
      },
      b: {
        radius: 8,
        speed: 1.5,
        color: '#0280B2',
        health: 16,
      },
      c: {
        radius: 6,
        speed: 2,
        color: '#FFD387',
        health: 12,
      },
    };
  }

  /**
   * Check if all kinds of enemies are dead
   */
  waveFinish() {
    const keys = Object.keys(this.enemyCnt);
    return keys.every((key) => {
      return this.enemyCnt[key] <= 0;
    });
  }

  generateEnemy() {
    if (this.waveFinish()) {
      return -1;
    } else {
      const keys = Object.keys(this.enemyCnt);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        if (this.enemyCnt[key] > 0) {
          this.enemyCnt[key]--;
          return this.enemyCfg[key];
        }
      }
    }
  }
}

export default class FireZone extends BaseBullet {
  type: string;
  ctx: CanvasRenderingContext2D;
  id: number;
  minRange: number;
  maxRange: number;
  range: number;
  parent: FireTower;
  damage: number;
  maxLife: number;
  life: number;
  x: number;
  y: number;

  constructor(
    opt: Omit<
      IBulletOption & {
        parent: FireTower;
      },
      'x' | 'y' | 'target'
    >
  ) {
    const { ctx, parent, range, damage, id } = opt;
    super(opt);
    this.type = BULLETS.FIRE;
    this.ctx = ctx;
    this.id = id;

    // range 将随时间逐渐加大
    this.minRange = 20;
    this.maxRange = range;
    this.range = this.minRange;

    this.maxLife = 300;
    this.life = this.maxLife;
  }

  draw(ctx: CanvasRenderingContext2D): void {
    if (this.life > 0) {
      this.range = this.calcRange();
      ctx.save();
      ctx.fillStyle = 'rgba(255, 0, 0, 0.15)';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.range, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      this.life--;
    }
  }

  /**
   * range 会随时间由最小值逐步加大至最大值，然后保持在最大值
   */
  calcRange() {
    const minR = this.minRange;
    const maxR = this.maxRange;
    const timePassed = this.maxLife - this.life;
    const timeStop = 100; // 在该时间点range达到最大

    const range =
      minR + (Math.min(timeStop, timePassed) * (maxR - minR)) / timeStop;
    return range;
  }
}

export function buildNotableReactionsSection(
  turnLog: TurnLog,
  newState: GameState,
  playerNationId: string
): { title: string; entries: string[] }

export function grudgeholder(score: number, context: GameContext): number {
  const { state, currentNationId } = context;

  // Check if we were attacked by any nation (they declared war on us)
  const hasAggressors = state.wars.some((w) => w.defenderId === currentNationId);

  if (hasAggressors) {
    return score * 0.4;
  }

  return score;
}

function computeBudget(
  state: GameState,
  playerNationId: string,
  pendingOrders: Order[]
): ActionBudget {
  // Base allocations per §6.3
  const playerArmyCount = state.armies.filter(
    (a) => a.ownerId === playerNationId && a.strength > 0
  ).length;
  const playerProvinceCount = state.provinces.filter(
    (p) => p.ownerId === playerNationId
  ).length;

  const budget: ActionBudget = {
    diplomatic: 2,
    diplomaticUsed: 0,
    military: playerArmyCount,
    militaryUsed: 0,
    construction: playerProvinceCount,
    constructionUsed: 0,
    wildcard: 1,
    wildcardUsed: 0,
  };

  // Count used slots from pending orders
  for (const order of pendingOrders) {
    const cat = getOrderCategory(order);
    switch (cat) {
      case 'diplomatic':
        budget.diplomaticUsed++;
        break;
      case 'military':
        budget.militaryUsed++;
        break;
      case 'construction':
        budget.constructionUsed++;
        break;
      case 'wildcard':
        budget.wildcardUsed++;
        break;
    }
  }

  return budget;
}

function pickBestFocus(nation: Nation, state: GameState): ProvinceFocus {
  const ownedProvinces = state.provinces.filter((p) => p.ownerId === nation.id);

  // Count existing focuses
  const focusCounts: Record<ProvinceFocus, number> = {
    Agricultural: 0,
    Industrial: 0,
    Commercial: 0,
    Military: 0,
  };
  for (const p of ownedProvinces) {
    if (p.focus) focusCounts[p.focus]++;
  }

  // Determine need based on resources
  const res = nation.resources;
  const atWar = state.wars.some(
    (w) => w.aggressorId === nation.id || w.defenderId === nation.id
  );

  // Prioritize based on scarcity
  if (res.food < 10) return 'Agricultural';
  if (atWar && res.manpower < 20) return 'Military';
  if (res.production < 15) return 'Industrial';

  // Otherwise balance based on archetype weights
  const weights = nation.utilityWeights;
  const focusScores: [ProvinceFocus, number][] = [
    ['Agricultural', 0.3 - focusCounts.Agricultural * 0.1],
    ['Industrial', weights.economicDev * 0.5 - focusCounts.Industrial * 0.1],
    ['Commercial', weights.tradeDeal * 0.5 - focusCounts.Commercial * 0.1],
    ['Military', weights.militaryAction * 0.5 - focusCounts.Military * 0.1],
  ];

  focusScores.sort((a, b) => b[1] - a[1]);
  return focusScores[0][0];
}

function getAgendaMultiplier(
  order: Order,
  nation: Nation,
  state: GameState
): number {
  const agenda = nation.agenda;
  const priorityBonus = agenda.priority === 'high' ? 1.5 : agenda.priority === 'medium' ? 1.25 : 1.1;

  switch (agenda.type) {
    case 'control_region_cluster': {
      if (!agenda.targetRegions) return 1.0;
      // Boost military moves toward target regions and construction in target regions
      if (order.type === 'move_army') {
        if (agenda.targetRegions.includes(order.toProvinceId)) return priorityBonus;
      }
      if (order.type === 'upgrade_dev' || order.type === 'set_focus' || order.type === 'build_fort') {
        if (agenda.targetRegions.includes(order.provinceId)) return priorityBonus;
      }
      if (order.type === 'declare_war') {
        // Check if the target nation owns any target regions
        const targetOwnsRegion = agenda.targetRegions.some((r) => {
          const prov = state.provinces.find((p) => p.id === r);
          return prov?.ownerId === order.targetNationId;
        });
        if (targetOwnsRegion) return priorityBonus;
      }
      return 1.0;
    }
    case 'economic_dominance': {
      if (order.type === 'upgrade_dev' || order.type === 'set_focus') return priorityBonus;
      if (order.type === 'propose_agreement' && order.agreementType === 'TradeDeal') return priorityBonus;
      return 1.0;
    }
    case 'military_supremacy': {
      if (order.type === 'move_army' || order.type === 'declare_war' || order.type === 'blockade') {
        return priorityBonus;
      }
      if (order.type === 'build_fort') return priorityBonus;
      return 1.0;
    }
    case 'diplomatic_hegemony': {
      if (
        order.type === 'propose_agreement' ||
        order.type === 'offer_peace' ||
        order.type === 'spy'
      ) {
        return priorityBonus;
      }
      return 1.0;
    }
  }

  return 1.0;
}

function generateConstructionCandidates(
  nation: Nation,
  context: GameContext
): ActionCandidate[] {
  const { state } = context;
  const weights = nation.utilityWeights;
  const candidates: ActionCandidate[] = [];
  const ownedProvinces = state.provinces.filter((p) => p.ownerId === nation.id);

  for (const province of ownedProvinces) {
    // --- Upgrade dev ---
    if (province.devLevel < 5) {
      const cost = province.devLevel * 10;
      const canAfford = nation.resources.gold >= cost && nation.resources.production >= cost;

      if (canAfford) {
        // Higher value for lower-dev provinces (more efficient)
        const efficiency = (6 - province.devLevel) / 5;

        candidates.push({
          order: {
            type: 'upgrade_dev',
            nationId: nation.id,
            provinceId: province.id,
          },
          category: 'construction',
          score: weights.economicDev * efficiency * 0.7,
        });
      }
    }

    // --- Set focus (devLevel >= 2, no focus or suboptimal focus) ---
    if (province.devLevel >= 2 && province.focus === null) {
      const bestFocus = pickBestFocus(nation, state);
      candidates.push({
        order: {
          type: 'set_focus',
          nationId: nation.id,
          provinceId: province.id,
          focus: bestFocus,
        },
        category: 'construction',
        score: weights.economicDev * 0.8, // High priority — no focus means wasted potential
      });
    }

    // --- Build fort on border provinces ---
    if (province.fortLevel < 3) {
      const onBorder = isBorderProvince(province.id, nation.id, state);
      const fortCost = (province.fortLevel + 1) * 15;
      const canAfford = nation.resources.production >= fortCost;

      if (onBorder && canAfford) {
        const isStrategic = province.strategicTag === 'Capital' || province.strategicTag === 'KeyRegion';
        const strategicBonus = isStrategic ? 0.3 : 0;

        candidates.push({
          order: {
            type: 'build_fort',
            nationId: nation.id,
            provinceId: province.id,
          },
          category: 'construction',
          score: weights.defensivePosture * 0.4 + strategicBonus,
        });
      }
    }
  }

  return candidates;
}

export function aiDeck(tierIndex: number): SideCard[] {
  const tier = CAMPAIGN_TIERS[tierIndex];
  if (!tier) throw new Error(`no campaign tier ${tierIndex}`);
  return tier.codes.map(card);
}

export function deckFromPool(rng: Rng, pool: BuiltInCardPool): SideCard[] {
  const src = POOLS[pool];
  return Array.from({ length: SIDE_DECK_SIZE }, () => src[rng.randint(0, src.length - 1)]);
}

export function deckFromCodes(codes: readonly string[]): SideCard[] {
  const normalized = normalizeDeckCodes([...codes]);
  if (!normalized) throw new Error(`custom deck must contain exactly ${SIDE_DECK_SIZE} valid cards`);
  return normalized.map(card);
}

export function resolveOnlineSideDecks(
  rng: Rng,
  mode: CardPool,
  hostCustomDeck: string[] | null,
  guestCustomDeck: string[] | null,
): OnlineSideDecks {
  return {
    hostDeck: sideDeckForPool(rng, mode, hostCustomDeck),
    guestDeck: sideDeckForPool(rng, mode, guestCustomDeck),
  };
}

export function sideDeckForPool(rng: Rng, pool: CardPool, customCodes?: string[] | null): SideCard[] {
  if (pool === 'builder') {
    const codes = customCodes ?? loadCustomDeckCodes();
    const normalized = codes ? normalizeDeckCodes(codes) : null;
    return normalized ? normalized.map(card) : deckFromPool(rng, 'mix');
  }
  return deckFromPool(rng, pool as BuiltInCardPool);
}

export function routeToHash(route: Route): string {
  switch (route.mode) {
    case 'main-menu':
      return '';
    case 'single-menu':
      return '#singleplayer';
    case 'deck-builder':
      return '#deck-builder';
    case 'quick-setup':
      return '#quick';
    case 'quick-opponent':
      return `#quick-opponent=${route.pool}`;
    case 'quick-game':
      return `#quick=${route.pool}${route.companion ? `&companion=${route.companion}` : ''}`;
    case 'campaign':
      return '#campaign';
    case 'campaign-game':
      return `#campaign=${route.difficulty}`;
    case 'multi-menu':
      return '#multiplayer';
    case 'hotseat':
      return '#hotseat';
    case 'online':
      return `#room=${encodeURIComponent(route.roomId)}`;
  }
}

function snapshotToDisplay(state: SeatState, mySeat: Seat): Display {
  const toCards = (cards: TableCardTuple[]): DisplayCard[] =>
    cards.map(([label, , family]) => ({ key: `c${cardSeq++}`, label, family }));
  const other = (1 - mySeat) as Seat;
  const tables: [DisplayCard[], DisplayCard[]] = [[], []];
  tables[mySeat] = toCards(state.you.table);
  tables[other] = toCards(state.opponent.table);
  const totals: [number, number] = [0, 0];
  totals[mySeat] = state.you.total;
  totals[other] = state.opponent.total;
  const standing: [boolean, boolean] = [false, false];
  standing[mySeat] = state.you.standing;
  standing[other] = state.opponent.standing;
  const scores: [number, number] = [0, 0];
  scores[mySeat] = state.match_score.you;
  scores[other] = state.match_score.opponent;
  return { tables, totals, standing, scores, setNumber: state.set_number };
}

