export function shuffle<T>(array: T[]): T[] {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

export function playerHandLen(player: Player, kind: HandKind) {
  switch (kind) {
    case "hand":
      return player.hand.length;
    case "faceDown":
    case "faceUp":
      return offHandLen(player.offHand[kind]);
  }
}

export class NotBuilt extends BaseState {
	isSetup = false;

	update(deltaTime: number, entity: any): void {
		if (!this.isSetup) {
			if (screen.isMobile) {
				this.entity.position.y += 30;
			} else {
				this.entity.position.y += 35;
			}

			this.isSetup = true;
		}
	}
}

export class FollowAngle extends BaseState {
	update(deltaTime: number) {
		this.follow(deltaTime);
	}

	follow(deltaTime: number) {
		const { angle } = this.stateMachine.context;
		const direction = getDirectionFromAngle(angle);

		const velocity = direction.multiply(this.entity.stats.speed * deltaTime);
		this.entity.position = this.entity.position.add(velocity);
		this.entity.rotation = (angle * 180) / Math.PI + 90;
	}
}

export class Screen {
	width = $state(0);
	height = $state(0);
	gameAreaWidth = $state(0);
	gameAreaHeight = $state(0);
	gameXOffset = $state(0);
	gameYOffset = $state(0);
	isMobile = $derived(this.width < 768);

	get screenBounds() {
		return {
			x1: 0,
			y1: 0,
			x2: this.width,
			y2: this.height
		};
	}

	get gameBoundingBox() {
		return {
			x1: this.gameXOffset,
			y1: this.gameYOffset,
			x2: this.width,
			y2: this.height
		};
	}

	isEntityInScreen(entity: Entity): boolean {
		const { x1, y1, x2, y2 } = this.screenBounds;
		const { x, y } = entity.position;

		return (
			x + entity.width / 2 > x1 &&
			x - entity.width / 2 < x2 &&
			y + entity.height > y1 &&
			y - entity.height < y2
		);
	}
}

