export function checkFlankingStatus(facingDir: HexDirection, attackFromDir: HexDirection): HexFlankStatus {
  if (facingDir === HexDirection.NONE || attackFromDir === HexDirection.NONE) {
    return HexFlankStatus.NONE;
  }

  // Directions
  //     \ 3 |  2 /
  //      \/  \ /
  //    4 |   |  1
  //     /\  / \
  //   / 5 |  6 \
  // If the unit is facing direction 4 and
  // - the attack is coming from direction 2 or 6, it is a flanking attack.
  // - the attack is coming from direction 1, it is a backstab.
  // - the attack is coming from other directions, it is a normal attack.

  const relativeDir = (6 + attackFromDir - facingDir) % 6 + 1;
  if (relativeDir === 3 || relativeDir === 5) {
    return HexFlankStatus.FLANK;
  } else if (relativeDir === 4) {
    return HexFlankStatus.BACKSTAB;
  }

  return HexFlankStatus.NONE;
}

export function analyzeAllTowers(avgTargets: number = 1): TowerDPS[] {
  const results: TowerDPS[] = [];
  for (const type of Object.values(TowerType)) {
    const levels = TOWER_LEVELS[type];
    for (let lvl = 0; lvl < levels.length; lvl++) {
      results.push(analyzeTowerDPS(type, lvl, avgTargets));
    }
  }
  return results;
}

export function towerSummary(type: TowerType, level: number = 0, avgTargets: number = 1): string {
  const t = analyzeTowerDPS(type, level, avgTargets);
  const abilities = t.abilities.length > 0 ? ` [${t.abilities.join(", ")}]` : "";
  return `${t.name} Lv${level + 1}: ${t.rawDPS.toFixed(1)} raw / ${t.effectiveDPS.toFixed(1)} eff DPS, ${t.totalCost}g (${t.dpsPerGold.toFixed(2)}/g)${abilities}`;
}

function buildArrowMeshes(): Mesh[] {
  const baseGeo = new CylinderGeometry(0.3, 0.35, 0.5, 8);
  const baseMat = new MeshStandardMaterial({ color: 0x8e44ad });
  const base = new Mesh(baseGeo, baseMat);
  base.position.y = 0.35;

  const topGeo = new BoxGeometry(0.25, 0.2, 0.25);
  const topMat = new MeshStandardMaterial({ color: 0x9b59b6 });
