export function wasAttackedBy(state: GameState, viewer: LeaderId, attacker: LeaderId): boolean {
  const me = state.leaders[viewer];
  if (!me) return false;
  return (me.grudge[attacker] ?? 0) > 0 || (me.recentAggressionFrom[attacker] ?? 0) > 0;
}

function pickStrongestRival(
  state: GameState, viewer: LeaderId, others: LeaderId[],
): LeaderId | undefined {
  if (others.length === 0) return undefined;
  return others.reduce((best, t) =>
    threatScore(state, viewer, t) > threatScore(state, viewer, best) ? t : best,
  );
}

function countImpacts(game: GameState, side: 'from' | 'target', id: LeaderId): number {
  let count = 0;
  for (const event of game.log) {
    if (event.kind === 'ImpactPeople' || event.kind === 'ImpactInfrastructure') {
      if (event[side] === id) count += 1;
    }
  }
  return count;
}

function combinedScore(target: LeaderId): number {
    const base = threatScore(state, leaderId, target);
    const escalated =
      (me.recentAggressionFrom[target] ?? 0) > 0
        ? base * AI_SCORING_WEIGHTS.carnageEscalationMultiplier
        : base;
    return escalated + opportunismScore(state, target);
  }

export function topGrudgeTarget(state: GameState, viewer: LeaderId): LeaderId | null {
  const me = state.leaders[viewer];
  if (!me) return null;
  let best: LeaderId | null = null;
  let bestVal = 0;
  for (const k of Object.keys(me.grudge) as LeaderId[]) {
    const v = me.grudge[k] ?? 0;
    if (v > bestVal) {
      bestVal = v;
      best = k;
    }
  }
  return best;
}

export function scoreState(state: GameState, viewer: LeaderId): number {
  if (state.outcome) {
    if (state.outcome.type === 'apocalypse') return -500;
    if (state.outcome.winner === viewer) return 1000;
    return -1000;
  }
  const me = state.leaders[viewer];
  if (!me) return -1000;
  const others = state.cast
    .filter((id) => id !== viewer)
    .map((id) => state.leaders[id])
    .filter((l) => l && l.alive);
  if (others.length === 0) return 1000; // we're the only one alive — effectively win
  const maxOther = Math.max(...others.map((o) => o!.population));
  return me.population - maxOther;
}

export function deriveMarket(
  game: GameState,
  prevPopulations: Partial<Record<LeaderId, number>>,
): MarketRow[] {
  return game.cast.map((id) => {
    const leader = game.leaders[id];
    const prev = prevPopulations[id] ?? 0;
    const change = prev > 0 ? Math.round(((leader.population - prev) / prev) * 100) : 0;
    const note =
      !leader.alive ? 'delisted' :
      change <= -20 ? 'clobbered' :
      change < 0 ? 'down' :
      change === 0 ? 'holds' : 'up';
    return {
      id,
      sym: tickerSym(id, leader.country),
      arrow: change > 0 ? '▲' : change < 0 ? '▼' : '▬',
      change,
      note,
    };
  });
}

export function simulateOneRound(
  state: GameState,
  ordersByLeader: Partial<Record<LeaderId, Order[]>>,
): GameState {
  let s = state;
  for (const id of state.cast) {
    const orders = ordersByLeader[id] ?? [];
    const next = reduce(s, { type: 'SUBMIT_ORDERS', leaderId: id, orders });
    if (next === s) {
      // Order set was rejected (e.g., AP overrun). Fall back to empty orders so
      // the simulation still progresses; AI personalities may pass orders that
      // exceed budget when constructing speculative candidates.
      s = reduce(s, { type: 'SUBMIT_ORDERS', leaderId: id, orders: [] });
    } else {
      s = next;
    }
  }
  s = reduce(s, { type: 'RESOLVE_ROUND' });
  return s;
}

export function dispatch(state: GameState, leaderId: LeaderId): Order[] {
  switch (leaderId) {
    case 'chump': return planChump(state, leaderId);
    case 'carnage': return planCarnage(state, leaderId);
    case 'khameneverhere': return planKhameneverhere(state, leaderId);
    case 'netanyahoo': return planNetanyahoo(state, leaderId);
    case 'burnem': return planBurnem(state, leaderId);
    case 'mileigh-hem': return planMileighHem(state, leaderId);
    case 'player1':
    case 'player2':
    case 'player3':
    case 'player4':
    case 'player5':
      throw new Error(
        `dispatch() called for human player slot '${leaderId}'. ` +
        `Human leaders submit orders via SUBMIT_ORDERS, not via the AI dispatcher.`,
      );
  }
}

export function checkOutcome(
  state: GameState,
  startOfRoundPop: Partial<Record<LeaderId, number>>,
): WinOutcome | null {
  const alive = state.cast.filter((id) => state.leaders[id].population > 0);

  // 1) Survivor — exactly one leader alive.
  if (alive.length === 1) {
    return { type: 'survivor', winner: alive[0] };
  }

  // 2) Pyrrhic / apocalypse — nobody alive.
  if (alive.length === 0) {
    let bestId: LeaderId | undefined;
    let bestPop = -1;
    for (const id of state.cast) {
      const p = startOfRoundPop[id] ?? 0;
      if (p > bestPop) {
        bestPop = p;
        bestId = id;
      }
    }
    if (bestPop > 0 && bestId) return { type: 'pyrrhic', winner: bestId };
    return { type: 'apocalypse' };
  }

  return null;
}

export function derivePhotoCaption(
  events: ResolutionEvent[],
  leaders: GameState['leaders'],
): string {
  const pairs = new Map<string, { target: LeaderId; deaths: number }>();
  for (const e of events) {
    if (e.kind !== 'ImpactPeople') continue;
    const k = `${e.from}|${e.target}`;
    const cur = pairs.get(k);
    if (cur) cur.deaths += e.deaths;
    else pairs.set(k, { target: e.target, deaths: e.deaths });
  }
  const all = [...pairs.values()];
  if (all.length === 0) {
    return 'File photo of a previous detonation. Nothing exploded tonight. Cherish it.';
  }
  let biggest = all[0];
  for (const p of all) if (p.deaths > biggest.deaths) biggest = p;
  const country = stripFlag(leaders[biggest.target].country);
  return `Eyewitness sketch of the impact zone over ${country}. Artist's impression.`;
}

export function planKhameneverhere(state: GameState, leaderId: LeaderId): Order[] {
  const me = state.leaders[leaderId];
  if (!me || !me.alive) return [];

  const others = state.cast.filter((t) => t !== leaderId && state.leaders[t]?.alive);

  // Rank: top grudge target first, then the remaining living leaders.
  const top = topGrudgeTarget(state, leaderId);
  const rankedTargets: LeaderId[] =
    top !== null && others.includes(top)
      ? [top, ...others.filter((t) => t !== top)]
      : [...others];

  // Launch first (uncapped), then build with the remainder.
  const salvo = launchSalvo(state, leaderId, { budget: me.ap, rankedTargets });
  const build = buildToward(
    state, leaderId, KHAMENEVERHERE_BUILD_PLAN, me.ap - salvo.apSpent,
  );

  // Builds precede launches in the submitted array.
  return [...build.orders, ...salvo.orders];
}

export function applyPropaganda(
  state: GameState,
  ordersByLeader: Partial<Record<LeaderId, Order[]>>,
): PropagandaResult {
  const next: GameState = structuredClone(state);
  const events: ResolutionEvent[] = [];
  const propagandists = Object.keys(ordersByLeader).sort() as LeaderId[];
  for (const id of propagandists) {
    const orders = ordersByLeader[id] ?? [];
    for (const o of orders) {
      if (o.kind !== 'propaganda') continue;
      const me = next.leaders[id];
      const target = next.leaders[o.target];
      if (!me || !me.alive || !target || !target.alive) continue;
      const amount = Math.min(PROPAGANDA_TRANSFER_M, target.population);
      if (amount <= 0) continue;
      target.population -= amount;
      me.population += amount;
      events.push({ kind: 'PropagandaTransfer', from: id, to: o.target, amount });
    }
  }
  return { state: next, events };
}

export function shuffle<T>(arr: T[]): T[] {
  const a = [...arr]; // copy, we want to keep it immutable

  for (let i = a.length - 1; i >= 1; i--) {
    let j = randomInt(i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }

  return a;
}

