function distBulletToEnemy(bullet: Bullet, enemy: Enemy) {
  let dist;

  switch (bullet.type) {
    case BULLETS.CIRCLE:
    case BULLETS.SLOW:
    case BULLETS.FIRE:
      dist = calculateDistance(bullet.x, bullet.y, enemy.x, enemy.y);
      break;
    case BULLETS.LASER:
      if ((bullet as Laser).target.id === enemy.id) {
        dist = 0;
      }
      break;
  }
  return dist;
}

export default class FireTower extends BaseTower {
  shooting: boolean;
  bullets: FireZone[];

  constructor(opt: any) {
    super(opt);

    this.type = 'FIRE';
    this.hue = 0;
    this.cost = towerData[this.type].cost;

    this.range = 3 * gridWidth;

    this.shooting = false;
    this.damage = 0.05;
  }

  shoot() {
    const fireZone = new FireZone({
      id: globalId.genId(),
      ctx: this.ctx,
      range: this.range,
      damage: this.damage,
      parent: this,
    });
    this.bullets.push(fireZone);
  }

  draw() {
    const ctx = this.ctx;
    ctx.save();
    // 在选中的情况下，画出其射程范围
    if (this.selected) {
      ctx.beginPath();
      ctx.fillStyle = 'rgba(200, 200, 200, 0.3)';
      ctx.arc(this.x, this.y, this.range, 0, 2 * Math.PI);
      ctx.fill();
    }

    ctx.strokeStyle = 'hsl(' + this.hue + ',100%, 80%';
    ctx.fillStyle = 'hsl(' + this.hue + ',100%, 80%';
    // ctx.fillStyle = 'rgba(1, 158, 213, 0.3)';
    ctx.lineWidth = Math.max(3, this.radius / 8);

    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, 2 * Math.PI);
    ctx.closePath();
    ctx.stroke();
    ctx.fill();

    if (this.targetIndex !== -1 && !this.shooting) {
      this.shoot();
      this.shooting = true;
    }

    ctx.restore();
  }
}

export default class SlowField extends BaseBullet {
  type: BULLET_TYPE;
  ctx: CanvasRenderingContext2D;
  id: number;
  minRange: number;
  maxRange: number;
  range: number;
  parent: SlowTower;
  ratio: number;
  life: number;
  maxLife: number;
  x: number;
  y: number;

  constructor(
    opt: IBulletOption & {
      ratio: number;
      parent: SlowTower;
    }
  ) {
    super({ ...opt, damage: 0 });
    const { range, ratio } = opt;
    this.type = BULLETS.SLOW;

    // range 将随时间逐渐加大
    this.minRange = 20;
    this.maxRange = range;
    this.range = this.minRange;

    this.ratio = ratio; // 减速系数

    this.maxLife = 300;
    this.life = this.maxLife;
  }

  draw(ctx: CanvasRenderingContext2D) {
    if (this.life > 0) {
      this.range = this.calcRange();
      ctx.save();
      ctx.fillStyle = 'rgba(1, 158, 213, 0.15)';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.range, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      this.life--;
    }
  }

  /**
   * range 会随时间由最小值逐步加大至最大值，然后保持在最大值
   */
  calcRange() {
    const minR = this.minRange;
    const maxR = this.maxRange;
    const timePassed = this.maxLife - this.life;
    const timeStop = 100; // 在该时间点range达到最大

    const range =
      minR + (Math.min(timeStop, timePassed) * (maxR - minR)) / timeStop;
    return range;
  }
}

function getAdjacentProvinceIds(provinceId: string, state: GameState): string[] {
  const ids: string[] = [];
  for (const edge of state.edges) {
    if (edge.sourceId === provinceId) ids.push(edge.targetId);
    if (edge.targetId === provinceId) ids.push(edge.sourceId);
  }
  return ids;
}

export function generateAllNpcOrders(
  state: GameState,
  playerNationId: string
): Record<string, Order[]> {
  const orders: Record<string, Order[]> = {};

  for (const nation of state.nations) {
    if (nation.id === playerNationId) continue;
    if (nation.eliminatedOnTurn !== undefined) continue;
    orders[nation.id] = generateNpcOrders(nation.id, state);
  }

  return orders;
}

function computeActionBudget(nationId: string, state: GameState): ActionBudget {
  const armyCount = state.armies.filter((a) => a.ownerId === nationId).length;
  const provinceCount = state.provinces.filter((p) => p.ownerId === nationId).length;

  return {
    diplomatic: 2,
    diplomaticUsed: 0,
    military: armyCount,
    militaryUsed: 0,
    construction: provinceCount,
    constructionUsed: 0,
    wildcard: 1,
    wildcardUsed: 0,
  };
}

export function exportSave(state: GameState): void {
  const envelope: SaveEnvelope = {
    version: SAVE_VERSION,
    savedAt: new Date().toISOString(),
    scenarioId: state.scenario.meta.id,
    turn: state.turn,
    state,
  };

  const json = JSON.stringify(envelope, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);

  const filename = `${state.scenario.meta.id}_turn${state.turn}.json`;

  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.style.display = 'none';
  document.body.appendChild(anchor);
  anchor.click();

  // Clean up
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}

export function applyEventEffects(
  state: GameState,
  event: GameEvent,
  targetNationId: string
): GameState {
  let { nations, provinces } = state;
  const { wars } = state;

  for (const effect of event.effects) {
    switch (effect.type) {
      case 'resource_delta': {
        nations = nations.map((n) =>
          n.id === targetNationId ? applyResourceDelta(n, effect) : n
        );
        break;
      }
      case 'relation_delta': {
        nations = applyRelationDelta(nations, targetNationId, effect, wars);
        break;
      }
      case 'unrest_delta': {
        provinces = applyUnrestDelta(provinces, targetNationId, effect);
        break;
      }
      case 'owner_change': {
        provinces = applyOwnerChange(provinces, targetNationId, effect);
        break;
      }
      case 'population_change': {
        provinces = applyPopulationChange(provinces, targetNationId, effect);
        break;
      }
      case 'dev_cost_modifier':
      case 'output_modifier': {
        // These effects are tracked as modifiers and consumed by relevant systems
        // They require a duration tracking mechanism; stored as active effects
        // For now, the modifier effects are noted in the turn log
        break;
      }
    }
  }

  return { ...state, nations, provinces };
}

export function applyRelationDelta(
  nations: Nation[],
  sourceNationId: string,
  effect: RelationDeltaEffect,
  wars: War[]
): Nation[] {
  return nations.map((n) => {
    if (n.id === sourceNationId) {
      const newRelations = { ...n.relations };
      if (effect.targets === 'all_at_war') {
        for (const war of wars) {
          if (war.aggressorId === sourceNationId) {
            newRelations[war.defenderId] = clampRelation(
              (newRelations[war.defenderId] ?? 0) + effect.amount
            );
          } else if (war.defenderId === sourceNationId) {
            newRelations[war.aggressorId] = clampRelation(
              (newRelations[war.aggressorId] ?? 0) + effect.amount
            );
          }
        }
      } else if (effect.targets === 'all_neighbors' || effect.targets === 'all') {
        for (const other of nations) {
          if (other.id !== sourceNationId) {
            newRelations[other.id] = clampRelation(
              (newRelations[other.id] ?? 0) + effect.amount
            );
          }
        }
      } else {
        // Specific nation target
        newRelations[effect.targets] = clampRelation(
          (newRelations[effect.targets] ?? 0) + effect.amount
        );
      }
      return { ...n, relations: newRelations };
    }
    return n;
  });
}

function applyModifiers(
  score: number,
  context: GameContext,
  nation: Nation,
  category: 'diplomatic' | 'military' | 'construction' | 'wildcard',
  isBetrayal: boolean,
  isNaval: boolean
): number {
  let adjusted = score;

  for (const mod of nation.modifiers) {
    const fn = MODIFIER_FNS[mod];
    if (!fn) continue;

    switch (mod as Modifier) {
      case 'Opportunist':
        // Applies to aggressive actions (military + war declarations)
        if (category === 'military' || isBetrayal) {
          adjusted = fn(adjusted, context);
        }
        break;
      case 'Paranoid':
        // Applies to defensive actions (defensive posture, NAPs)
        if (category === 'construction' || category === 'diplomatic') {
          adjusted = fn(adjusted, context);
        }
        break;
      case 'Honorable':
        // Applies only to betrayal actions (breaking agreements, declaring war on partners)
        if (isBetrayal) {
          adjusted = fn(adjusted, context);
        }
        break;
      case 'NavalFocus':
        // Applies only to naval-related actions
        if (isNaval) {
          adjusted = fn(adjusted, context);
        }
        break;
      case 'Grudgeholder':
        // Applies to peace offers toward aggressors
        if (category === 'diplomatic') {
          adjusted = fn(adjusted, context);
        }
        break;
      case 'Militarist':
        // Applies to all military actions
        if (category === 'military') {
          adjusted = fn(adjusted, context);
        }
        break;
    }
  }

  return adjusted;
}

function selectOrders(
  candidates: ActionCandidate[],
  budget: ActionBudget,
  nation: Nation
): Order[] {
  const selected: Order[] = [];
  const usedArmyIds = new Set<string>();
  const usedProvinceIds = new Set<string>();

  // Group by category
  const diplomatic = candidates.filter((c) => c.category === 'diplomatic');
  const military = candidates.filter((c) => c.category === 'military');
  const construction = candidates.filter((c) => c.category === 'construction');
  const wildcard = candidates.filter((c) => c.category === 'wildcard');

  // Sort each group by score descending
  diplomatic.sort((a, b) => b.score - a.score);
  military.sort((a, b) => b.score - a.score);
  construction.sort((a, b) => b.score - a.score);
  wildcard.sort((a, b) => b.score - a.score);

  // Select diplomatic orders (up to budget, overflow costs Influence)
  let diploUsed = 0;
  const maxDiploOrders = budget.diplomatic + (nation.resources.influence >= 20 ? 1 : 0);
  for (const candidate of diplomatic) {
    if (diploUsed >= maxDiploOrders) break;
    // Skip low-scoring candidates
    if (candidate.score < 0.1) continue;
    selected.push(candidate.order);
    diploUsed++;
  }

  // Select military orders (1 per army, no duplicate army usage)
  for (const candidate of military) {
    const order = candidate.order;
    if (order.type === 'move_army' || order.type === 'retreat') {
      if (usedArmyIds.has(order.armyId)) continue;
      usedArmyIds.add(order.armyId);
    } else if (order.type === 'blockade') {
      if (usedArmyIds.has(order.armyId)) continue;
      usedArmyIds.add(order.armyId);
    }
    if (candidate.score < 0.05) continue;
    selected.push(candidate.order);
  }

  // Select construction orders (1 per province)
  let constructionUsed = 0;
  for (const candidate of construction) {
    if (constructionUsed >= budget.construction) break;
    const order = candidate.order;
    if (order.type === 'upgrade_dev' || order.type === 'set_focus' || order.type === 'build_fort') {
      if (usedProvinceIds.has(order.provinceId)) continue;
      usedProvinceIds.add(order.provinceId);
    }
    if (candidate.score < 0.05) continue;
    selected.push(candidate.order);
    constructionUsed++;
  }

  // Select wildcard order (at most 1)
  if (wildcard.length > 0 && wildcard[0].score >= 0.1) {
    selected.push(wildcard[0].order);
  }

  return selected;
}

