export class SeededRng implements Rng {
  private state: number;

  constructor(seed = Date.now() >>> 0) {
    this.state = seed >>> 0;
  }

  private next(): number {

    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  randint(a: number, b: number): number {
    return a + Math.floor(this.next() * (b - a + 1));
  }

  shuffle<T>(list: T[]): void {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
  }

  sample<T>(list: readonly T[], k: number): T[] {
    const pool = [...list];
    this.shuffle(pool);
    return pool.slice(0, k);
  }
}

export function setBannerText(
  t: (key: string, params?: Record<string, string | number>) => string,
  winner: Seat | null,
  totals: [number, number],
  mySeat: Seat | null,
  reason: SetReason,
): string {
  if (winner == null) {
    return t('tie_set', { mine: totals[0], theirs: totals[1] });
  }
  const bust = reason === 'bust';
  const nineCards = reason === 'nine-cards';
  if (mySeat == null) {
    const params = {
      player: winner + 1,
      loser: (1 - winner) + 1,
      mine: totals[winner],
      theirs: totals[1 - winner],
    };
    if (bust) return t('player_bust_set', params);
    if (nineCards) return t('player_nine_cards_set', params);
    return t('player_wins_set', params);
  }
  const mine = totals[mySeat];
  const theirs = totals[1 - mySeat];
  if (winner === mySeat) {
    if (bust) return t('opponent_bust_set', { mine, theirs });
    if (nineCards) return t('you_nine_cards_set', { mine, theirs });
    return t('you_win_set', { mine, theirs });
  }
  if (bust) return t('you_bust_set', { mine, theirs });
  if (nineCards) return t('opponent_nine_cards_set', { mine, theirs });
  return t('opponent_wins_set', { mine, theirs });
}

export function useLobby(active: boolean) {
  const [activeGames, setActiveGames] = useState<ActiveGame[]>([]);
  const [connecting, setConnecting] = useState(false);

  useEffect(() => {
    if (!active) {
      setActiveGames([]);
      setConnecting(false);
      return;
    }

    setConnecting(true);
    const room = createRoom(LOBBY_ROOM_ID);
    const [ , getAnnounce] = room.makeAction('announce') as unknown as [unknown, (cb: (m: LobbyAnnounceMessage, peerId: string) => void) => void];


    getAnnounce((data, peerId) => {
      setConnecting(false);
      setActiveGames((prev) => {
        const exists = prev.some((g) => g.peerId === peerId);
        if (exists) {
          return prev.map((g) =>
            g.peerId === peerId ? { peerId, roomId: data.roomId, hostName: data.hostName } : g,
          );
        }
        return [...prev, { peerId, roomId: data.roomId, hostName: data.hostName }];
      });
    });

    room.onPeerLeave((peerId) => {
      setActiveGames((prev) => prev.filter((g) => g.peerId !== peerId));
    });


    const timeout = setTimeout(() => {
      setConnecting(false);
    }, 4000);

    return () => {
      clearTimeout(timeout);
      void room.leave();
    };
  }, [active]);

  return { activeGames, connecting };
}

function delayedTimeout(low: number, high: number, cb: () => void) {
  const timeout = low + Math.floor(Math.random() * (high - low));
  return window.setTimeout(cb, timeout);
}

function topCard(pile: Readonly<Pile>): Card | undefined {
  const top = pile.at(-1);
  if (top === undefined) return;
  if (getRank(top) === Rank.Num8) return topCard(pile.slice(0, -1));
  return top;
}

export function canPlay(card: Readonly<Card>, pile: Readonly<Pile>): boolean {
  if ([Rank.Num2, Rank.Num8].includes(getRank(card))) return true;
  const top = topCard(pile);
  if (top === undefined) return true;
  if (getRank(top) === Rank.Num7) return getRank(card) <= getRank(top);
  return getRank(card) >= getRank(top);
}

export function isPileBurnable(pile: Readonly<Pile>): boolean {
  const topCard = pile.at(-1);
  if (topCard === undefined) return false;
  const isTopCard10 = getRank(topCard) === Rank.Num10;
  const areTop4CardsSameRank =
    pile.length >= 4 &&
    pile.slice(-4).every((card) => getRank(card) === getRank(topCard));
  return isTopCard10 || areTop4CardsSameRank;
}

