export class MagicCollisionChecker {
  #touchedEnemiesIds: number[] = []
  constructor() {}

  setToIgnoreList(enemy: Enemy) {
    this.#touchedEnemiesIds.push(enemy.id)
  }

  #hasPreviouslyCollided(enemy: Enemy) {
    const found = this.#touchedEnemiesIds.find((id) => id === enemy.id)
    return found !== undefined
  }

  #isMagicColliding(enemy: Enemy, indexOrder: number) {
    const distanceBetween = Math.abs(indexOrder - enemy.orderPosition)
    return indexOrder >= enemy.orderPosition && distanceBetween < 1
  }

  shouldCollide(enemy: Enemy, indexOrder: number) {
    if (enemy.isDead || enemy.isWinner) {
      return false
    }

    if (this.#hasPreviouslyCollided(enemy)) {
      return false
    }

    if (this.#isMagicColliding(enemy, indexOrder)) {
      return true
    }

    return false
  }
}

export class MagicIceballCollisionChecker {
  #magicCollisionChecker: MagicCollisionChecker
  #pathMovement: PathMovement
  constructor(
    magicCollisionChecker: MagicCollisionChecker,
    pathMovement: PathMovement,
  ) {
    this.#magicCollisionChecker = magicCollisionChecker
    this.#pathMovement = pathMovement
  }

  #checkCollision(magicIceball: MagicIceball, enemy: Enemy) {
    if (
      this.#magicCollisionChecker.shouldCollide(
        enemy,
        this.#pathMovement.indexOrder,
      )
    ) {
      this.handleCollision(magicIceball, enemy)
    }
  }

  check(magicIceball: MagicIceball, enemies: Enemy[]) {
    enemies.forEach((enemy) => {
      if (!enemy.isAbducted) {
        this.#checkCollision(magicIceball, enemy)
      }
    })
  }

  handleCollision(magicIceball: MagicIceball, enemy: Enemy) {
    magicIceball.freeze(enemy)
    this.#magicCollisionChecker.setToIgnoreList(enemy)
    ExplosionMagicIceball.instantiate(enemy.position)
  }
}

export class ProgressBar extends Obj {
  #size: Size
  #progress: number = 0
  #maxProgress: number

  constructor(position: Position, size: Size) {
    super(position)
    this.#size = { ...size }
    this.#maxProgress = this.#size.w - 1
  }

  get progress(): number {
    return this.#progress
  }

  reInitProgress() {
    this.#progress = 0
  }

  increaseProgress(increment: number = 1) {
    this.#progress += increment
    if (this.#progress > 100) {
      this.#progress = 100
    }
  }

  isFullOfProgress() {
    return this.#progress >= 100
  }

  #drawBackgroundBar() {
    P5.p5.strokeWeight(1)
    P5.p5.stroke('black')
    P5.p5.fill('green')
    P5.p5.rect(this.position.x, this.position.y, this.#size.w, this.#size.h)
  }

  #drawProgressBar() {
    P5.p5.strokeWeight(0)
    P5.p5.fill('red')
    const progressLevel = (this.#progress * this.#maxProgress) / 100
    P5.p5.rect(
      this.position.x + 1,
      this.position.y + 1,
      progressLevel,
      this.#size.h - 2,
    )
  }

  draw() {
    this.#drawBackgroundBar()
    if (this.#progress > 0) {
      this.#drawProgressBar()
    }
  }
}

export class StateManager {
  static STATE_MENU_MAIN = 0
  static STATE_MENU_SURVIVAL = 1
  static STATE_PLAY_SURVIVAL = 2
  static STATE_PLAY_SURVIVAL_PAUSE = 3
  static STATE_PLAY_SURVIVAL_GAME_OVER = 4

  static #instance: StateManager | null = null
  #state: number
  constructor(initialState: number) {
    if (StateManager.#instance !== null) {
      throw new Error(
        'StateManager is a singleton class, use getInstance to get the instance',
      )
    }
    this.#state = initialState

    // assign the singleton instance
    StateManager.#instance = this
  }

  static getInstance(initialState: number) {
    if (StateManager.#instance === null) {
      StateManager.#instance = new StateManager(initialState)
    }
    return StateManager.#instance
  }

  setPlay() {
    this.#state = StateManager.STATE_PLAY_SURVIVAL
  }

  setMenuSurvival() {
    this.#state = StateManager.STATE_MENU_SURVIVAL
  }

  setMenuMain() {
    this.#state = StateManager.STATE_MENU_MAIN
  }

  setPause() {
    this.#state = StateManager.STATE_PLAY_SURVIVAL_PAUSE
  }

  setGameOver() {
    this.#state = StateManager.STATE_PLAY_SURVIVAL_GAME_OVER
  }

  isPlaying() {
    return this.#state === StateManager.STATE_PLAY_SURVIVAL
  }

  isGameOver() {
    return this.#state === StateManager.STATE_PLAY_SURVIVAL_GAME_OVER
  }

  isPaused() {
