export class PerfectMemory extends Memory {
  constructor() {
    super();
  }

  /**
   * Will memorize all cards
   * @param {PlayedCard} playedCard - The card and the player who has played it
   * @param {string} trickId - The trick Identifier the card was played in
   */
  memorize(playedCard: PlayedCard, trickId?: string) {
    this.memorizedCards.push({ playedCard, trickId });
  }
}

export function playableCards(cards: Array<Card>, baseCard?: Card) {
  if (!baseCard) {
    return cards;
  }

  if (!baseCard.isTrump()) {
    const matchingNonTrumps = cards
      .filter((card) => card.suit === baseCard.suit)
      .filter((card) => !card.isTrump());
    return matchingNonTrumps.length > 0 ? matchingNonTrumps : cards;
  }

  const trumps = cards.filter((card) => card.isTrump());
  return trumps.length > 0 ? trumps : cards;
}

export class chanceAnnouncement implements announcementRules {
  announcementChance: number;

  constructor(chance: number) {
    this.announcementChance = chance;
  }

  announcementToMake(possibleAnnouncements: Set<Announcement>, hand?: Hand): Announcement | null {
    if (possibleAnnouncements.size === 0) {
      return null;
    }

    if (chance(this.announcementChance)) {
      return [...possibleAnnouncements][0];
    }

    return null;
  }
}

export class PercentageMemory extends Memory {
