}

export class PriorityMemory extends Memory {
  constructor() {
    super();
  }

  /**
   * Opinionated function to memorize 'important' cards.
   * Will memorize by value. Only memorizes Queens, Tens, Aces
   * @param {PlayedCard} playedCard - The card and the player who has played it
   * @param {string} trickId - The trick Identifier the card was played in
   */
  memorize(playedCard: PlayedCard, trickId?: string) {
    if ([3, 10, 11].includes(playedCard.card.value))
      this.memorizedCards.push({ playedCard, trickId });
  }
}

export function findGameType(players: RingQueue<Player>): GameType | undefined {
  const gameTypeCandidates = players.asList().map((p) => new GameType(p.reservation, p));

  const missingReservations = gameTypeCandidates.find((c) => c.reservation === Reservation.None);
  if (missingReservations) {
    return undefined;
  }

  const solos = gameTypeCandidates.filter((c) => !nonSoloTypes.includes(c.reservation));

  if (solos.length > 0) {
    return solos[0];
  }

  const wedding = gameTypeCandidates.find((c) => c.reservation === Reservation.Wedding);

  return wedding || GameType.normalGame();
}

export class TrickStack {
  tricks: Trick[];

  constructor(tricks: Trick[] = []) {
    this.tricks = tricks;
  }

  add(trick: Trick) {
    if (!trick.isFinished()) {
      throw new Error("can not add an unfinished trick to the trick stack");
    }

    this.tricks.push(trick);
  }

  cards() {
    const playedCards = this.tricks.flatMap((trick) => trick.playedCards);
    return playedCards.map((playedCard) => playedCard.card);
  }

  points() {
    return this.tricks.reduce((acc, trick) => acc + trick.points(), 0);
  }

  extras() {
    return this.tricks
      .reduce((acc, trick) => acc.concat(trick.extras()), new Array<Extra>())
      .flat();
  }
}

export class ScoreBuilder {
  extras: { [party in PartyName]: Extra[] }
  points: { [party in PartyName]: number }
  winningParty?: Party
  losingParty?: Party

  constructor() {
    this.extras = { [PartyName.Re]: [], [PartyName.Kontra]: [] }
    this.points = { [PartyName.Re]: 0, [PartyName.Kontra]: 0 }
  }

  withWinners(partyName: PartyName, ...players: Player[]) {
    this.winningParty = new Party(partyName, ...players)
    return this
  }

  withLosers(partyName: PartyName, ...players: Player[]) {
    this.losingParty = new Party(partyName, ...players)
    return this
  }

  withPoints(points: number) {
    this.points[PartyName.Re] = points
    this.points[PartyName.Kontra] = -points
    return this
  }

  withRePoints(points: number) {
    this.points[PartyName.Re] = points
    return this
  }

  withKontraPoints(points: number) {
    this.points[PartyName.Kontra] = points
    return this
  }

  withReExtras(extras: Extra[]) {
    this.extras[PartyName.Re] = extras
    return this
  }

  withKontraExtras(extras: Extra[]) {
    this.extras[PartyName.Kontra] = extras
    return this
  }

  build() {
    if (this.winningParty) {
      this.winningParty.points = () => 130
    }

    if (this.losingParty) {
      this.losingParty.points = () => 110
    }

    const score = new Score(this.winningParty!, this.losingParty!)
    score.winningPartyName = () => this.winningParty!.name
    score.winner = () => this.winningParty
    score.totalPoints = (partyName) => this.points[partyName]
    score.listExtras = (partyName) => this.extras[partyName]
    return score
  }
}

export class Card {
  id: number;
  rank: Rank;
  suit: Suit;

  constructor(rank: Rank, suit = Suit.Clubs, id = 0) {
    this.rank = rank;
    this.suit = suit;
    this.id = id;
  }

  get value() {
    return values[this.rank];
  }

  get cardId() {
    return `${this.rank}-${this.suit}-${this.id}`;
  }

  of(suit: Suit) {
    return new Card(this.rank, suit);
  }

  first() {
    return new Card(this.rank, this.suit, 0);
  }

  second() {
    return new Card(this.rank, this.suit, 1);
  }

  isTrump() {
    return trumps.some((c) => c.is(this));
  }

  beats(anotherCard: Card | undefined) {
    if (!anotherCard) {
      return false;
    }

    return this.compareTo(anotherCard) < 0;
  }

  compareTo(anotherCard: Card) {
    const thisIsTrump = this.isTrump();
    const otherCardIsTrump = anotherCard.isTrump();

    if (thisIsTrump && !otherCardIsTrump) {
      return -1;
    }

    if (!thisIsTrump && otherCardIsTrump) {
      return 1;
    }

    if (thisIsTrump && otherCardIsTrump) {
      return trumps.findIndex((c) => c.is(this)) - trumps.findIndex((c) => c.is(anotherCard));
    }

    if (!thisIsTrump && !otherCardIsTrump) {
      if (this.suit === anotherCard.suit) {
        return anotherCard.value - this.value;
      }
    }

    return 0;
  }

  equals(anotherCard: Card | undefined) {
    if (!anotherCard) {
      return false;
    }

    return (
      this.rank == anotherCard.rank && this.suit == anotherCard.suit && this.id == anotherCard.id
    );
  }

  is(anotherCard: Card) {
    return this.rank === anotherCard.rank && this.suit === anotherCard.suit;
  }
}

export default class Block extends BaseTower {
  constructor(opt: any) {
    super(opt);
    this.type = 'BLOCK';
  }

  draw() {
    const ctx = this.ctx;

    ctx.save();

    ctx.strokeStyle = 'greenyellow';
    ctx.lineWidth = 1;
    ctx.beginPath();
    const halfSize = GRID_SIZE / 2;
    ctx.moveTo(this.x - halfSize, this.y - halfSize);
    ctx.lineTo(this.x + halfSize, this.y + halfSize);
    ctx.moveTo(this.x + halfSize, this.y - halfSize);
    ctx.lineTo(this.x - halfSize, this.y + halfSize);

    ctx.stroke();

    ctx.restore();
  }
}

