class SlowTower extends BaseTower {
  shooting: boolean;
  ratio: number;
  bullets: SlowField[];

  constructor(opt: Option) {
    super(opt);

    this.type = 'SLOW';
    this.hue = 120;
    this.cost = towerData[this.type].cost;

    this.range = 2.5 * gridWidth;

    this.shooting = false;
    this.ratio = 0.3;
  }

  shoot() {
    const slowField = new SlowField({
      id: globalId.genId(),
      ctx: this.ctx,
      range: this.range,
      ratio: this.ratio,
      parent: this,
    });
    this.bullets.push(slowField);
  }

  draw() {
    const ctx = this.ctx;
    ctx.save();
    // 在选中的情况下，画出其射程范围
    if (this.selected) {
      ctx.beginPath();
      ctx.fillStyle = 'rgba(200, 200, 200, 0.3)';
      ctx.arc(this.x, this.y, this.range, 0, 2 * Math.PI);
      ctx.fill();
    }

    ctx.strokeStyle = 'hsl(' + this.hue + ',100%, 80%';
    // ctx.fillStyle = 'hsl(' + this.hue + ',100%, 80%';
    ctx.fillStyle = 'rgba(1, 158, 213, 0.15)';
    ctx.lineWidth = Math.max(3, this.radius / 8);

    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, 2 * Math.PI);
    ctx.closePath();
    ctx.stroke();
    ctx.fill();

    if (this.targetIndex !== -1 && !this.shooting) {
      this.shoot();
      this.shooting = true;
    }

    ctx.restore();
  }
}

export default class CircleBullet extends BaseBullet {
  type: BULLET_TYPE;
  x: number;
  y: number;
  ctx: CanvasRenderingContext2D;
  target: Enemy;
  radius: number;
  speed: number;
  vx: number;
  vy: number;
  angle: number;
  hue: number;
  range: number;
  damage: number;

  constructor({ id, ctx, x, y, target, range, damage, parent }: IBulletOption) {
    super({ ctx, x, y, damage, id, parent })
    this.type = BULLETS.CIRCLE;
    this.target = target;
    this.radius = 3;
    this.speed = 5;
    this.vx = 0;
    this.vy = 0;
    this.angle = 0;
    this.hue = 200;
    this.range = range;
  }

  step(enemies: EntityCollection<Enemy>) {
    // 计算新位置

    if (this.target) {
      const target = enemies.getElementById(this.target.id);
      if (target) {
        const curDis = calculateDistance(target.x, target.y, this.x, this.y);
        if (curDis < this.range) {
          const dx = target.x - this.x;
          const dy = target.y - this.y;
          this.angle = Math.atan2(dy, dx);
        }
      }
    }
    this.vx = Math.cos(this.angle) * this.speed;
    this.vy = Math.sin(this.angle) * this.speed;

    this.x += this.vx;
    this.y += this.vy;
  }

  draw(ctx: CanvasRenderingContext2D, enemies: EntityCollection<Enemy>) {
    this.step(enemies);

    // 绘图开始
    ctx.save();
    ctx.strokeStyle = 'hsl(' + this.hue + ', 100%, 40%)';
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.restore();
  }
}

class TowerArea implements TowerAreaOption {
  constructor(opt: TowerAreaOption) {
    this.ctx = opt.ctx;
    this.selected = -1;
    this.offsetX = opt.x;
    this.offsetY = opt.y;

    const bulletTower = new BulletTower({
      x: this.offsetX + GRID_WIDTH / 2 + 10,
      y: this.offsetY + GRID_HEIGHT / 2,
      ctx: this.ctx,
      radius: 12,
    });

    const laserTower = new LaserTower({
      x: this.offsetX + GRID_WIDTH * 1.5 + 5,
      y: this.offsetY + GRID_HEIGHT / 2,
      ctx: this.ctx,
      direction: 90,
      radius: 10,
    });

    const slowTower = new SlowTower({
      x: this.offsetX + GRID_WIDTH * 2.5 + 5,
      y: this.offsetY + GRID_HEIGHT / 2,
      ctx: this.ctx,
      radius: 12,
    });

    const fireTower = new FireTower({
      x: this.offsetX + GRID_WIDTH / 2 + 5,
      y: this.offsetY + GRID_HEIGHT * 1.5,
      ctx: this.ctx,
      radius: 10,
    });

    const block = new Block({
      x: this.offsetX + GRID_WIDTH * 2.5,
      y: this.offsetY + GRID_HEIGHT * 1.5,
      ctx: this.ctx,
      radius: 0,
    });

    this.towers = {
      BULLET: bulletTower,
      LASER: laserTower,
      SLOW: slowTower,
      FIRE: fireTower,
      BLOCK: block,
    };
  }

  draw() {
    const ctx = this.ctx;
    ctx.strokeStyle = FILL_COLOR;
    ctx.lineWidth = 1;

    drawGrid(
      ctx,
      GRID_NUM_X,
      GRID_NUM_Y,
      GRID_WIDTH,
      FILL_COLOR,
      this.offsetX,
      this.offsetY
    );

    if (this.selected !== -1) {
      this.highlightTower(this.selected[0], this.selected[1]);
    }

    Object.keys(this.towers).forEach((key) => {
      this.towers[key].draw(ctx);
    });
  }

  highlightTower(col: number, row: number) {
    const x = col * GRID_WIDTH + this.offsetX;
    const y = row * GRID_HEIGHT + this.offsetY;
    highlightGrid(this.ctx, x, y, GRID_WIDTH, GRID_HEIGHT);
  }
}

export default class BootScene extends Phaser.Scene {

  private progressBar?: Phaser.GameObjects.Graphics;
  private progressBgRect?: Phaser.Geom.Rectangle;
  private progressRect?: Phaser.Geom.Rectangle;

  constructor() {
    super('boot');
  }

  public preload() {
    this.load.on('progress', this.onLoadProgress, this);
    this.load.on('complete', this.onLoadComplete, this);
    this.createProgressBar();
  }

  public create() {
    // this.registry.set('score', 0);
    // this.scene.start('menu');
    this.scene.start('game');
  }

  // extend:

  public createProgressBar() {
    const main = this.cameras.main;
    this.progressBgRect = new Rectangle(0, 0, 0.5 * main.width, 50);
    Rectangle.CenterOn(this.progressBgRect, 0.5 * main.width, 0.5 * main.height);
    this.progressRect = Rectangle.Clone(this.progressBgRect);
    this.progressBar = this.add.graphics();
  }

  public onLoadComplete(loader: any, totalComplete: number, totalFailed: number) {
    // console.debug('complete', totalComplete);
    // console.debug('failed', totalFailed);
    if (!this.progressBar) { return; }
    this.progressBar.destroy();
  }

  public onLoadProgress(progress: number) {
    // console.debug('progress', progress);
    if (!this.progressBar ||
        !this.progressBgRect ||
        !this.progressRect) { return; }

    const { darkGray, red, white } = hexColors;

    this.progressRect.width = progress * this.progressBgRect.width;
    this.progressBar
      .clear()
      .fillStyle(darkGray)
      .fillRectShape(this.progressBgRect)
      .fillStyle(this.load.totalFailed ? red : white)
      .fillRectShape(this.progressRect);
  }
}

export function loadAutosave(): GameState | null {
  const raw = localStorage.getItem(AUTOSAVE_KEY);
  if (raw === null) return null;

  const envelope = parseAndValidateEnvelope(raw);
  return envelope.state;
}

export function getTerrainModifier(terrain: string): number {
  switch (terrain) {
    case 'Mountain': return 5;
    case 'Forest': return 3;
    case 'Desert': return 1;
    case 'Coastal': return 0;
    case 'Plains': return 0;
    default: return 0;
  }
}

function isBorderProvince(provinceId: string, nationId: string, state: GameState): boolean {
  return getAdjacentProvinceIds(provinceId, state).some((adjId) => {
    const adj = state.provinces.find((p) => p.id === adjId);
    return adj && adj.ownerId !== nationId;
  });
}

function createSeededRng(seed: number): () => number {
  let s = seed | 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function autosave(state: GameState): void {
  const envelope: SaveEnvelope = {
    version: SAVE_VERSION,
    savedAt: new Date().toISOString(),
    scenarioId: state.scenario.meta.id,
    turn: state.turn,
    state,
  };
  localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(envelope));
}

function getOrderCategory(order: Order): 'diplomatic' | 'military' | 'construction' | 'wildcard' {
  switch (order.type) {
    case 'propose_agreement':
    case 'break_agreement':
    case 'declare_war':
    case 'offer_peace':
      return 'diplomatic';
    case 'move_army':
    case 'retreat':
    case 'blockade':
      return 'military';
    case 'upgrade_dev':
    case 'set_focus':
    case 'build_fort':
      return 'construction';
    case 'spy':
    case 'restore_nation':
    case 'hire_mercenaries':
      return 'wildcard';
  }
}

export function importSave(file: File): Promise<GameState> {
  return new Promise((resolve, reject) => {
    if (!file.name.endsWith('.json')) {
      reject(new PersistenceError('File must be a .json file'));
      return;
    }

    const reader = new FileReader();

    reader.onload = () => {
      try {
        const raw = reader.result as string;
        const envelope = parseAndValidateEnvelope(raw);
        resolve(envelope.state);
      } catch (err) {
        reject(err instanceof PersistenceError ? err : new PersistenceError('Failed to read save file'));
      }
    };

    reader.onerror = () => {
      reject(new PersistenceError('Failed to read file'));
    };

    reader.readAsText(file);
  });
}

export function runBookkeeping(
  nation: Nation,
  state: GameState
): ResourceLedger {
  const { provinces, edges, armies, scenario, nations } = state;
  const income = getNationIncome(nation.id, provinces, scenario);
  const foodConsumption = getArmyFoodConsumption(nation.id, armies);
  const tradeBonus = getTradeDealBonus(nation.id, edges, provinces);
  const tribute = getVassalTribute(nation.id, nations);
  const influenceCap = getInfluenceSoftCap(nation);
  const manpowerCap = getManpowerSoftCap(nation.id, provinces);

  let gold = nation.resources.gold + income.gold + tradeBonus + tribute.gold;
  let food = nation.resources.food + income.food - foodConsumption;
  let production = nation.resources.production + income.production + tribute.production;
  let influence = nation.resources.influence + income.influence;
  let manpower = nation.resources.manpower + income.manpower;

  // Influence decay: if over cap, decay 10% of excess per turn
  if (influence > influenceCap) {
    const excess = influence - influenceCap;
    influence -= Math.ceil(excess * 0.1);
  }

  // Manpower soft cap: don't accumulate above cap
  if (manpower > manpowerCap) {
    manpower = manpowerCap;
  }

  return { gold, food, production, influence, manpower };
}

function validateEdge(e: unknown, index: number, provinceIds: Set<string>, errors: string[]): e is Edge {
  const prefix = `world.edges[${index}]`;
  if (!isObject(e)) {
    errors.push(`${prefix}: must be an object`);
    return false;
  }

  if (!isString(e.sourceId)) {
    errors.push(`${prefix}.sourceId: must be a string`);
  } else if (!provinceIds.has(e.sourceId)) {
    errors.push(`${prefix}.sourceId: "${e.sourceId}" does not reference a valid province`);
  }

  if (!isString(e.targetId)) {
    errors.push(`${prefix}.targetId: must be a string`);
  } else if (!provinceIds.has(e.targetId)) {
    errors.push(`${prefix}.targetId: "${e.targetId}" does not reference a valid province`);
  }

  if (isString(e.sourceId) && isString(e.targetId) && e.sourceId === e.targetId) {
    errors.push(`${prefix}: sourceId and targetId cannot be the same`);
  }

  if (!isNumber(e.movementCost) || e.movementCost < 1) {
    errors.push(`${prefix}.movementCost: must be a positive number`);
  }
  if (!isNumber(e.tradeValue) || e.tradeValue < 0) {
    errors.push(`${prefix}.tradeValue: must be a non-negative number`);
  }
  if (typeof e.chokepoint !== 'boolean') {
    errors.push(`${prefix}.chokepoint: must be a boolean`);
  }
  if (typeof e.tradeActive !== 'boolean') {
    errors.push(`${prefix}.tradeActive: must be a boolean`);
  }

  return true;
}

function validateMeta(meta: unknown, errors: string[]): meta is ScenarioMeta {
  if (!isObject(meta)) {
    errors.push('meta: must be an object');
    return false;
  }

  if (!isString(meta.id) || meta.id.length === 0) errors.push('meta.id: must be a non-empty string');
  if (!isString(meta.name) || meta.name.length === 0) errors.push('meta.name: must be a non-empty string');
  if (!isString(meta.description)) errors.push('meta.description: must be a string');
  if (!isNumber(meta.turnLimit) || meta.turnLimit < 1) errors.push('meta.turnLimit: must be a positive number');
  if (!isNumber(meta.exileWindowTurns) || meta.exileWindowTurns < 0) errors.push('meta.exileWindowTurns: must be a non-negative number');
  if (!isNumber(meta.exileRestoreCost) || meta.exileRestoreCost < 0) errors.push('meta.exileRestoreCost: must be a non-negative number');
  if (!isNumber(meta.siegeTurns) || meta.siegeTurns < 1) errors.push('meta.siegeTurns: must be a positive number');
  if (!isNumber(meta.relationDecayPerTurn) || meta.relationDecayPerTurn < 0) errors.push('meta.relationDecayPerTurn: must be a non-negative number');

  if (meta.majorBattleThreshold !== undefined && !isNumber(meta.majorBattleThreshold)) {
    errors.push('meta.majorBattleThreshold: must be a number if provided');
  }

  validateVictoryConditions(meta.victoryConditions, errors);

  if (meta.developmentOutputTable !== undefined) {
    validateDevelopmentOutputTable(meta.developmentOutputTable, errors);
  }

  return true;
}

