export function initializeGameState(scenario: Scenario): GameState {
  const nationIds = scenario.nations.map((n) => n.id);
  const relationsMap = buildRelations(nationIds, scenario.startingState.relations);

  // Build Nation objects from NationDefinition + starting state
  const nations: Nation[] = scenario.nations.map((def) => ({
    id: def.id,
    name: def.name,
    color: def.color,
    archetype: def.archetype,
    modifiers: def.modifiers,
    agenda: def.agenda,
    utilityWeights: ARCHETYPE_WEIGHTS[def.archetype],
    resources: scenario.startingState.resources[def.id] ?? {
      gold: 0,
      food: 0,
      production: 0,
      influence: 0,
      manpower: 0,
    },
    relations: relationsMap[def.id] ?? {},
    agreements: {},
    intelOf: buildIntelOf(
      def.id,
      nationIds,
      scenario.startingState.provinceOwnership,
      scenario.world.edges
    ),
  }));

  // Apply province ownership from starting state
  const provinces = scenario.world.provinces.map((p) => ({
    ...p,
    ownerId: scenario.startingState.provinceOwnership[p.id] ?? p.ownerId,
  }));

  // Build armies with siegeTurns initialized to 0
  const armies: Army[] = scenario.startingState.armies.map((a) => ({
    id: a.id,
    type: a.type,
    strength: a.strength,
    provinceId: a.provinceId,
    ownerId: a.ownerId,
    siegeTurns: 0,
  }));

  return {
    scenario,
    turn: 1,
    provinces,
    edges: [...scenario.world.edges],
    nations,
    armies,
    wars: [],
    turnLogs: [],
    eliminationLog: [],
    winner: null,
    gameOver: false,
  };
}

function parseAndValidateEnvelope(raw: string): SaveEnvelope {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new PersistenceError('Save data is not valid JSON');
  }

  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new PersistenceError('Save data must be a JSON object');
  }

  const obj = parsed as Record<string, unknown>;

  if (typeof obj.version !== 'number') {
    throw new PersistenceError('Save data missing version field');
  }

  if (obj.version > SAVE_VERSION) {
    throw new PersistenceError(
      `Save version ${obj.version} is newer than supported version ${SAVE_VERSION}`
    );
  }

  if (typeof obj.savedAt !== 'string') {
    throw new PersistenceError('Save data missing savedAt field');
  }

  if (typeof obj.scenarioId !== 'string') {
    throw new PersistenceError('Save data missing scenarioId field');
  }

  if (typeof obj.turn !== 'number' || obj.turn < 0) {
    throw new PersistenceError('Save data has invalid turn number');
  }

  if (obj.state === null || typeof obj.state !== 'object' || Array.isArray(obj.state)) {
    throw new PersistenceError('Save data missing or invalid state object');
  }

  const state = obj.state as Record<string, unknown>;

  // Validate essential GameState shape
  if (typeof state.turn !== 'number') {
    throw new PersistenceError('GameState missing turn field');
  }
  if (!Array.isArray(state.provinces)) {
    throw new PersistenceError('GameState missing provinces array');
  }
  if (!Array.isArray(state.edges)) {
    throw new PersistenceError('GameState missing edges array');
  }
  if (!Array.isArray(state.nations)) {
    throw new PersistenceError('GameState missing nations array');
  }
  if (!Array.isArray(state.armies)) {
    throw new PersistenceError('GameState missing armies array');
  }
  if (!Array.isArray(state.wars)) {
    throw new PersistenceError('GameState missing wars array');
  }
  if (!Array.isArray(state.turnLogs)) {
    throw new PersistenceError('GameState missing turnLogs array');
  }
  if (!Array.isArray(state.eliminationLog)) {
    throw new PersistenceError('GameState missing eliminationLog array');
  }
  if (state.scenario === null || typeof state.scenario !== 'object') {
    throw new PersistenceError('GameState missing scenario object');
  }
  if (typeof state.gameOver !== 'boolean') {
    throw new PersistenceError('GameState missing gameOver field');
  }

  return obj as unknown as SaveEnvelope;
}

export function card(code: string): SideCard {
  const c = BY_CODE.get(code);
  if (!c) throw new Error(`unknown card code ${code}`);
  return c;
}

export function familyForCode(code: string): string {
  if (code.startsWith('±')) return 'flip';
  return code.startsWith('-') ? 'minus' : 'plus';
}

export function loadCustomDeckCodes(): string[] | null {
  try {
    const raw = localStorage.getItem(CUSTOM_DECK_STORAGE_KEY);
    return raw ? normalizeDeckCodes(JSON.parse(raw)) : null;
  } catch {
    return null;
  }
}

export function backIntentForRoute(route: Route): BackIntent {
  if (isGameRoute(route)) return { type: 'forfeit', target: forfeitTargetForRoute(route) };
  const parent = parentRouteForRoute(route);
  return parent ? { type: 'navigate', target: parent } : { type: 'exit' };
}

export function normalizeDeckCodes(value: unknown): string[] | null {
  if (!Array.isArray(value) || value.length !== SIDE_DECK_SIZE) return null;
  const codes = value.map((item) => (typeof item === 'string' ? item : ''));
  return codes.every((code) => VALID_CODES.has(code)) ? codes : null;
}

export function cardArt(label: string, family: string): string {
  if (family === 'flip') {
    return label.startsWith('-') ? `${CARD_BASE}/pcards_dblneg_p.png` : `${CARD_BASE}/pcards_dblpos_p.png`;
  }
  if (family === 'main' || /^\d+$/.test(label)) return `${CARD_BASE}/pcards_generic_p.png`;
  if (label.startsWith('-')) return `${CARD_BASE}/pcards_neg_p.png`;
  return `${CARD_BASE}/pcards_pos_p.png`;
}

export function installClickSound(): () => void {
  if (typeof window === 'undefined') return () => {};
  const prime = () => primeUiSounds();
  window.addEventListener('pointerdown', prime, { once: true });

  const onClick = (e: MouseEvent) => {
    const el = (e.target as HTMLElement | null)?.closest('button, a, [role="button"]');
    if (!el || el.hasAttribute('disabled') || el.closest('[data-no-click-sound]')) return;
    playClick();
  };
  window.addEventListener('click', onClick, true);

  return () => {
    window.removeEventListener('pointerdown', prime);
    window.removeEventListener('click', onClick, true);
  };
}

export function useLobbyAnnouncer(roomId: string, hostName: string, active: boolean) {
  useEffect(() => {
    if (!active) return;

    const room = createRoom(LOBBY_ROOM_ID);
    const [sendAnnounce] = room.makeAction('announce') as unknown as [(m: LobbyAnnounceMessage, target?: string) => Promise<unknown>, unknown];


    const announceAll = () => {
      void sendAnnounce({ roomId, hostName });
    };


    room.onPeerJoin((peerId) => {
      void sendAnnounce({ roomId, hostName }, peerId);
    });


    const delay = setTimeout(announceAll, 1000);

    return () => {
      clearTimeout(delay);
      void room.leave();
    };
  }, [roomId, hostName, active]);
}

export class Die extends BaseState {
	constructor(stateMachine) {
		super(stateMachine);

		managers.get('stageManager').gameOver('lose');
	}
}

export class BaseState {
	stateMachine = $state();

	constructor(stateMachine) {
		this.stateMachine = stateMachine;
	}

	update(deltaTime: number, entity) {}

	get name() {
		return this.constructor.name;
	}

	get entity() {
		return this.stateMachine.owner;
	}
}

export function normalizeVector(current: Vector2, target: Vector2): Vector2 {
	const dx = target.x - current.x;
	const dy = target.y - current.y;
	const distance = Math.sqrt(dx * dx + dy * dy);
	return distance ? new Vector2(dx / distance, dy / distance) : new Vector2(0, 0);
}

export class Managers {
	managers = $state({});

	setup = (managers: any) => {
		this.managers = managers;
	};

	update = (deltaTime: number) => {
		this.managers.stageManager.update(deltaTime);
		this.managers.entityManager.update(deltaTime);
		this.managers.collisionManager.update();
	};

	get = (name: string | string[]) => {
		if (typeof name === 'string') {
			return this.managers[name];
		}
		return name.reduce((acc, n) => {
			acc[n] = this.managers[n];
			return acc;
		}, {});
	};
}

export class StateMachine {
	currentState = $state();
	context = $state();

	constructor({ owner, initialState, onEnter, context = {} }) {
		this.owner = owner;
		this.onEnter = onEnter;
		this.context = context;

		this.onEnter(initialState);
		this.currentState = initState(this, owner.type, initialState, context);
	}

	update(deltaTime, entityManager) {
		this.currentState.update(deltaTime, this.owner, entityManager);
	}

	setState(name, stateContext = {}) {
		if (name === this.currentState.name) return;

		this.onEnter(name);
		this.context = { ...this.context, ...stateContext };
		this.currentState = initState(this, this.owner.type, name, stateContext);
	}
}

export class Game {
	isStarted = $state(false);

	update = async (deltaTime) => {
		managers.update(deltaTime);
		cursor.update(deltaTime);
	};

	start = async () => {
		managers.setup(setupManagers());

		const { gameLoop, stageManager } = managers.get(['gameLoop', 'stageManager']);

		stageManager.init();

		gameLoop.start(this.update);

		soundManager.play('bgSound');

		this.isStarted = true;
	};

	restart = () => {
		const { entityManager, gameLoop, stageManager } = managers.get([
			'entityManager',
			'gameLoop',
			'stageManager'
		]);

		gameLoop.reset();
		entityManager.reset();
		stageManager.reset();
		soundManager.reset();
		lootTracker.reset();

		gameLoop.resume();
	};
}

export class Cursor {
	animation = $state<Animation>();

	arrow = $derived(`url(${cursors.arrow}), auto`);
	hammer = $derived(`url(${cursors.hammer}), auto`);

	inAnimation = $derived(this.animation && !this.animation.isComplete);
	currentFrame = $derived(this.getCurrentFrame());

	update(deltaTime: number) {
		if (this.inAnimation) {
			this.animation.update(deltaTime);
		}
	}

	get(name) {
		if (this.inAnimation) {
			return this.currentFrame;
		} else {
			return this[name];
		}
	}

	setAnimation(animation: string) {
		if (!animation) {
			this.animation = null;
			return;
		}

		const animationConfig = getAnimation(animation);

		this.animation = new Animation({ ...animationConfig });
	}

	getCurrentFrame() {
		const { frames } = getAnimation(this.animation.name);
		return `url(${frames[this.animation.currentFrame]}), auto`;
	}
}

function getRotatedRectVertices(rect: Rect2D, angleInDegrees: number): Vector2[] {
	const centerX = (rect.x1 + rect.x2) / 2;
	const centerY = (rect.y1 + rect.y2) / 2;
	const width = rect.x2 - rect.x1;
	const height = rect.y2 - rect.y1;

	// We already have angleToTarget for radians conversion
	const angle = angleToTarget(
		new Vector2(0, 0),
		new Vector2(
			Math.cos((angleInDegrees * Math.PI) / 180),
			Math.sin((angleInDegrees * Math.PI) / 180)
		)
	);

	// We already have getDirectionFromAngle
	const direction = getDirectionFromAngle(angle);

	// Calculate vertices using existing Vector2 class
	return [
		new Vector2(-width / 2, -height / 2),
		new Vector2(width / 2, -height / 2),
		new Vector2(width / 2, height / 2),
		new Vector2(-width / 2, height / 2)
	].map((v) => {
		// Rotate using direction vector
		return new Vector2(
			v.x * direction.x - v.y * direction.y + centerX,
			v.x * direction.y + v.y * direction.x + centerY
		);
	});
}

export class Animation {
	name: string;
	framesAmount = $state(0);
	frameRate = $state(0);
	loop = $state(false);
	currentFrame = $state(0);
	currentFrameTime = $state(0);
	isComplete = $derived(this.getIsAnimationComplete());
	onFrameChange = $state(() => {});

	constructor({ name, framesAmount, frameRate, loop = false }: AnimationConfig) {
		this.name = name;
		this.framesAmount = framesAmount;
		this.frameRate = frameRate;
		this.loop = loop;
	}

	update(deltaTime: number) {
		if (this.frameRate === 0) return;

		this.currentFrameTime += deltaTime;

		if (this.currentFrameTime >= 1000 / this.frameRate) {
			this.currentFrameTime = 0;
			this.nextFrame();
		}
	}

	nextFrame() {
		this.onFrameChange(this.currentFrame);

		if (this.currentFrame >= this.framesAmount - 1) {
			if (this.loop) {
				this.currentFrame = 0;
			} else {
				this.currentFrame = this.framesAmount - 1;
			}
		} else {
			this.currentFrame += 1;
		}
	}

	getIsAnimationComplete(): boolean {
		if (this.loop) {
			return false;
		}
		return this.currentFrame === this.framesAmount - 1;
	}
}

export class Vector2 {
	x = $state(0);
	y = $state(0);

	constructor(x = 0, y = 0) {
		this.x = x;
		this.y = y;
	}

	clone(): Vector2 {
		return new Vector2(this.x, this.y);
	}

	isEqual(vector: Vector2): boolean {
		return this.x === vector.x && this.y === vector.y;
	}

	add(vector: Vector2): Vector2 {
		return new Vector2(this.x + vector.x, this.y + vector.y);
	}

	subtract(vector: Vector2): Vector2 {
		return new Vector2(this.x - vector.x, this.y - vector.y);
	}

	multiply(scalar: number): Vector2 {
		return new Vector2(this.x * scalar, this.y * scalar);
	}

	magnitude(): number {
		return Math.sqrt(this.x * this.x + this.y * this.y);
	}

	normalize(): Vector2 {
		const mag = this.magnitude();
		return mag ? new Vector2(this.x / mag, this.y / mag) : new Vector2();
	}

	distance(vector: Vector2): number {
		return this.subtract(vector).magnitude();
	}

	dot(vector: Vector2): number {
		return this.x * vector.x + this.y * vector.y;
	}

	rotate(angle: number): Vector2 {
		const cos = Math.cos(angle);
		const sin = Math.sin(angle);
		return new Vector2(this.x * cos - this.y * sin, this.x * sin + this.y * cos);
	}
}

export class Random {
  static integerBetween(min: number, max: number) {
    return Math.floor(Math.random() * (max - min + 1)) + min
  }
}

export class Distance {
  calculate(posA: Position, posB: Position) {
    return Math.sqrt(
      (posA.x - posB.x) * (posA.x - posB.x) +
        (posA.y - posB.y) * (posA.y - posB.y),
    )
  }
}

