export function sample<T>(array: Array<T>): T | undefined {
  if (array.length === 0) {
    return undefined;
  }

  return array[randomInt(array.length)];
}

export function findParties(players: Player[]) {
  return {
    [PartyName.Re]: new Party(PartyName.Re, ...players.filter((player) => player.isRe())),
    [PartyName.Kontra]: new Party(
      PartyName.Kontra,
      ...players.filter((player) => player.isKontra()),
    ),
  };
}

export function sampleSize<T>(array: Array<T>, n: number = 1): T[] {
  if (!array || array.length === 0 || n <= 0) {
    return [];
  }

  n = Math.min(n, array.length);

  const sampled = new Array<T>();
  const arrayCopy = [...array];

  while (sampled.length < n) {
    const randomIndex = randomInt(sampled.length);
    const pickedItem = arrayCopy.splice(randomIndex, 1)[0]; // mutates `arrayCopy` in place
    sampled.push(pickedItem);
  }

  return sampled.slice();
}

export class Party {
  name: PartyName;
  players: Player[];

  constructor(name: PartyName, ...players: Player[]) {
    this.name = name;
    this.players = players;
  }

  isPlayingSolo() {
    return this.players.length === 1;
  }

  points() {
    return this.players.reduce((acc, player) => acc + player.points(), 0);
  }

  announcements() {
    return this.players.flatMap((p) => [...p.announcements]);
  }

  extras() {
    return this.players.reduce(
      (acc, player) => acc.concat(player.trickStack.extras()),
      new Array<Extra>(),
    );
  }

  playerNames(): string {
    return this.players.map((player) => player.name).join(" & ");
  }
}

export class PlayerBuilder {
  name: string
  points: number = 0
  extras: Extra[] = []
  party: string = 're'
  id: string = uuidv4()

  constructor(name: string) {
    this.name = name
  }

  withPoints(points: number): PlayerBuilder {
    this.points = points
    return this
  }

  withParty(party: string): PlayerBuilder {
    this.party = party
    return this
  }

  withExtra(extra: Extra): PlayerBuilder {
    this.extras.push(extra)
    return this
  }

  withId(id: string): PlayerBuilder {
    this.id = id
    return this
  }

  build() {
    const player = new Player(this.name)
    player.isRe = () => this.party === PartyName.Re
    player.isKontra = () => this.party !== PartyName.Re
    player.points = () => this.points
    player.trickStack.extras = () => this.extras
    player.id = this.id
    return player
  }
}

export class PartyBuilder {
  party: PartyName;
  players: Player[];
  announcements: Set<Announcement>;
  extras: Extra[];
  points: number;

  constructor(party: PartyName) {
    this.party = party;
    this.players = [];
    this.announcements = new Set();
    this.extras = [];
    this.points = 0;
  }

  withPlayer(player: Player) {
    this.players.push(player);
    return this;
  }

  withAnnouncement(announcements: Announcement) {
    this.announcements.add(announcements);
    return this;
  }

  withExtra(extra: Extra) {
    this.extras.push(extra);
    return this;
  }

  withPoints(points: number) {
    this.points = points;
    return this;
  }

  build() {
    if (this.players.length === 0) {
      this.players = [
        new PlayerBuilder(`a ${this.party} player`).withParty(this.party).build(),
        new PlayerBuilder(`another ${this.party} player`).withParty(this.party).build(),
      ];
    } else {
      this.players.forEach((player) => {
        player.isRe = () => this.party === PartyName.Re;
      });
    }

    const createdParty = new Party(this.party, ...this.players);
    createdParty.announcements = () => [...this.announcements];
    createdParty.extras = () => this.extras;
    createdParty.points = () => this.points;

    return createdParty;
  }
}

function bulletOutOfBound(bullet: Bullet) {
  switch (bullet.type) {
    case 'circle':
      return (
        bullet.x < 0 || bullet.y < 0 || bullet.x > WIDTH || bullet.y > HEIGHT
      );

    case 'line':
      return (
        bullet.start[0] < 0 ||
        bullet.start[1] < 0 ||
        bullet.start[0] > WIDTH ||
        bullet.start[1] > HEIGHT
      );

    default:
      return false;
  }
}

class EntityCollection<T> extends Array {
  constructor() {
    super();
  }

  getElementById(id: number): T | null {
    for (let i = 0; i < this.length; i++) {
      if (this[i].id === id) {
        return this[i];
      }
    }
    return null;
  }

  removeElementById(id: number): T[] {
    let removed;
    for (let i = 0; i < this.length; i++) {
      if (this[i].id === id) {
        removed = this.splice(i, 1);
        break;
      }
    }
    return removed;
  }

  removeElementByIndex(idx: number): T[] {
    const removed = this.splice(idx, 1);
    return removed;
  }
}

class GameInfo implements Option {
  constructor(opt: Option) {
    this.element = opt.element;
    this.game = opt.game;

    this.element.width = WIDTH + GAME_CONTROL_WIDTH;
    this.element.height = HEIGHT;

    this.infos = [defaultInfo];

    this.count = 0;
  }

  draw() {
    setTimeout(() => this.draw(), 300);

    // 游戏未开始时，不显示提示信息
    if (this.game.status === '') {
      return;
    }

    const infos = this.infos;
    const ctx = this.element.getContext('2d');

    ctx.fillStyle = 'rgba(255, 255, 255, 0)';
    ctx.clearRect(0, 0, this.element.width, this.element.height);

    infos.forEach((info) => {
      // const rect = [info.x, info.y, info.width, info.height];
      ctx.font = '20px Arial';

      if (info.text && info.text.length > 0) {
        ctx.save();
        ctx.fillStyle = 'rgba(0, 255, 0, 0.4)';
        // 确定信息显示的位置
        const textStartX = info.x + WIDTH;
        // 确定信息的宽度
        // @ts-ignore why?
        const textWidth = ctx.measureText(info.text).width;
        // 画出信息显示时的背景
        ctx.fillRect(
          textStartX - 20,
          info.y - 25,
          textWidth + 40,
          30 * info.text.length
        );

        ctx.fillStyle = 'rgba(255, 255, 255, 1)';
        info.text.forEach((t: string, idx: number) => {
          const y = info.y + idx * 25;
          ctx.fillText(t, textStartX, y);
        });

        ctx.restore();
      }
    });
  }
}

export default class Bullet {
  type: BULLET_TYPE;
  x: number;
  y: number;
  directionVec: vec2;
  start: vec2;
  hue: number;
  velocity: vec2;
  length: number;
  bulletVec: vec2;
  end: vec2;
  damage: number;

  constructor({ ctx, x, y, directionVec, damage }: {
    ctx: CanvasRenderingContext2D,
    x: number;
    y: number;
    directionVec: vec2;
    damage: number;
  }) {
    this.type = BULLETS.LINE;
    this.x = x;
    this.y = y;
    this.directionVec = directionVec;

    // {vec2} this.start 表示起点位置的向量
    this.start = vec2.fromValues(x, y);

    this.hue = 200;

    // {vec2} this.velocity 表示bullet速度的向量
    // 将表示方向的单位向量乘以速率，得到速度向量
    this.velocity = vec2.create();
    vec2.scale(this.velocity, directionVec, 2);

    // bullet的长度
    this.length = 10;
    // 从bullet的起点指向终点的向量
    this.bulletVec = vec2.create();
    vec2.scale(this.bulletVec, directionVec, this.length);

    // {vec2} this.end 表示终点位置的向量
    this.end = vec2.create();
    this.end = vec2.add(this.end, this.start, this.bulletVec);

    this.damage = damage || 5;
  }

  draw(ctx: CanvasRenderingContext2D) {
    // bullet运动后的起点和终点位置
    vec2.add(this.start, this.start, this.velocity);
    vec2.add(this.end, this.end, this.velocity);

    // 绘图开始
    ctx.save();
    ctx.strokeStyle = 'hsl(' + this.hue + ', 100%, 80%)';
    ctx.beginPath();
    ctx.moveTo(this.start[0], this.start[1]);
    ctx.lineTo(this.end[0], this.end[1]);
    ctx.stroke();
    ctx.restore();
  }
}

