export function isGameRoute(route: Route): boolean {
  return (
    route.mode === 'quick-game' ||
    route.mode === 'campaign-game' ||
    route.mode === 'hotseat' ||
    route.mode === 'online'
  );
}

export function getSavedNickname(): string {
  if (typeof window === 'undefined') return 'HK-47';
  let name = localStorage.getItem(NICKNAME_KEY);
  if (!name || !name.trim()) {
    name = getRandomNickname();
    localStorage.setItem(NICKNAME_KEY, name);
  }
  return name;
}

function matchBannerText(
  t: (key: string, params?: Record<string, string | number>) => string,
  winner: Seat,
  mySeat: Seat | null,
): string {
  if (mySeat == null) {
    return t('player_wins_match', { player: winner + 1 });
  }
  return winner === mySeat ? t('you_win_match') : t('opponent_wins_match');
}

export function useNickname() {
  const [nickname, setNicknameState] = useState(getSavedNickname);

  const setNickname = useCallback((name: string) => {
    const val = name.slice(0, 20);
    localStorage.setItem(NICKNAME_KEY, val);
    setNicknameState(val);
  }, []);

  return [nickname, setNickname] as const;
}

export function useCopyToClipboard(): [boolean, (text: string) => void] {
  const [copied, setCopied] = useState(false);

  const copy = useCallback((text: string) => {
    void navigator.clipboard?.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }, []);

  return [copied, copy];
}

function ensureContext(): AudioContext | null {
  if (!enabled) return null;
  const Ctor = audioContextCtor();
  if (!Ctor) {
    enabled = false;
    return null;
  }
  if (!context) {
    try {
      context = new Ctor();
    } catch {
      enabled = false;
      return null;
    }
  }
  if (context.state === 'suspended') void context.resume();
  return context;
}

function primeUiSounds(): void {
  if (!enabled) return;
  const Ctor = audioContextCtor();
  if (!Ctor) {
    enabled = false;
    return;
  }
  if (!context) {
    try {
      context = new Ctor();
    } catch {
      enabled = false;
      return;
    }
    void (async () => {
      try {
        const res = await fetch(SRC);
        buffer = await context!.decodeAudioData(await res.arrayBuffer());
      } catch {
      }
    })();
  }
  if (context.state === 'suspended') void context.resume();
}

export function primePazaakSounds(): void {
  if (!enabled) return;
  const Ctor = audioContextCtor();
  if (!Ctor) {
    enabled = false;
    return;
  }
  if (!context) {
    try {
      context = new Ctor();
    } catch {
      enabled = false;
      return;
    }
    void Promise.all(
      (Object.keys(SOURCES) as PazaakSound[]).map(async (name) => {
        try {
          const response = await fetch(SOURCES[name]);
          buffers.set(name, await context!.decodeAudioData(await response.arrayBuffer()));
        } catch {
        }
      }),
    );
  }
  if (context.state === 'suspended') void context.resume();
}
